// ------------------------------------------------------------
// kcmu_mcu.sv
// MCU contains:
// - Decoder
// - Prefetcher
// - Execute (includes policy calls)
// - RW ctrl + SRAM inside MCU
// External memory interface is exposed to top level.
// ------------------------------------------------------------
module kcmu_l2_ctrl #(
  parameter integer ADDR_W = 8,
  parameter integer DATA_W = 32,
  parameter integer SCORE_W = 8,
  parameter integer L1_LINES = 16,
  parameter integer L2_LINES = 16,
  parameter integer L2_WAYS = 1,
  parameter integer VB_LINES = 2,
  parameter bit     VB_ENABLE = 1'b1,
  parameter bit     VB_CLEAN_READONLY_EN = 1'b0,
  parameter bit     VB_CLEAN_ATTNAWARE_ADMIT_EN = 1'b0,
  parameter bit     GROUP_FETCH_TO_CVR_EN = 1'b0,
  parameter integer GROUP_FETCH_ADDR_STRIDE = 2,
  parameter integer GROUP_BUF_LINES = 4,
  parameter bit     WRITE_ALLOCATE = 1'b1,
  parameter bit     WRITE_THROUGH_EN = 1'b1,
  parameter bit     BG_DIRTY_FLUSH_EN = 1'b1,
  parameter logic [2:0] WRITE_ALLOC_QOS_TH = 3'd2,
  parameter logic [2:0] READ_FILL_QOS_TH = 3'd1,
  parameter logic [2:0] PREFETCH_FILL_QOS_TH = 3'd3,
  parameter bit     SEM_HOT_FILL_RELAX_EN = 1'b1,
  parameter bit     SEM_HOT_VICTIM_PROTECT_EN = 1'b1,
  parameter logic [2:0] SEM_HOT_SCORE_BONUS = 3'd2,
  parameter logic [2:0] SEM_COLD_SCORE_PENALTY = 3'd1,
  parameter logic [7:0] SEM_HOT_MAX_AGE = 8'd96,
  parameter logic [2:0] REQ_HOT_SCORE_BONUS = 3'd1,
  parameter logic [2:0] AGE_STALE_SCORE_PENALTY = 3'd2,
  parameter logic [2:0] LOSSY_SCORE_PENALTY = 3'd1,
  parameter bit     LOSSY_COMPRESS_EN = 1'b1,
  parameter integer COMP_SHIFT = 4,
  parameter logic [2:0] COMPRESS_QOS_TH = 3'd2,
  parameter logic [7:0] COMP_ERR_CAP = 8'd63,
  parameter bit     H2O_V2_EN = 1'b1,
  parameter bit     UTILITY_SCORE_REPL_EN = 1'b0,
  parameter bit     UTILITY_MARGINAL_REPL_EN = 1'b0,
  parameter bit     QMATCH_SERVICE_PLACEMENT_EN = 1'b0,
  parameter bit     SERVICE_ISSUE_DEFER_DIRTY_FLUSH_EN = 1'b0,
  parameter bit     SERVICE_ISSUE_CLEAN_VICTIM_RESCUE_EN = 1'b0,
  parameter logic [2:0] SERVICE_ISSUE_CLEAN_VICTIM_MARGIN = 3'd2,
  parameter bit     SCHED_OWNERSHIP_QUERY_BIAS_EN = 1'b0,
  parameter bit     SCHED_OWNERSHIP_QUERY_STRONG_BIAS_EN = 1'b0,
  parameter bit     SCHED_OWNERSHIP_QUERY_ADAPTIVE_BIAS_EN = 1'b0
)(
  input  logic                 clk,
  input  logic                 rst_n,

  input  logic                 req_re,
  input  logic [ADDR_W-1:0]    req_raddr,
  input  logic                 req_is_prefetch,
  input  logic [2:0]           req_qos,
  input  logic                 req_sem_hot,
  input  logic                 req_fill_allow,
  input  logic                 req_victim_protect,
  input  logic                 req_compress_allow,
  input  logic                 req_hh_protect,
  input  logic                 req_recent_keep,
  input  logic [1:0]           req_h2o_class,
  input  logic [SCORE_W-1:0]   req_utility_score,
  input  logic [SCORE_W-1:0]   req_query_relevance,
  input  logic [kcmu_pkg::KCMU_HEAD_BUDGET_W-1:0] req_head_budget_class,
  input  logic [kcmu_pkg::KCMU_DESC_CLASS_W-1:0] req_temporal_persist_class,
  input  logic [kcmu_pkg::KCMU_DESC_CLASS_W-1:0] req_reuse_distance_class,
  input  logic [kcmu_pkg::KCMU_DESC_CLASS_W-1:0] req_query_structure_class,
  input  logic                 req_marginal_active,
  input  logic                 req_service_issue_boost,
  input  logic                 req_sched_query_take,
  input  logic                 req_sched_temporal_take,
  input  logic                 req_sched_query_bias_take,
  input  logic                 req_group_boundary,
  input  logic                 req_group_target_valid,
  input  logic [ADDR_W-1:0]    req_group_target_addr,
  input  logic                 req_group_v251gf_force,
  input  logic                 req_kiloscore_extra_cvr_hint,
  input  logic [2:0]           req_kiloscore_qsig_bucket,
  input  logic                 req_backend_write_pressure,
  output logic [DATA_W-1:0]    req_rdata,
  output logic                 req_rvalid,
  output logic                 req_rhit,
  output logic                 req_rlossy,
  output logic [2:0]           req_rsource,

  input  logic                 req_we,
  input  logic [ADDR_W-1:0]    req_waddr,
  input  logic [DATA_W-1:0]    req_wdata,

  output logic                 mem_re,
  output logic [ADDR_W-1:0]    mem_raddr,
  output logic                 mem_req_is_prefetch,
  output logic                 mem_req_is_group,
  output logic                 mem_req_service_issue_boost,
  input  logic                 mem_re_ready,
  output logic                 mem_req_accepted,
  input  logic [DATA_W-1:0]    mem_rdata,
  input  logic                 mem_rvalid,

  output logic                 mem_we,
  output logic [ADDR_W-1:0]    mem_waddr,
  output logic [DATA_W-1:0]    mem_wdata,
  output logic                 mem_req_is_writeback,
  input  logic                 mem_we_ready,
  output logic                 fill_req_query_admit_event,
  output logic [2:0]           group_feedback_credit_o,
  output logic [2:0]           group_throttle_credit_o,
  output logic [2:0]           group_hhfloor_backoff_credit_o,
  output logic [31:0]          stat_l2_comp_fill_cnt_o,
  output logic [31:0]          stat_l2_comp_readback_cnt_o,
  output logic [31:0]          stat_l2_comp_spill_cnt_o,
  output logic [31:0]          stat_l2_dirty_wb_req_cnt_o
);

