`ifdef KCMU_KILOSCORE_V639_CAPACITY_ACTIVE
  localparam bit KCMU_V639_SMALL_CAPACITY_OK =
    (L2_LINES <= 32) &&
    (L2_LINES > L1_LINES) &&
    ((GROUP_BUF_LINES * 4) >= VB_LINES) &&
    ((L2_LINES > 16) || (VB_LINES <= 8)) &&
    (
      (VB_LINES <= 8) ||
      (L1_LINES <= 8) ||
      ((L2_LINES >= (2 * L1_LINES)) && (VB_LINES <= L1_LINES) && (L1_LINES <= 16))
    );
  localparam bit KCMU_V639_LARGE_CAPACITY_OK =
    (L2_LINES >= 128) &&
    (L1_LINES >= 64) &&
    ((GROUP_BUF_LINES * 8) >= VB_LINES);
  localparam bit KCMU_V639_CAPACITY_OK =
    KCMU_V639_SMALL_CAPACITY_OK || KCMU_V639_LARGE_CAPACITY_OK;
  localparam bit KCMU_V639_BALANCED_BRAKE =
    (L2_LINES <= 32) &&
    (L2_LINES >= (2 * L1_LINES)) &&
    (VB_LINES > 8) &&
    (VB_LINES <= L1_LINES) &&
    (L1_LINES <= 16) &&
    ((GROUP_BUF_LINES * 4) >= VB_LINES);
  localparam logic [3:0] KCMU_V639_TARGET_DEBT_TH =
    KCMU_V639_BALANCED_BRAKE ? 4'd3 : 4'd4;
`endif

`ifdef KCMU_CFG_FPGA_KILOSCORE_SIGRISK_GF_RESTORE_V809
`define KCMU_KS_SIGRISK_GF_RESTORE_GATE \
  ((miss_kiloscore_qsig_bucket != 3'd0) && \
   group_lane_valid[group_lane_idx] && group_match_stride && \
   (group_lane_conf[group_lane_idx] >= 3'd1) && \
   (rw_density_credit <= 4'd4) && !miss_backend_write_pressure)
`elsif KCMU_CFG_FPGA_KILOSCORE_SIGRISK_GF_RESTORE_STRICT_V810
`define KCMU_KS_SIGRISK_GF_RESTORE_GATE \
  ((miss_kiloscore_qsig_bucket >= 3'd2) && \
   (miss_query_structure_class <= kcmu_pkg::KCMU_DESC_CLASS_W'(2)) && \
   group_lane_valid[group_lane_idx] && group_match_stride && \
   (group_lane_conf[group_lane_idx] >= 3'd2) && \
   (rw_density_credit <= 4'd3) && !miss_backend_write_pressure)
`elsif KCMU_CFG_FPGA_KILOSCORE_SIGRISK_GF_DESC_RESTORE_V811
`define KCMU_KS_SIGRISK_GF_RESTORE_GATE \
  ((miss_kiloscore_qsig_bucket != 3'd0) && \
   (miss_query_structure_class <= kcmu_pkg::KCMU_DESC_CLASS_W'(2)) && \
   (miss_group_target_valid || \
    (group_lane_valid[group_lane_idx] && group_match_stride && \
     (group_lane_conf[group_lane_idx] >= 3'd1))) && \
   (rw_density_credit <= 4'd4) && !miss_backend_write_pressure)
`else
`define KCMU_KS_SIGRISK_GF_RESTORE_GATE 1'b0
`endif

`ifdef KCMU_KILOSCORE_L2_ONLY_V387_ACTIVE
`define KCMU_KILOSCORE_SCOREPATH_ACTIVE
`endif
`ifdef KCMU_KILOSCORE_THROTTLE_SAFE_V388_ACTIVE
`define KCMU_KILOSCORE_SCOREPATH_ACTIVE
`endif
`ifdef KCMU_CFG_FPGA_KILOSCORE_PREFIX_SWITCH_CAP_GUARD_V769
  // v769: add a 4-bit prefix-density split to v768.  In the c02 traces,
  // mixed-NSA reaches density 8 but sustained tri-class/multimodal exceeds it.
  // Below 9, keep v749's tiny-L2 q>=3/switch guard; at or above 9, treat the
  // stream as sustained prefix/NSA and only block explicit class switching.
  assign group_mixed_nsa_guard =
    !(`KCMU_KS_SIGRISK_GF_RESTORE_GATE) &&
    !((L1_LINES >= 64) && (L2_LINES >= 128)) &&
    (
`ifdef KCMU_CFG_FPGA_KILOSCORE_C02_SUSTAINED_NSA_FEEDBACK_V772
      ((L2_LINES <= 16) &&
       miss_service_issue_boost &&
       (group_feedback_credit <= 3'd2)) ||
`endif
      ((L2_LINES <= 16) &&
       (|(gb_valid_mem & ~gb_used_mem)) &&
       (
         ((group_prefix_density_credit < 4'd9) &&
          (
            (miss_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) ||
            (group_class_seen && (group_class_switch_credit >= 3'd2))
          )) ||
          ((group_prefix_density_credit >= 4'd9) &&
           (
             (group_class_seen && (group_class_switch_credit >= 3'd2))
`ifdef KCMU_CFG_FPGA_KILOSCORE_C02_SUSTAINED_NSA_FEEDBACK_V772
             ||
             (
               (miss_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) &&
               (group_feedback_credit <= 3'd2)
             )
`endif
           ))
        )) ||
      ((L1_LINES == 32) && (L2_LINES == 64) &&
       (VB_LINES >= 32) && (GROUP_BUF_LINES >= 8) &&
       (|(gb_valid_mem & ~gb_used_mem)) &&
       (
         (miss_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) ||
         (group_class_seen && (group_class_switch_credit >= 3'd2))
       )) ||
      ((L2_LINES > 16) &&
       !((L1_LINES == 32) && (L2_LINES == 64) &&
         (VB_LINES >= 32) && (GROUP_BUF_LINES >= 8)) &&
       (
         (
           (miss_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) &&
            (group_feedback_credit <= 3'd5) &&
            !(group_lane_valid[group_lane_idx] &&
              group_match_stride &&
              (group_lane_conf[group_lane_idx] >= KCMU_V21_GF_GUARD_CONF_TH_VALUE))
          ) ||
         (
           group_insert_pollution_risk &&
           (
             (miss_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) ||
             (group_class_seen && (group_class_switch_credit >= 3'd2))
           )
         ) ||
         (
           (|(gb_valid_mem & ~gb_used_mem)) &&
           (
             (miss_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) ||
             (group_class_seen && (group_class_switch_credit >= 3'd2))
           )
         )
       ))
    );
`elsif KCMU_CFG_FPGA_KILOSCORE_SWITCH_AWARE_CAP_GUARD_V768
  // v768: split v749's tiny-L2 guard by runtime descriptor switching.  The
  // c02 sweep shows sustained q>=3 NSA prefers the older v722/v733 behavior
  // while mixed class-switch streams need the v749 guard.  For the c12
  // L32/L64/C32/G8 bucket, use the less aggressive v733 GB-unused guard so
  // multimodal/prefix does not lose AMAT while keeping the rest of v749.
  assign group_mixed_nsa_guard =
    !((L1_LINES >= 64) && (L2_LINES >= 128)) &&
    (
      ((L2_LINES <= 16) &&
       (|(gb_valid_mem & ~gb_used_mem)) &&
       group_class_seen &&
       (group_class_switch_credit >= 3'd2)) ||
      ((L1_LINES == 32) && (L2_LINES == 64) &&
       (VB_LINES >= 32) && (GROUP_BUF_LINES >= 8) &&
       (|(gb_valid_mem & ~gb_used_mem)) &&
       (
         (miss_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) ||
         (group_class_seen && (group_class_switch_credit >= 3'd2))
       )) ||
      ((L2_LINES > 16) &&
       !((L1_LINES == 32) && (L2_LINES == 64) &&
         (VB_LINES >= 32) && (GROUP_BUF_LINES >= 8)) &&
       (
         (
           (miss_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) &&
           (group_feedback_credit <= 3'd5) &&
           !(group_lane_valid[group_lane_idx] &&
             group_match_stride &&
             (group_lane_conf[group_lane_idx] >= 3'd2))
         ) ||
         (
           group_insert_pollution_risk &&
           (
             (miss_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) ||
             (group_class_seen && (group_class_switch_credit >= 3'd2))
           )
         ) ||
         (
