`ifndef SYNTHESIS
  initial begin
    if (!L2_LINES_IS_POW2) begin
      $fatal(1, "kcmu_l2_ctrl requires power-of-two L2_LINES, got %0d", L2_LINES);
    end
    if (!((L2_WAYS == 1) || (L2_WAYS == 2))) begin
      $fatal(1, "kcmu_l2_ctrl currently supports L2_WAYS in {1,2}, got %0d", L2_WAYS);
    end
    if ((L2_LINES % L2_WAYS) != 0) begin
      $fatal(1, "kcmu_l2_ctrl requires L2_LINES divisible by L2_WAYS, got L2_LINES=%0d L2_WAYS=%0d", L2_LINES, L2_WAYS);
    end
    if (!L2_SETS_IS_POW2) begin
      $fatal(1, "kcmu_l2_ctrl requires power-of-two L2_SETS, got %0d", L2_SETS);
    end
    if (!VB_LINES_IS_POW2) begin
      $fatal(1, "kcmu_l2_ctrl requires power-of-two VB_LINES, got %0d", VB_LINES);
    end
  end
`endif

