  assign stat_l2_comp_readback_cnt_o = stat_l2_comp_readback_cnt;
  assign stat_l2_comp_spill_cnt_o = stat_l2_comp_spill_cnt;
  assign stat_l2_dirty_wb_req_cnt_o = stat_l2_dirty_wb_req_cnt;
  assign group_feedback_credit_o = group_feedback_credit;
  assign group_throttle_credit_o = group_throttle_credit;
  assign group_hhfloor_backoff_credit_o = group_hhfloor_backoff_credit;
  logic [31:0] sim_cycle;
  logic [31:0] line_fill_cycle [0:L2_LINES-1];
`endif

  function automatic logic [L2_IDX_W-1:0] set_way_to_line_idx(
    input logic [L2_SET_IDX_W-1:0] set_idx,
    input logic                    way_sel
  );
    begin
      if (L2_WAYS <= 1) begin
        set_way_to_line_idx = set_idx[L2_IDX_W-1:0];
      end else begin
        // Flat layout: way0 in lower half, way1 in upper half.
        set_way_to_line_idx = {way_sel, set_idx};
      end
    end
  endfunction

  function automatic logic [L2_SET_IDX_W-1:0] line_idx_to_set_idx(
    input logic [L2_IDX_W-1:0] line_idx
  );
    begin
      line_idx_to_set_idx = line_idx[L2_SET_IDX_W-1:0];
    end
  endfunction

  function automatic logic [L2_SET_IDX_W-1:0] addr_set_idx(input logic [ADDR_W-1:0] addr);
    begin
      addr_set_idx = addr[L2_SET_IDX_W-1:0];
    end
  endfunction

  function automatic logic [L2_TAG_W-1:0] addr_tag(input logic [ADDR_W-1:0] addr);
    begin
      if (ADDR_W > L2_SET_IDX_W) begin
        addr_tag = addr[ADDR_W-1:L2_SET_IDX_W];
      end else begin
        addr_tag = {L2_TAG_W{1'b0}};
      end
    end
  endfunction

  function automatic logic [ADDR_W-1:0] compose_addr_from_line(
    input logic [L2_TAG_W-1:0] line_tag,
    input logic [L2_IDX_W-1:0] line_idx
  );
    logic [L2_SET_IDX_W-1:0] set_idx;
    begin
      set_idx = line_idx_to_set_idx(line_idx);
      if (ADDR_W > L2_SET_IDX_W) begin
        compose_addr_from_line = {line_tag, set_idx};
      end else begin
        compose_addr_from_line = set_idx[ADDR_W-1:0];
      end
    end
  endfunction

  function automatic logic [5:0] sat_add6(
    input logic [5:0] a,
    input logic [5:0] b
  );
    logic [6:0] sum;
    begin
      sum = {1'b0, a} + {1'b0, b};
      if (sum[6]) begin
        sat_add6 = 6'h3f;
      end else begin
        sat_add6 = sum[5:0];
      end
    end
  endfunction

  function automatic logic [5:0] sat_sub6(
    input logic [5:0] a,
    input logic [5:0] b
  );
    begin
      if (a > b) begin
        sat_sub6 = a - b;
      end else begin
        sat_sub6 = 6'd0;
      end
    end
  endfunction

  function automatic logic [3:0] sat_add4(
    input logic [3:0] a,
    input logic [2:0] b
  );
    logic [4:0] sum;
    begin
      sum = {1'b0, a} + {2'b00, b};
      if (sum[4]) begin
        sat_add4 = 4'hf;
      end else begin
        sat_add4 = sum[3:0];
      end
    end
  endfunction

  function automatic logic [5:0] utility_score_bonus(
    input logic [SCORE_W-1:0] utility_score,
    input logic [7:0]         age,
    input logic [3:0]         freq,
    input logic               line_protected,
    input logic               marginal_keep,
    input logic               pollution_risk,
    input logic [2:0]         pressure_bonus
  );
    logic [5:0] raw_bonus;
    begin
      raw_bonus = 6'd0;
      if (UTILITY_SCORE_REPL_EN) begin
        if (utility_score >= SCORE_W'(8'hD8)) begin
          raw_bonus = 6'd3;
        end else if (utility_score >= SCORE_W'(8'hB8)) begin
          raw_bonus = 6'd2;
        end else if (utility_score >= SCORE_W'(8'h90)) begin
          raw_bonus = 6'd1;
        end

        if (UTILITY_MARGINAL_REPL_EN) begin
          // CAS-U v2 is intentionally conservative: when no marginal metadata
          // is present, keep the S4 utility score intact and only apply
          // line-local marginal/pollution/pressure corrections.
          if (marginal_keep) begin
            raw_bonus = sat_add6(raw_bonus, line_protected ? 6'd1 : 6'd3);
          end
          if (pressure_bonus != 3'd0) begin
            raw_bonus = sat_add6(raw_bonus, {3'b000, pressure_bonus});
          end
          if (pollution_risk) begin
            raw_bonus = sat_sub6(raw_bonus, 6'd4);
          end
        end else begin
          // S5b/S5d: high utility is most valuable when reuse is still plausible.
          // Keep HAQU-covered lines stable, strengthen recently/frequently reused
          // utility lines, and decay stale one-touch utility to avoid pollution.
          if ((utility_score >= SCORE_W'(8'hD8)) &&
              (line_protected || (freq >= 4'd2) || (age < 8'd64))) begin
            raw_bonus = sat_add6(raw_bonus, 6'd1);
          end else if (!line_protected && (freq <= 4'd1) && (age >= 8'd128)) begin
            raw_bonus = 6'd0;
          end else if (!line_protected && (freq <= 4'd1) && (age >= 8'd64) && (raw_bonus != 6'd0)) begin
            raw_bonus = raw_bonus - 6'd1;
          end
        end
      end
      utility_score_bonus = raw_bonus;
    end
  endfunction

  function automatic logic make_marginal_keep(
    input logic [SCORE_W-1:0] utility_score,
    input logic               marginal_active,
    input logic               already_protected,
    input logic               service_issue_boost,
    input logic [3:0]         freq,
    input logic [7:0]         age
  );
    begin
      make_marginal_keep =
        UTILITY_MARGINAL_REPL_EN &&
        marginal_active &&
        (utility_score >= SCORE_W'(8'hA0)) &&
        !already_protected &&
        (service_issue_boost || (utility_score >= SCORE_W'(8'hA8)) ||
         (freq >= 4'd1));
    end
  endfunction

  function automatic logic make_pollution_risk(
    input logic [SCORE_W-1:0] utility_score,
    input logic               marginal_active,
    input logic               already_protected,
    input logic [3:0]         freq,
    input logic [7:0]         age
  );
    begin
      make_pollution_risk =
        UTILITY_MARGINAL_REPL_EN &&
        marginal_active &&
        (utility_score != {SCORE_W{1'b0}}) &&
        !already_protected &&
        ((utility_score < SCORE_W'(8'h90)) || ((freq == 4'd0) && (age >= 8'd96)));
    end
  endfunction

  function automatic logic [2:0] make_pressure_bonus(
    input logic [SCORE_W-1:0] utility_score,
    input logic               marginal_active,
    input logic               service_issue_boost
  );
    begin
      if (UTILITY_MARGINAL_REPL_EN && marginal_active && service_issue_boost &&
          (utility_score >= SCORE_W'(8'hD0))) begin
        make_pressure_bonus = 3'd2;
      end else if (UTILITY_MARGINAL_REPL_EN && marginal_active && service_issue_boost &&
                   (utility_score >= SCORE_W'(8'hB8))) begin
        make_pressure_bonus = 3'd1;
      end else begin
        make_pressure_bonus = 3'd0;
      end
    end
  endfunction

  function automatic logic [2:0] desc_bucket3(
    input logic [kcmu_pkg::KCMU_DESC_CLASS_W-1:0] cls
  );
    begin
      if (cls >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) begin
        desc_bucket3 = 3'd3;
      end else begin
        desc_bucket3 = {1'b0, cls};
      end
    end
  endfunction

  function automatic logic [2:0] rnear_bucket3(
    input logic [kcmu_pkg::KCMU_DESC_CLASS_W-1:0] reuse_distance_class
  );
    begin
      if (reuse_distance_class == {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}}) begin
        rnear_bucket3 = 3'd0;
      end else if (reuse_distance_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) begin
        rnear_bucket3 = 3'd0;
      end else begin
        rnear_bucket3 = 3'd3 - {1'b0, reuse_distance_class};
      end
    end
  endfunction

  function automatic logic [2:0] bucket3_from_u3(
    input logic [2:0] value
  );
    begin
      bucket3_from_u3 = (value >= 3'd3) ? 3'd3 : value;
    end
  endfunction

  function automatic logic [2:0] nsa_bucket3(
    input logic [kcmu_pkg::KCMU_DESC_CLASS_W-1:0] query_structure_class,
    input logic [kcmu_pkg::KCMU_DESC_CLASS_W-1:0] temporal_persist_class,
    input logic [kcmu_pkg::KCMU_DESC_CLASS_W-1:0] reuse_distance_class
  );
    begin
      if (query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) begin
        nsa_bucket3 = 3'd3;
      end else if (query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(2)) begin
        nsa_bucket3 = 3'd2;
      end else if ((temporal_persist_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(2)) ||
                   ((reuse_distance_class != {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}}) &&
                    (reuse_distance_class <= kcmu_pkg::KCMU_DESC_CLASS_W'(2)))) begin
        nsa_bucket3 = 3'd1;
      end else begin
        nsa_bucket3 = 3'd0;
      end
    end
  endfunction

  function automatic logic make_admission_bypass(
    input logic [SCORE_W-1:0] utility_score,
    input logic               marginal_active,
    input logic               sem_hot,
    input logic               victim_protect,
    input logic               hh_protect,
    input logic               recent_keep,
    input logic [1:0]         h2o_class,
    input logic               compress_allow,
    input logic [2:0]         qos,
    input logic               is_prefetch
  );
    begin
      // Keep admission bypass disabled on the default line. Earlier experiments
      // showed that broad low-utility bypass tends to trade short-term backend
      // wins for lost reuse. The stronger descriptor->control mapping in this
      // iteration is applied through set-local victim ordering instead.
      make_admission_bypass =
        1'b0;
    end
  endfunction

  function automatic logic [SCORE_W-1:0] merge_utility_score(
    input logic [SCORE_W-1:0] current_score,
    input logic [SCORE_W-1:0] incoming_score
  );
    begin
      if (!UTILITY_SCORE_REPL_EN) begin
        merge_utility_score = {SCORE_W{1'b0}};
      end else if (incoming_score > current_score) begin
        merge_utility_score = incoming_score;
      end else begin
        merge_utility_score = current_score;
      end
    end
  endfunction

  function automatic logic [2:0] freq_step_from_req(
    input logic [2:0] qos,
    input logic       sem_hot,
    input logic       is_prefetch
  );
    begin
      if (sem_hot && (qos >= 3'd5)) begin
        freq_step_from_req = 3'd3;
      end else if (sem_hot || (!is_prefetch && (qos >= 3'd4))) begin
        freq_step_from_req = 3'd2;
      end else begin
        freq_step_from_req = 3'd1;
      end
    end
  endfunction

  function automatic logic [3:0] seed_freq_from_req(
    input logic [2:0] qos,
    input logic       sem_hot,
    input logic       is_prefetch
  );
    logic [3:0] seed;
    begin
      seed = is_prefetch ? 4'd1 : ({1'b0, qos} + 4'd1);
      if (sem_hot && (seed < 4'd4)) begin
        seed = 4'd4;
      end
      if (sem_hot && (qos >= 3'd5) && (seed < 4'd6)) begin
        seed = 4'd6;
      end
      seed_freq_from_req = seed;
    end
  endfunction

  function automatic logic [5:0] h2o_line_score(
    input logic [3:0] freq,
    input logic [7:0] age,
    input logic       lossy,
    input logic       line_dirty,
    input logic       line_hot,
    input logic       line_hh_protect,
    input logic       line_recent_keep,
    input logic [1:0] line_h2o_class,
    input logic [SCORE_W-1:0] line_utility_score,
    input logic       line_marginal_keep,
    input logic       line_pollution_risk,
    input logic [2:0] line_pressure_bonus,
    input logic       req_hot,
    input logic       req_hh_protect,
    input logic       req_recent_keep,
    input logic [SCORE_W-1:0] req_utility_score,
    input logic [SCORE_W-1:0] req_query_relevance,
    input logic [kcmu_pkg::KCMU_DESC_CLASS_W-1:0] req_query_structure_class,
    input logic       req_marginal_active,
    input logic [2:0] req_qos,
    input logic       req_is_prefetch
  );
    logic [2:0] recency_bonus;
    logic [5:0] score_v;
    logic [5:0] hot_bonus;
    logic [5:0] cold_penalty;
    logic       line_hot_eff;
    logic [2:0] req_query_bucket;
    logic [2:0] line_utility_bucket;
    logic       req_structured_query_value;
    logic       native_line_reuse_value;
    logic       native_tiny_midprefix_query_brake;
    begin
      if (age < 8'd8) begin
        recency_bonus = 3'd5;
      end else if (age < 8'd24) begin
        recency_bonus = 3'd4;
      end else if (age < 8'd64) begin
        recency_bonus = 3'd2;
      end else if (age < 8'd128) begin
        recency_bonus = 3'd1;
      end else begin
        recency_bonus = 3'd0;
      end

      score_v = sat_add6({2'b00, freq}, {3'b000, recency_bonus});
      if (lossy) begin
        score_v = sat_sub6(score_v, {3'b000, LOSSY_SCORE_PENALTY});
      end else begin
        score_v = sat_add6(score_v, 6'd1);
      end
      if (line_dirty) begin
        // Protect dirty victims to suppress writeback pressure.
        score_v = sat_add6(score_v, {3'b000, DIRTY_SCORE_BONUS});
        if (req_is_prefetch && (req_qos <= 3'd2)) begin
          score_v = sat_add6(score_v, 6'd1);
        end
      end

      line_hot_eff = (line_hot && (age <= SEM_HOT_MAX_AGE)) ||
                     (H2O_V2_EN && (line_h2o_class != KCMU_H2O_NEITHER))
`ifdef KCMU_CFG_FPGA_KILOSCORE_NATIVE_STANDALONE
                     ||
                     (!H2O_V2_EN &&
                      (line_hh_protect ||
                       line_marginal_keep ||
                       (line_utility_score >= SCORE_W'(8'h60)) ||
                       ((line_h2o_class == KCMU_H2O_BOTH) &&
                        ((line_utility_score >= SCORE_W'(8'h40)) ||
                         (freq >= 4'd1))) ||
                       ((line_h2o_class == KCMU_H2O_HEAVY_ONLY) &&
                        ((line_utility_score >= SCORE_W'(8'h50)) ||
                         (freq >= 4'd1)))))
`endif
                     ;
      req_query_bucket = req_query_relevance[SCORE_W-1 -: 3];
      line_utility_bucket = line_utility_score[SCORE_W-1 -: 3];
      req_structured_query_value =
        !req_is_prefetch &&
        (req_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) &&
        (req_query_relevance >= SCORE_W'(8'h80)) &&
        (req_utility_score >= SCORE_W'(8'h30));
      native_line_reuse_value = (freq >= 4'd2) && (age <= 8'd128);
      native_tiny_midprefix_query_brake =
        !H2O_V2_EN &&
        (L1_LINES <= 8) &&
        (L2_LINES <= 16) &&
        !req_is_prefetch &&
        (req_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) &&
        (req_query_relevance <= SCORE_W'(8'hC8)) &&
        (req_utility_score >= SCORE_W'(8'h40));
      hot_bonus = 6'd0;
      if (SEM_HOT_VICTIM_PROTECT_EN && line_hot_eff) begin
        hot_bonus = {3'b000, SEM_HOT_SCORE_BONUS};
        if (req_hot || (req_qos >= 3'd5)) begin
          hot_bonus = sat_add6(hot_bonus, {3'b000, REQ_HOT_SCORE_BONUS});
        end
        score_v = sat_add6(score_v, hot_bonus);
      end

      if (H2O_V2_EN) begin
        unique case (line_h2o_class)
`ifdef KCMU_CFG_FPGA_KILOSCORE_HV_OPT5_GLOBAL_WINNER
          KCMU_H2O_BOTH:       score_v = sat_add6(score_v, 6'd5);
`elsif KCMU_CFG_FPGA_KILOSCORE_HV_BOTH5_BONUS
          KCMU_H2O_BOTH:       score_v = sat_add6(score_v, 6'd5);
`else
          KCMU_H2O_BOTH:       score_v = sat_add6(score_v, 6'd4);
`endif
          KCMU_H2O_HEAVY_ONLY: score_v = sat_add6(score_v, 6'd3);
          KCMU_H2O_RECENT_ONLY:score_v = sat_add6(score_v, 6'd1);
          default: begin end
        endcase
        if (line_hh_protect)  score_v = sat_add6(score_v, 6'd1);
        score_v = sat_add6(score_v, utility_score_bonus(
          line_utility_score,
          age,
          freq,
          line_hh_protect || line_recent_keep || (line_h2o_class != KCMU_H2O_NEITHER),
          line_marginal_keep,
          line_pollution_risk,
          line_pressure_bonus
        ));
        if (req_hh_protect && line_hh_protect) begin
          score_v = sat_add6(score_v, 6'd1);
        end else if (req_recent_keep && line_recent_keep) begin
          score_v = sat_add6(score_v, 6'd1);
        end else if (UTILITY_SCORE_REPL_EN &&
                     (req_utility_score >= SCORE_W'(8'hB8)) &&
                     (line_utility_score >= SCORE_W'(8'hB8))) begin
          score_v = sat_add6(score_v, 6'd1);
        end

`ifdef KCMU_ABL_SOFT_NSA_TINY_BIAS_V70
        if (line_hh_protect ||
            line_marginal_keep ||
            (line_h2o_class == KCMU_H2O_BOTH) ||
            (line_h2o_class == KCMU_H2O_HEAVY_ONLY) ||
            ((line_utility_score >= SCORE_W'(8'hA8)) && !line_pollution_risk)) begin
          score_v = sat_add6(score_v, 6'd1);
        end
`elsif KCMU_ABL_SOFT_NSA_QUERY_SAFE_BIAS_V71
        if (!req_is_prefetch &&
            !((req_query_relevance >= SCORE_W'(8'hA8)) &&
              (req_utility_score >= SCORE_W'(8'h80))) &&
            (line_hh_protect ||
             line_marginal_keep ||
             (line_h2o_class == KCMU_H2O_BOTH) ||
             (line_h2o_class == KCMU_H2O_HEAVY_ONLY) ||
             ((line_utility_score >= SCORE_W'(8'hA8)) && !line_pollution_risk))) begin
          score_v = sat_add6(score_v, 6'd1);
        end
`elsif KCMU_ABL_SOFT_NSA_HH_ONLY_BIAS_V72
        if (line_hh_protect ||
            (line_h2o_class == KCMU_H2O_BOTH) ||
            (line_h2o_class == KCMU_H2O_HEAVY_ONLY)) begin
          score_v = sat_add6(score_v, 6'd1);
        end
`endif

        if ((((UTILITY_SCORE_REPL_EN || req_marginal_active) &&
              (req_query_relevance >= SCORE_W'(8'hA8)) &&
              (req_utility_score >= SCORE_W'(8'h80))) ||
             (QMATCH_SERVICE_PLACEMENT_EN &&
              !req_is_prefetch &&
              (req_query_relevance >= QMATCH_SERVICE_QUERY_TH) &&
              (req_utility_score >= QMATCH_SERVICE_UTILITY_TH))) &&
            !line_hh_protect &&
            !line_recent_keep &&
            (line_h2o_class != KCMU_H2O_BOTH) &&
            (line_h2o_class != KCMU_H2O_HEAVY_ONLY)) begin
          if (req_query_bucket >= (line_utility_bucket + 3'd3)) begin
            score_v = sat_sub6(score_v, 6'd6);
          end else if (req_query_bucket >= (line_utility_bucket + 3'd2)) begin
            score_v = sat_sub6(score_v, 6'd4);
          end else if (req_query_bucket > line_utility_bucket) begin
            score_v = sat_sub6(score_v, 6'd2);
          end
          if (QMATCH_SERVICE_PLACEMENT_EN &&
              (line_h2o_class == KCMU_H2O_RECENT_ONLY) &&
              (req_query_relevance >= QMATCH_SERVICE_QUERY_TH) &&
              (freq <= 4'd1) &&
              (age >= 8'd24)) begin
            score_v = sat_sub6(score_v, 6'd2);
          end
          if ((line_utility_score < SCORE_W'(8'h80)) &&
              (req_query_relevance >= SCORE_W'(8'hD0))) begin
            score_v = sat_sub6(score_v, 6'd2);
          end
          if ((freq <= 4'd1) && (age >= 8'd32)) begin
            score_v = sat_sub6(score_v, 6'd2);
          end else if ((freq <= 4'd2) && (age >= 8'd48)) begin
            score_v = sat_sub6(score_v, 6'd1);
          end
        end

        if (UTILITY_MARGINAL_REPL_EN &&
            req_marginal_active &&
            !req_is_prefetch &&
            !line_dirty &&
            !line_hh_protect &&
            (line_h2o_class != KCMU_H2O_BOTH) &&
            (line_h2o_class != KCMU_H2O_HEAVY_ONLY) &&
            (req_utility_score >= SCORE_W'(8'hB8))) begin
          // CAS-U v2: steer only within the current 2-way set. This gives a
          // high marginal-utility fill a chance to displace low-value overlap
          // without dropping the fill itself.
          if (line_pollution_risk || (!line_recent_keep && (line_utility_score < SCORE_W'(8'h80)))) begin
            score_v = sat_sub6(score_v, 6'd3);
          end else if (!line_recent_keep && (freq <= 4'd1) && (age >= 8'd64)) begin
            score_v = sat_sub6(score_v, 6'd2);
          end else if ((line_h2o_class == KCMU_H2O_RECENT_ONLY) &&
                       (line_utility_score < SCORE_W'(8'hA8)) &&
                       (req_utility_score >= SCORE_W'(8'hD0))) begin
            score_v = sat_sub6(score_v, 6'd1);
          end
        end

      end
`ifdef KCMU_CFG_FPGA_KILOSCORE_NATIVE_STANDALONE
      if (!H2O_V2_EN) begin
        // Native KiloScore keeps the legacy 2-bit policy bus only as an
        // interface encoding. In H2O-off mode, interpret it as hardware-value
        // class metadata for L2 victim scoring.
        unique case (line_h2o_class)
          KCMU_H2O_BOTH:       score_v = sat_add6(score_v, 6'd4);
          KCMU_H2O_HEAVY_ONLY: score_v = sat_add6(score_v, 6'd4);
          KCMU_H2O_RECENT_ONLY:score_v = sat_add6(score_v, 6'd2);
          default: begin end
        endcase
        if (line_hh_protect) begin
          score_v = sat_add6(score_v, 6'd2);
        end
        if (line_recent_keep) begin
          score_v = sat_add6(score_v, 6'd1);
        end
        if (line_utility_score >= SCORE_W'(8'h80)) begin
          score_v = sat_add6(score_v, 6'd3);
        end else if (line_utility_score >= SCORE_W'(8'h60)) begin
          score_v = sat_add6(score_v, 6'd2);
        end else if (line_utility_score >= SCORE_W'(8'h40)) begin
          score_v = sat_add6(score_v, 6'd1);
        end
        if ((req_utility_score >= SCORE_W'(8'h60)) &&
            (line_utility_score >= SCORE_W'(8'h60))) begin
          score_v = sat_add6(score_v, 6'd1);
        end
        if (native_line_reuse_value) begin
          if ((freq >= 4'd6) && (age <= 8'd96)) begin
            score_v = sat_add6(score_v, 6'd3);
          end else if ((freq >= 4'd3) && (age <= 8'd96)) begin
            score_v = sat_add6(score_v, 6'd2);
          end else begin
            score_v = sat_add6(score_v, 6'd1);
          end
          if ((req_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) &&
              !req_is_prefetch &&
              (freq >= 4'd3)) begin
            score_v = sat_add6(score_v, 6'd1);
          end
        end
        if (!native_tiny_midprefix_query_brake &&
            !req_is_prefetch &&
            (req_query_relevance >= SCORE_W'(8'hA0)) &&
            (req_utility_score >= SCORE_W'(8'h40))) begin
          if (req_query_bucket >= (line_utility_bucket + 3'd3)) begin
            score_v = sat_sub6(score_v, 6'd4);
          end else if (req_query_bucket >= (line_utility_bucket + 3'd2)) begin
            score_v = sat_sub6(score_v, 6'd3);
          end else if (req_query_bucket > line_utility_bucket) begin
            score_v = sat_sub6(score_v, 6'd1);
          end
          if ((line_utility_score < SCORE_W'(8'h50)) &&
              (freq <= 4'd1) &&
              (age >= 8'd24)) begin
            score_v = sat_sub6(score_v, 6'd1);
          end
        end
        if (!native_tiny_midprefix_query_brake &&
            req_structured_query_value &&
            !line_hh_protect &&
            (line_h2o_class != KCMU_H2O_BOTH) &&
            (line_utility_score < SCORE_W'(8'h80))) begin
          if ((freq <= 4'd1) && (age >= 8'd24)) begin
            score_v = sat_sub6(score_v, 6'd3);
          end else if ((freq <= 4'd2) && (age >= 8'd48)) begin
            score_v = sat_sub6(score_v, 6'd2);
          end else if (!line_recent_keep && (line_utility_score < SCORE_W'(8'h50))) begin
            score_v = sat_sub6(score_v, 6'd1);
          end
        end
        if (line_marginal_keep) begin
          score_v = sat_add6(score_v, line_hh_protect ? 6'd1 : 6'd2);
        end
        if (line_pressure_bonus != 3'd0) begin
          score_v = sat_add6(score_v, {3'b000, line_pressure_bonus});
        end
        if (line_pollution_risk &&
            !line_hh_protect &&
            (line_utility_score < SCORE_W'(8'h60))) begin
          score_v = sat_sub6(score_v, 6'd3);
        end else if (!line_hh_protect &&
                     !line_recent_keep &&
                     (line_utility_score < SCORE_W'(8'h40)) &&
                     (freq <= 4'd1) &&
                     (age >= 8'd96)) begin
          score_v = sat_sub6(score_v, 6'd2);
        end
      end
`endif

      cold_penalty = 6'd0;
      if (!line_hot_eff) begin
        if (!req_hot && (req_qos <= 3'd2)) begin
          cold_penalty = sat_add6(cold_penalty, {3'b000, SEM_COLD_SCORE_PENALTY});
        end
        if (req_hot || (req_qos >= 3'd5)) begin
          cold_penalty = sat_add6(cold_penalty, 6'd1);
        end
        if (age >= SEM_HOT_MAX_AGE) begin
          cold_penalty = sat_add6(cold_penalty, {3'b000, AGE_STALE_SCORE_PENALTY});
        end
        if (req_is_prefetch && (req_qos <= 3'd2)) begin
          cold_penalty = sat_add6(cold_penalty, 6'd1);
        end
      end

      h2o_line_score = sat_sub6(score_v, cold_penalty);
    end
  endfunction

  function automatic logic [5:0] kiloscore_v384_line_score(
    input logic [5:0]         base_score,
    input logic [3:0]         freq,
    input logic [7:0]         age,
    input logic               line_dirty,
    input logic               line_hh_protect,
    input logic               line_recent_keep,
    input logic [1:0]         line_h2o_class,
    input logic [SCORE_W-1:0] line_utility_score,
    input logic               line_pollution_risk,
    input logic [2:0]         line_pressure_bonus,
    input logic [kcmu_pkg::KCMU_DESC_CLASS_W-1:0] miss_class,
    input logic [2:0]         feedback_credit,
    input logic [2:0]         activity_credit,
    input logic [3:0]         rw_credit,
    input logic [2:0]         class_switch_credit,
    input logic               gb_unused_full
  );
    logic [5:0] score_v;
    begin
      score_v = base_score;

      if (line_dirty) begin
        score_v = sat_add6(score_v, 6'd2);
      end
      if (line_hh_protect || (line_h2o_class >= KCMU_H2O_HEAVY_ONLY)) begin
        score_v = sat_add6(score_v, 6'd2);
      end else if (line_recent_keep || (line_h2o_class == KCMU_H2O_RECENT_ONLY)) begin
        score_v = sat_add6(score_v, 6'd1);
      end

      if ((miss_class == kcmu_pkg::KCMU_DESC_CLASS_W'(1)) && (freq >= 4'd3)) begin
        score_v = sat_add6(score_v, 6'd1);
      end
      if ((miss_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) &&
          (line_hh_protect || (line_h2o_class == KCMU_H2O_BOTH))) begin
        score_v = sat_add6(score_v, 6'd2);
      end
      if ((activity_credit != 3'd0) && (feedback_credit >= 3'd3) &&
          (rw_credit <= 4'd3) && (freq != 4'd0)) begin
        score_v = sat_add6(score_v, 6'd1);
      end
      if ((class_switch_credit >= 3'd2) && !line_dirty &&
          (line_h2o_class == KCMU_H2O_NEITHER) && (age >= 8'd64)) begin
        score_v = sat_sub6(score_v, 6'd1);
      end
      if (line_pollution_risk || gb_unused_full || (feedback_credit <= 3'd1)) begin
        score_v = sat_sub6(score_v, 6'd2);
      end
      if ((line_pressure_bonus != 3'd0) && (line_utility_score >= SCORE_W'(8'hB8))) begin
        score_v = sat_add6(score_v, {3'b000, line_pressure_bonus});
      end
      if ((age >= 8'd128) && !line_dirty &&
          !line_hh_protect && (line_h2o_class == KCMU_H2O_NEITHER)) begin
        score_v = sat_sub6(score_v, 6'd1);
      end

      kiloscore_v384_line_score = score_v;
    end
  endfunction

  function automatic logic [7:0] max_err_for_bits(input logic [2:0] bits_kept);
    begin
      case (bits_kept)
        3'd4: max_err_for_bits = 8'd15;
        3'd3: max_err_for_bits = 8'd31;
        3'd2: max_err_for_bits = 8'd63;
        default: max_err_for_bits = 8'd127;
      endcase
    end
  endfunction

  function automatic logic [2:0] choose_comp_bits(
    input logic [2:0] qos,
    input logic       is_prefetch
  );
    logic [7:0] err_target;
    begin
      if (qos >= 3'd6) begin
        err_target = 8'd15;
      end else if (qos >= 3'd4) begin
        err_target = 8'd31;
      end else if (qos >= 3'd2) begin
        err_target = 8'd63;
      end else begin
        err_target = 8'd127;
      end

      if (is_prefetch && (qos <= 3'd2)) begin
        err_target = 8'd127;
      end

      if (COMP_ERR_CAP < err_target) begin
        err_target = COMP_ERR_CAP;
      end

      if (err_target <= 8'd15) begin
        choose_comp_bits = 3'd4;
      end else if (err_target <= 8'd31) begin
        choose_comp_bits = 3'd3;
      end else if (err_target <= 8'd63) begin
        choose_comp_bits = 3'd2;
      end else begin
        choose_comp_bits = 3'd1;
      end
    end
  endfunction

  function automatic logic allow_read_fill(
    input logic       is_prefetch,
    input logic [2:0] qos,
    input logic       sem_hot
  );
    logic [2:0] th;
    begin
      th = is_prefetch ? PREFETCH_FILL_QOS_TH : READ_FILL_QOS_TH;
      if (SEM_HOT_FILL_RELAX_EN && sem_hot && (th > 3'd0)) begin
        th = th - 3'd1;
      end
      if (sem_hot) begin
        allow_read_fill = 1'b1;
      end else begin
        allow_read_fill = (qos >= th);
      end
    end
  endfunction

  function automatic logic [COMP_W-1:0] compress_data(
    input logic [DATA_W-1:0] din,
    input logic [2:0]        bits_kept
  );
    integer bi;
    logic [7:0] b;
    logic [COMP_SHIFT-1:0] packed_bits;
    begin
      compress_data = {COMP_W{1'b0}};
      for (bi = 0; bi < BYTE_W; bi = bi + 1) begin
        b = din[bi*8 +: 8];
        case (bits_kept)
          3'd4: packed_bits = b[7:4];
          3'd3: packed_bits = {1'b0, b[7:5]};
          3'd2: packed_bits = {2'b00, b[7:6]};
          default: packed_bits = {3'b000, b[7]};
        endcase
        compress_data[bi*COMP_SHIFT +: COMP_SHIFT] = packed_bits;
      end
    end
  endfunction

  function automatic logic [DATA_W-1:0] decompress_data(
    input logic [COMP_W-1:0] cin,
    input logic [2:0]        bits_kept
  );
    integer bi;
    logic [COMP_SHIFT-1:0] packed_bits;
    logic [7:0] b;
    begin
      decompress_data = {DATA_W{1'b0}};
      for (bi = 0; bi < BYTE_W; bi = bi + 1) begin
        packed_bits = cin[bi*COMP_SHIFT +: COMP_SHIFT];
        case (bits_kept)
          3'd4: b = {packed_bits[3:0], 4'b0000};
          3'd3: b = {packed_bits[2:0], 5'b00000};
          3'd2: b = {packed_bits[1:0], 6'b000000};
          default: b = {packed_bits[0], 7'b0000000};
        endcase
        decompress_data[bi*8 +: 8] = b;
      end
    end
  endfunction

  function automatic logic [DATA_W-1:0] line_export_data(
    input logic [DATA_W-1:0] line_data,
    input logic [COMP_W-1:0] line_comp,
    input logic [2:0]        line_comp_bits,
    input logic              line_lossy
  );
    begin
      if (line_lossy) begin
        line_export_data = decompress_data(line_comp, line_comp_bits);
      end else begin
        line_export_data = line_data;
      end
    end
  endfunction

  function automatic logic should_spill_compress(
    input logic       line_dirty,
    input logic       line_hot,
    input logic       line_hh_protect,
    input logic       line_recent_keep,
    input logic [1:0] line_h2o_class,
    input logic       line_lossy,
    input logic       req_hot,
    input logic [2:0] qos,
    input logic       is_prefetch
  );
    begin
      if (line_lossy) begin
        should_spill_compress = 1'b1;
      end else if (H2O_V2_EN &&
                   ((line_h2o_class == KCMU_H2O_BOTH) ||
                    (line_h2o_class == KCMU_H2O_HEAVY_ONLY) ||
                    line_hh_protect)) begin
        should_spill_compress = 1'b0;
      end else begin
        should_spill_compress =
          LOSSY_COMPRESS_EN &&
          !line_dirty &&
          !line_hot &&
          !(H2O_V2_EN && line_recent_keep) &&
          !req_hot &&
          (is_prefetch || (qos <= COMPRESS_QOS_TH));
      end
    end
  endfunction

  function automatic logic [31:0] spill_saved_beats(
    input logic line_lossy,
    input logic [2:0] bits_kept
  );
    integer saved_bits;
    begin
      if (!line_lossy) begin
        spill_saved_beats = 32'd0;
      end else begin
        saved_bits = (BYTE_W * 8) - (BYTE_W * bits_kept);
        if (saved_bits <= 0) begin
          spill_saved_beats = 32'd0;
        end else begin
          spill_saved_beats = 32'((saved_bits + 7) / 8);
        end
      end
    end
  endfunction

`ifdef KCMU_CFG_FPGA_KILOSCORE_NATIVE_STANDALONE
  assign deferred_req_take = deferred_req_valid && !req_re;
`else
  assign deferred_req_take = deferred_req_valid;
`endif
  assign rd_req_re = req_re || deferred_req_valid;
  assign rd_req_raddr = deferred_req_take ? deferred_req_raddr : req_raddr;
  assign rd_req_is_prefetch = deferred_req_take ? deferred_req_is_prefetch : req_is_prefetch;
  assign rd_req_qos = deferred_req_take ? deferred_req_qos : req_qos;
  assign rd_req_sem_hot = deferred_req_take ? deferred_req_sem_hot : req_sem_hot;
  assign rd_req_fill_allow = deferred_req_take ? deferred_req_fill_allow : req_fill_allow;
  assign rd_req_victim_protect = deferred_req_take ? deferred_req_victim_protect : req_victim_protect;
  assign rd_req_compress_allow = deferred_req_take ? deferred_req_compress_allow : req_compress_allow;
  assign rd_req_hh_protect = deferred_req_take ? deferred_req_hh_protect : req_hh_protect;
  assign rd_req_recent_keep = deferred_req_take ? deferred_req_recent_keep : req_recent_keep;
  assign rd_req_h2o_class = deferred_req_take ? deferred_req_h2o_class : req_h2o_class;
  assign rd_req_utility_score = deferred_req_take ? deferred_req_utility_score : req_utility_score;
  assign rd_req_query_relevance = deferred_req_take ? deferred_req_query_relevance : req_query_relevance;
  assign rd_req_head_budget_class = deferred_req_take ? deferred_req_head_budget_class : req_head_budget_class;
  assign rd_req_temporal_persist_class = deferred_req_take ? deferred_req_temporal_persist_class : req_temporal_persist_class;
  assign rd_req_reuse_distance_class = deferred_req_take ? deferred_req_reuse_distance_class : req_reuse_distance_class;
  assign rd_req_query_structure_class = deferred_req_take ? deferred_req_query_structure_class : req_query_structure_class;

`ifdef KCMU_CFG_FPGA_KILOSCORE_Q1_SAT_TINY_OWNER_VISIBLE_V727
  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      rd_req_q1_run_cnt <= 3'd0;
    end else if (rd_req_re) begin
      if (rd_req_query_structure_class == kcmu_pkg::KCMU_DESC_CLASS_W'(1)) begin
        if (rd_req_q1_run_cnt != 3'd7) begin
          rd_req_q1_run_cnt <= rd_req_q1_run_cnt + 3'd1;
        end
      end else begin
        rd_req_q1_run_cnt <= 3'd0;
      end
    end
  end
`elsif KCMU_CFG_FPGA_KILOSCORE_Q1_PURE_TINY_OWNER_VISIBLE_V726
  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      rd_req_q1_run_cnt <= 3'd0;
    end else if (rd_req_re) begin
      if (rd_req_query_structure_class == kcmu_pkg::KCMU_DESC_CLASS_W'(1)) begin
        if (rd_req_q1_run_cnt != 3'd7) begin
          rd_req_q1_run_cnt <= rd_req_q1_run_cnt + 3'd1;
        end
      end else begin
        rd_req_q1_run_cnt <= 3'd0;
      end
    end
  end
`endif

  assign rd_req_marginal_active = deferred_req_take ? deferred_req_marginal_active : req_marginal_active;
  assign rd_req_service_issue_boost = deferred_req_take ? deferred_req_service_issue_boost : req_service_issue_boost;
  assign rd_req_sched_query_take = deferred_req_take ? deferred_req_sched_query_take : req_sched_query_take;
  assign rd_req_sched_temporal_take = deferred_req_take ? deferred_req_sched_temporal_take : req_sched_temporal_take;
  assign rd_req_sched_query_bias_take = deferred_req_take ? deferred_req_sched_query_bias_take : req_sched_query_bias_take;
  assign rd_req_group_boundary = deferred_req_take ? deferred_req_group_boundary : req_group_boundary;
  assign rd_req_group_target_valid = deferred_req_take ? deferred_req_group_target_valid : req_group_target_valid;
  assign rd_req_group_target_addr = deferred_req_take ? deferred_req_group_target_addr : req_group_target_addr;
  assign rd_req_group_v251gf_force =
    deferred_req_take ? deferred_req_group_v251gf_force : req_group_v251gf_force;
  assign rd_req_kiloscore_extra_cvr_hint =
    deferred_req_take ? deferred_req_kiloscore_extra_cvr_hint : req_kiloscore_extra_cvr_hint;
  assign rd_req_kiloscore_qsig_bucket =
    deferred_req_take ? deferred_req_kiloscore_qsig_bucket : req_kiloscore_qsig_bucket;

  assign r_set_idx = addr_set_idx(rd_req_raddr);
  assign w_set_idx = addr_set_idx(req_waddr);
  assign r_way0_idx = set_way_to_line_idx(r_set_idx, 1'b0);
  assign r_way1_idx = set_way_to_line_idx(r_set_idx, 1'b1);
  assign w_way0_idx = set_way_to_line_idx(w_set_idx, 1'b0);
  assign w_way1_idx = set_way_to_line_idx(w_set_idx, 1'b1);
  assign r_tag = addr_tag(rd_req_raddr);
  assign w_tag = addr_tag(req_waddr);

  assign read_hit_way0 = valid_mem[r_way0_idx] && (tag_mem[r_way0_idx] == r_tag);
  assign read_hit_way1 = (L2_WAYS > 1) && valid_mem[r_way1_idx] && (tag_mem[r_way1_idx] == r_tag);
  assign read_hit  = rd_req_re && (read_hit_way0 || read_hit_way1);
  assign r_hit_idx = read_hit_way0 ? r_way0_idx : r_way1_idx;

  assign write_hit_way0 = valid_mem[w_way0_idx] && (tag_mem[w_way0_idx] == w_tag);
  assign write_hit_way1 = (L2_WAYS > 1) && valid_mem[w_way1_idx] && (tag_mem[w_way1_idx] == w_tag);
  assign write_hit = req_we && (write_hit_way0 || write_hit_way1);
  assign w_hit_idx = write_hit_way0 ? w_way0_idx : w_way1_idx;

  assign write_alloc_enable = WRITE_ALLOCATE && req_fill_allow && (req_qos >= WRITE_ALLOC_QOS_TH);
  assign casu_req_admission_bypass = make_admission_bypass(
    rd_req_utility_score,
    rd_req_marginal_active,
    rd_req_sem_hot,
    rd_req_victim_protect,
    rd_req_hh_protect,
    rd_req_recent_keep,
    rd_req_h2o_class,
    rd_req_compress_allow,
    rd_req_qos,
    rd_req_is_prefetch
  );
  assign req_fill_hot_hint =
    rd_req_sem_hot ||
    rd_req_hh_protect ||
    (H2O_V2_EN && (rd_req_h2o_class != KCMU_H2O_NEITHER));
  assign req_sched_structured_fill_admit =
    !rd_req_is_prefetch &&
    (rd_req_sched_query_take || rd_req_sched_temporal_take) &&
    (rd_req_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(2)) &&
    (rd_req_query_relevance >= SCORE_W'(8'h78)) &&
    (rd_req_utility_score >= SCORE_W'(8'h68)) &&
    !allow_read_fill(rd_req_is_prefetch, rd_req_qos, req_fill_hot_hint);
  // Allow cold compressed lines to enter L2 even when the normal fill policy would bypass
  // them. This is the key path that makes lossy compression participate in the hierarchy.
  assign read_fill_enable = !casu_req_admission_bypass &&
                            ((rd_req_fill_allow && allow_read_fill(rd_req_is_prefetch, rd_req_qos, req_fill_hot_hint)) ||
                             req_sched_structured_fill_admit ||
                             (rd_req_compress_allow && !req_we));
`ifdef KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_CVR_SIDE_CACHE_NOPROMOTE_V357
  // v357: treat clean CVR as a read-only side cache.  A CVR hit is returned
  // directly but is not promoted back into L2, avoiding L2 pollution from
  // one-off near misses.  Writes still invalidate the whole clean CVR.
  assign clean_vb_promote_enable = 1'b0;
  assign clean_vb_consume_on_hit = 1'b0;
  assign clean_vb_latched_side_enable = 1'b0;
  assign clean_vb_delayed_consume_enable = 1'b0;
  assign clean_vb_hold_side_enable = 1'b0;
`elsif KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_CVR_ONESHOT_SIDE_V358
  // v358: safer side-cache variant.  A clean CVR hit is returned directly and
  // consumed immediately, so it avoids L2 pollution without leaving a stale
  // side-cache copy that can conflict with later descriptor/payload updates.
  assign clean_vb_promote_enable = 1'b0;
  assign clean_vb_consume_on_hit = 1'b1;
  assign clean_vb_latched_side_enable = 1'b0;
  assign clean_vb_delayed_consume_enable = 1'b0;
  assign clean_vb_hold_side_enable = 1'b0;
`elsif KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_CVR_LATCHED_SIDE_V359
  // v359: protocol-safe side-cache response.  A clean CVR hit is latched into
  // a one-cycle response register before the side entry is consumed, avoiding
  // the combinational response race seen by direct no-promote variants.
  assign clean_vb_promote_enable = 1'b0;
  assign clean_vb_consume_on_hit = 1'b1;
  assign clean_vb_latched_side_enable = 1'b1;
  assign clean_vb_delayed_consume_enable = 1'b0;
  assign clean_vb_hold_side_enable = 1'b0;
`elsif KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_CVR_DELAYED_CONSUME_SIDE_V360
  // v360: no-promote side-cache response with delayed one-cycle consume.  The
  // entry remains stable through the response sampling edge, then is cleared
  // on the next cycle to avoid long-lived stale side copies.
  assign clean_vb_promote_enable = 1'b0;
  assign clean_vb_consume_on_hit = 1'b0;
  assign clean_vb_latched_side_enable = 1'b0;
  assign clean_vb_delayed_consume_enable = 1'b1;
  assign clean_vb_hold_side_enable = 1'b0;
`elsif KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_CVR_HOLD_CONSUME_SIDE_V365
  // v365: side-cache hit returns on the normal hit path, while a one-cycle
  // hold register keeps the response stable after the CVR entry is consumed.
  assign clean_vb_promote_enable = 1'b0;
  assign clean_vb_consume_on_hit = 1'b1;
  assign clean_vb_latched_side_enable = 1'b0;
  assign clean_vb_delayed_consume_enable = 1'b0;
  assign clean_vb_hold_side_enable = 1'b1;
`else
  assign clean_vb_promote_enable = read_fill_enable;
  assign clean_vb_consume_on_hit = 1'b0;
  assign clean_vb_latched_side_enable = 1'b0;
  assign clean_vb_delayed_consume_enable = 1'b0;
  assign clean_vb_hold_side_enable = 1'b0;
`endif
  assign read_hit_lossy = read_hit && lossy_mem[r_hit_idx];
  assign req_comp_bits = choose_comp_bits(rd_req_qos, rd_req_is_prefetch);
`ifdef KCMU_KILOSCORE_CVR_FRESH4_GF7_PHASE_GUARD_V403_ACTIVE
  // v403: v402 plus one narrow strong-feedback rail.  Low-utility qstruct=0
  // CVR hits at saturated group feedback carry the same +4 fresh-reuse seed;
