  assign clean_vb_promote_freq_seed =
    (req_h2o_class >= KCMU_H2O_HEAVY_ONLY) ?
      4'd7 : seed_freq_from_req(req_qos, req_sem_hot, req_is_prefetch);
`elsif KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_CVR_HIT_FREQBOOST_HIGHCLASS5_V376
  // v376: lower-amplitude version of v375.  The v375 high-class feedback
  // showed real Qwen/CMQA gain but exposed an MDQA descriptor mismatch; seed5
  // tests whether the same hierarchy feedback signal can be used without
  // pushing replacement state as aggressively.
  assign clean_vb_promote_freq_seed =
    (req_h2o_class >= KCMU_H2O_HEAVY_ONLY) ?
      4'd5 : seed_freq_from_req(req_qos, req_sem_hot, req_is_prefetch);
`elsif KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_CVR_HIT_FREQBOOST_STRUCTHIGH5_V378
  // v378: descriptor-gated version of v376.  Only structured/non-uniform
  // descriptor classes can use the CVR-hit replacement feedback, leaving LCQA
  // style unstructured traces on the conservative v251 placement path.
  assign clean_vb_promote_freq_seed =
    ((req_h2o_class >= KCMU_H2O_HEAVY_ONLY) &&
     (req_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(2))) ?
      4'd5 : seed_freq_from_req(req_qos, req_sem_hot, req_is_prefetch);
`elsif KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_CVR_HIT_FREQBOOST_HIGHCLASS5_QUIET_V379
  // v379: v376 plus a fully write-quiet window requirement.  This keeps the
  // high-class hierarchy feedback off traces where recent writes can make the
  // promoted replacement state unstable.
  assign clean_vb_promote_freq_seed =
    ((req_h2o_class >= KCMU_H2O_HEAVY_ONLY) &&
     (group_write_quiet_cnt == 3'd7)) ?
      4'd5 : seed_freq_from_req(req_qos, req_sem_hot, req_is_prefetch);
`elsif KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_CVR_HIT_FREQBOOST_HIGHCLASS5_RWSAFE_V380
  // v380: v376 plus a low read/write-density credit requirement.  It is less
  // strict than v379 and tests whether a coarse write-pressure signal is a
  // better safety guard than full quiet.
  assign clean_vb_promote_freq_seed =
    ((req_h2o_class >= KCMU_H2O_HEAVY_ONLY) &&
     (rw_density_credit <= 4'd2)) ?
      4'd5 : seed_freq_from_req(req_qos, req_sem_hot, req_is_prefetch);
`elsif KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_CVR_METADATA_PRESERVE_V381
  // v381: preserve the CVR entry's own low-bit frequency evidence on promote
  // instead of replacing it with a request-only seed.  This is a conservative
  // hierarchy-feedback signal: the line carries forward its observed lifetime
  // metadata rather than receiving an artificial boost.
  assign clean_vb_promote_freq_seed = sat_add4(
    vb_freq_mem[vb_read_idx],
    freq_step_from_req(req_qos, req_sem_hot, req_is_prefetch)
  );
`elsif KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_CVR_METADATA_PRESERVE_CLASS_V382
  // v382: v381 plus class preservation.  If the evicted clean line already
  // carried stronger H2O class evidence than the current request, keep it.
  assign clean_vb_promote_freq_seed = sat_add4(
    vb_freq_mem[vb_read_idx],
    freq_step_from_req(req_qos, req_sem_hot, req_is_prefetch)
  );
`elsif KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_CVR_HIT_BOTHBOOST_V363
  assign clean_vb_promote_freq_seed = 4'd7;
`else
  assign clean_vb_promote_freq_seed = seed_freq_from_req(req_qos, req_sem_hot, req_is_prefetch);
`endif
`ifdef KCMU_KILOSCORE_CVR_CLASS_PROMOTE_ACTIVE
  assign clean_vb_promote_h2o_class_seed =
    (kiloscore_path_enable && (vb_h2o_class_mem[vb_read_idx] > req_h2o_class)) ?
      vb_h2o_class_mem[vb_read_idx] : req_h2o_class;
`elsif KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_CVR_HIT_CLASSBOOST_V362
  assign clean_vb_promote_h2o_class_seed = KCMU_H2O_BOTH;
`elsif KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_CVR_HIT_BOTHBOOST_V363
  assign clean_vb_promote_h2o_class_seed = KCMU_H2O_BOTH;
`elsif KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_CVR_METADATA_PRESERVE_CLASS_V382
  assign clean_vb_promote_h2o_class_seed =
    (vb_h2o_class_mem[vb_read_idx] > req_h2o_class) ?
      vb_h2o_class_mem[vb_read_idx] : req_h2o_class;
`else
  assign clean_vb_promote_h2o_class_seed = req_h2o_class;
`endif
  assign req_lossy_fill = rd_req_compress_allow &&
                          !req_we &&
                          LOSSY_COMPRESS_EN &&
                          (rd_req_is_prefetch || (rd_req_qos <= COMPRESS_QOS_TH)) &&
                          (max_err_for_bits(req_comp_bits) <= COMP_ERR_CAP);
  assign r_score0 = h2o_line_score(
    line_freq[r_way0_idx],
    epoch_ctr - line_touch_epoch[r_way0_idx],
    lossy_mem[r_way0_idx],
    dirty_mem[r_way0_idx],
    line_sem_hot[r_way0_idx],
    line_hh_protect_mem[r_way0_idx],
    line_recent_keep_mem[r_way0_idx],
    line_h2o_class_mem[r_way0_idx],
    line_utility_score_mem[r_way0_idx],
    line_marginal_keep_mem[r_way0_idx],
    line_pollution_risk_mem[r_way0_idx],
    line_pressure_bonus_mem[r_way0_idx],
    (rd_req_sem_hot || rd_req_victim_protect || rd_req_hh_protect || rd_req_recent_keep),
    rd_req_hh_protect,
    rd_req_recent_keep,
    rd_req_utility_score,
    rd_req_query_relevance,
    rd_req_query_structure_class,
    rd_req_marginal_active,
    rd_req_qos,
    rd_req_is_prefetch
  );
  assign r_score1 = h2o_line_score(
    line_freq[r_way1_idx],
    epoch_ctr - line_touch_epoch[r_way1_idx],
    lossy_mem[r_way1_idx],
    dirty_mem[r_way1_idx],
    line_sem_hot[r_way1_idx],
    line_hh_protect_mem[r_way1_idx],
    line_recent_keep_mem[r_way1_idx],
    line_h2o_class_mem[r_way1_idx],
    line_utility_score_mem[r_way1_idx],
    line_marginal_keep_mem[r_way1_idx],
    line_pollution_risk_mem[r_way1_idx],
    line_pressure_bonus_mem[r_way1_idx],
    (rd_req_sem_hot || rd_req_victim_protect || rd_req_hh_protect || rd_req_recent_keep),
    rd_req_hh_protect,
    rd_req_recent_keep,
    rd_req_utility_score,
    rd_req_query_relevance,
    rd_req_query_structure_class,
    rd_req_marginal_active,
    rd_req_qos,
    rd_req_is_prefetch
  );
  assign w_score0 = h2o_line_score(
    line_freq[w_way0_idx],
    epoch_ctr - line_touch_epoch[w_way0_idx],
    lossy_mem[w_way0_idx],
    dirty_mem[w_way0_idx],
    line_sem_hot[w_way0_idx],
    line_hh_protect_mem[w_way0_idx],
    line_recent_keep_mem[w_way0_idx],
    line_h2o_class_mem[w_way0_idx],
    line_utility_score_mem[w_way0_idx],
    line_marginal_keep_mem[w_way0_idx],
    line_pollution_risk_mem[w_way0_idx],
    line_pressure_bonus_mem[w_way0_idx],
    (req_sem_hot || req_victim_protect || req_hh_protect || req_recent_keep),
    req_hh_protect,
    req_recent_keep,
    req_utility_score,
    req_query_relevance,
    req_query_structure_class,
    1'b0,
    req_qos,
    1'b0
  );
  assign w_score1 = h2o_line_score(
    line_freq[w_way1_idx],
    epoch_ctr - line_touch_epoch[w_way1_idx],
    lossy_mem[w_way1_idx],
    dirty_mem[w_way1_idx],
    line_sem_hot[w_way1_idx],
    line_hh_protect_mem[w_way1_idx],
    line_recent_keep_mem[w_way1_idx],
    line_h2o_class_mem[w_way1_idx],
    line_utility_score_mem[w_way1_idx],
    line_marginal_keep_mem[w_way1_idx],
    line_pollution_risk_mem[w_way1_idx],
    line_pressure_bonus_mem[w_way1_idx],
    (req_sem_hot || req_victim_protect || req_hh_protect || req_recent_keep),
    req_hh_protect,
    req_recent_keep,
    req_utility_score,
    req_query_relevance,
    req_query_structure_class,
    1'b0,
    req_qos,
    1'b0
  );

  assign r_pick_way1 = (L2_WAYS > 1) &&
                       valid_mem[r_way0_idx] &&
                       valid_mem[r_way1_idx] &&
                       ((r_score1 < r_score0) || ((r_score1 == r_score0) && set_rr_way[r_set_idx]));
  assign w_pick_way1 = (L2_WAYS > 1) &&
                       valid_mem[w_way0_idx] &&
                       valid_mem[w_way1_idx] &&
                       ((w_score1 < w_score0) || ((w_score1 == w_score0) && set_rr_way[w_set_idx]));

  always @(*) begin
    r_idx = r_way0_idx;
    if (L2_WAYS > 1) begin
      if (!valid_mem[r_way0_idx]) begin
        r_idx = r_way0_idx;
      end else if (!valid_mem[r_way1_idx]) begin
        r_idx = r_way1_idx;
      end else if (r_pick_way1) begin
        r_idx = r_way1_idx;
      end
    end
  end

  always @(*) begin
    w_idx = w_way0_idx;
    if (L2_WAYS > 1) begin
      if (!valid_mem[w_way0_idx]) begin
        w_idx = w_way0_idx;
      end else if (!valid_mem[w_way1_idx]) begin
        w_idx = w_way1_idx;
      end else if (w_pick_way1) begin
        w_idx = w_way1_idx;
      end
    end
  end

  assign r_victim_sem_hot_eff = (line_sem_hot[r_idx] &&
                                ((epoch_ctr - line_touch_epoch[r_idx]) <= SEM_HOT_MAX_AGE)) ||
                                (H2O_V2_EN && (line_h2o_class_mem[r_idx] != KCMU_H2O_NEITHER));
  assign w_victim_sem_hot_eff = (line_sem_hot[w_idx] &&
                                ((epoch_ctr - line_touch_epoch[w_idx]) <= SEM_HOT_MAX_AGE)) ||
                                (H2O_V2_EN && (line_h2o_class_mem[w_idx] != KCMU_H2O_NEITHER));
  assign r_victim_dirty = valid_mem[r_idx] && dirty_mem[r_idx];
  assign w_victim_dirty = valid_mem[w_idx] && dirty_mem[w_idx];

  assign fill_set_idx = addr_set_idx(miss_addr);
  assign fill_way0_idx = set_way_to_line_idx(fill_set_idx, 1'b0);
  assign fill_way1_idx = set_way_to_line_idx(fill_set_idx, 1'b1);
  assign fill_tag = addr_tag(miss_addr);
  assign fill_score0 = h2o_line_score(
    line_freq[fill_way0_idx],
    epoch_ctr - line_touch_epoch[fill_way0_idx],
    lossy_mem[fill_way0_idx],
    dirty_mem[fill_way0_idx],
    line_sem_hot[fill_way0_idx],
    line_hh_protect_mem[fill_way0_idx],
    line_recent_keep_mem[fill_way0_idx],
    line_h2o_class_mem[fill_way0_idx],
    line_utility_score_mem[fill_way0_idx],
    line_marginal_keep_mem[fill_way0_idx],
    line_pollution_risk_mem[fill_way0_idx],
    line_pressure_bonus_mem[fill_way0_idx],
    (miss_sem_hot || miss_victim_protect || miss_hh_protect || miss_recent_keep),
    miss_hh_protect,
    miss_recent_keep,
    miss_utility_score,
    miss_query_relevance,
    miss_query_structure_class,
    miss_marginal_active,
    miss_qos,
    miss_is_prefetch
  );
  assign fill_score1 = h2o_line_score(
    line_freq[fill_way1_idx],
    epoch_ctr - line_touch_epoch[fill_way1_idx],
    lossy_mem[fill_way1_idx],
    dirty_mem[fill_way1_idx],
    line_sem_hot[fill_way1_idx],
    line_hh_protect_mem[fill_way1_idx],
    line_recent_keep_mem[fill_way1_idx],
    line_h2o_class_mem[fill_way1_idx],
    line_utility_score_mem[fill_way1_idx],
    line_marginal_keep_mem[fill_way1_idx],
    line_pollution_risk_mem[fill_way1_idx],
    line_pressure_bonus_mem[fill_way1_idx],
    (miss_sem_hot || miss_victim_protect || miss_hh_protect || miss_recent_keep),
    miss_hh_protect,
    miss_recent_keep,
    miss_utility_score,
    miss_query_relevance,
    miss_query_structure_class,
    miss_marginal_active,
    miss_qos,
    miss_is_prefetch
  );
  assign fill_score0_noquery = h2o_line_score(
    line_freq[fill_way0_idx],
    epoch_ctr - line_touch_epoch[fill_way0_idx],
    lossy_mem[fill_way0_idx],
    dirty_mem[fill_way0_idx],
    line_sem_hot[fill_way0_idx],
    line_hh_protect_mem[fill_way0_idx],
    line_recent_keep_mem[fill_way0_idx],
    line_h2o_class_mem[fill_way0_idx],
    line_utility_score_mem[fill_way0_idx],
    line_marginal_keep_mem[fill_way0_idx],
    line_pollution_risk_mem[fill_way0_idx],
    line_pressure_bonus_mem[fill_way0_idx],
    (miss_sem_hot || miss_victim_protect || miss_hh_protect || miss_recent_keep),
    miss_hh_protect,
    miss_recent_keep,
    miss_utility_score,
    {SCORE_W{1'b0}},
    {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}},
    miss_marginal_active,
    miss_qos,
    miss_is_prefetch
  );
  assign fill_score1_noquery = h2o_line_score(
    line_freq[fill_way1_idx],
    epoch_ctr - line_touch_epoch[fill_way1_idx],
    lossy_mem[fill_way1_idx],
    dirty_mem[fill_way1_idx],
    line_sem_hot[fill_way1_idx],
    line_hh_protect_mem[fill_way1_idx],
    line_recent_keep_mem[fill_way1_idx],
    line_h2o_class_mem[fill_way1_idx],
    line_utility_score_mem[fill_way1_idx],
    line_marginal_keep_mem[fill_way1_idx],
    line_pollution_risk_mem[fill_way1_idx],
    line_pressure_bonus_mem[fill_way1_idx],
    (miss_sem_hot || miss_victim_protect || miss_hh_protect || miss_recent_keep),
    miss_hh_protect,
    miss_recent_keep,
    miss_utility_score,
    {SCORE_W{1'b0}},
    {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}},
    miss_marginal_active,
    miss_qos,
    miss_is_prefetch
  );
  assign fill_kiloscore0 = kiloscore_v384_line_score(
    fill_score0,
    line_freq[fill_way0_idx],
    epoch_ctr - line_touch_epoch[fill_way0_idx],
    dirty_mem[fill_way0_idx],
    line_hh_protect_mem[fill_way0_idx],
    line_recent_keep_mem[fill_way0_idx],
    line_h2o_class_mem[fill_way0_idx],
    line_utility_score_mem[fill_way0_idx],
    line_pollution_risk_mem[fill_way0_idx],
    line_pressure_bonus_mem[fill_way0_idx],
    miss_query_structure_class,
    group_feedback_credit,
    group_activity_credit,
    rw_density_credit,
    group_class_switch_credit,
    group_pollution_block
  );
  assign fill_kiloscore1 = kiloscore_v384_line_score(
    fill_score1,
    line_freq[fill_way1_idx],
    epoch_ctr - line_touch_epoch[fill_way1_idx],
    dirty_mem[fill_way1_idx],
    line_hh_protect_mem[fill_way1_idx],
    line_recent_keep_mem[fill_way1_idx],
    line_h2o_class_mem[fill_way1_idx],
    line_utility_score_mem[fill_way1_idx],
    line_pollution_risk_mem[fill_way1_idx],
    line_pressure_bonus_mem[fill_way1_idx],
    miss_query_structure_class,
    group_feedback_credit,
    group_activity_credit,
    rw_density_credit,
    group_class_switch_credit,
    group_pollution_block
  );
  assign fill_kiloscore_gate =
    (L2_WAYS > 1) &&
    kiloscore_path_enable &&
    valid_mem[fill_way0_idx] &&
    valid_mem[fill_way1_idx] &&
    !miss_is_prefetch &&
    fill_score_close_rrip_tie &&
    (
      ((miss_query_structure_class == kcmu_pkg::KCMU_DESC_CLASS_W'(1)) &&
       (rw_density_credit <= 4'd4)) ||
      ((miss_query_structure_class == {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}}) &&
       (group_activity_credit != 3'd0) &&
       (group_feedback_credit >= 3'd3) &&
       (rw_density_credit <= 4'd3)) ||
      ((miss_query_structure_class <= kcmu_pkg::KCMU_DESC_CLASS_W'(2)) &&
       group_class_seen &&
       (group_class_switch_credit >= 3'd2)) ||
      ((miss_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) &&
       (group_feedback_credit >= 3'd3) &&
       !group_pollution_block)
    );
  assign fill_pick_way1_kiloscore =
    (fill_kiloscore1 < fill_kiloscore0) ||
    ((fill_kiloscore1 == fill_kiloscore0) && fill_pick_way1_rrip_lite);
  assign fill_pick_way1_rrip_lite =
    (L2_WAYS > 1) &&
    valid_mem[fill_way0_idx] &&
    valid_mem[fill_way1_idx] &&
    (
      (line_h2o_class_mem[fill_way1_idx] < line_h2o_class_mem[fill_way0_idx]) ||
      ((line_h2o_class_mem[fill_way1_idx] == line_h2o_class_mem[fill_way0_idx]) &&
       (line_freq[fill_way1_idx] < line_freq[fill_way0_idx])) ||
      ((line_h2o_class_mem[fill_way1_idx] == line_h2o_class_mem[fill_way0_idx]) &&
       (line_freq[fill_way1_idx] == line_freq[fill_way0_idx]) &&
       (fill_age1 > fill_age0))
    );
  assign fill_l2victim_guard_gate =
    (L2_WAYS > 1) &&
    valid_mem[fill_way0_idx] &&
    valid_mem[fill_way1_idx] &&
    !miss_is_prefetch &&
    !fill_tiny_cvr16_restore_v1473 &&
    !fill_capacity_corridor_restore_v1475 &&
    !fill_largecap_hotdeficit_restore_v1475 &&
    !fill_largecap_qstruct_l2_restore_v1478 &&
    fill_score_close_rrip_tie &&
    (rw_density_credit <= 4'd3) &&
    !fill_largecap_qstruct0_rrip_brake &&
    !fill_sprint_j_smallcap_rrip_brake &&
    !group_pollution_block;
  assign fill_tiny_cvr16_restore_v1473 =
`ifdef KCMU_CFG_FPGA_KILOSCORE_SEARCH_TINY_CVR16_RESTORE_V1473
    (L1_LINES <= 8) &&
    (L2_LINES <= 16) &&
    (VB_LINES >= 16) &&
    (GROUP_BUF_LINES <= 2);
`else
    1'b0;
`endif
  assign fill_capacity_corridor_restore_v1475 =
`ifdef KCMU_CFG_FPGA_KILOSCORE_SEARCH_CAPACITY_CORRIDOR_RESTORE_V1475
    (((L1_LINES == 16) && (L2_LINES == 16) && (VB_LINES == 8) &&
      (GROUP_BUF_LINES <= 2)) ||
     ((L1_LINES == 32) && (L2_LINES == 64) && (VB_LINES == 32) &&
      ((GROUP_BUF_LINES == 4) || (GROUP_BUF_LINES == 8))));
`else
    1'b0;
`endif
  assign fill_largecap_hotdeficit_restore_v1475 =
`ifdef KCMU_CFG_FPGA_KILOSCORE_SEARCH_LARGECAP_HOTDEFICIT_RESTORE_V1475
    (L1_LINES >= 64) &&
    (L2_LINES >= 128) &&
    (VB_LINES >= 64) &&
    (GROUP_BUF_LINES >= 8) &&
    ((miss_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) ||
     ((L2_LINES <= 16) &&
      (VB_LINES >= 16) &&
      (GROUP_BUF_LINES <= 2) &&
      (miss_query_structure_class == kcmu_pkg::KCMU_DESC_CLASS_W'(1)) &&
      (miss_query_relevance >= SCORE_W'(8'h70)) &&
      (miss_query_relevance <= SCORE_W'(8'h80)) &&
      (miss_temporal_persist_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(2)) &&
      (miss_reuse_distance_class <= kcmu_pkg::KCMU_DESC_CLASS_W'(1)))) &&
    !miss_hh_protect;
`else
    1'b0;
`endif
  assign fill_largecap_qstruct_l2_restore_v1478 =
`ifdef KCMU_CFG_FPGA_KILOSCORE_SEARCH_LARGECAP_QSTRUCT_L2_RESTORE_V1478
    (L1_LINES >= 64) &&
    (L2_LINES >= 128) &&
    (VB_LINES >= 64) &&
    (miss_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3));
`else
    1'b0;
`endif
  assign fill_largecap_qstruct0_rrip_brake =
`ifdef KCMU_CFG_FPGA_KILOSCORE_SEARCH_LARGECAP_QSTRUCT0_L2RRIP_BRAKE_V1466
    (L1_LINES >= 64) &&
    (L2_LINES >= 128) &&
    (miss_query_structure_class == {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}});
`else
    1'b0;
`endif
  assign fill_sprint_j_smallcap_rrip_brake =
`ifdef KCMU_CFG_FPGA_KILOSCORE_SPRINT_J_SMALLCAP_L2RRIP_Q0_BRAKE
    (L1_LINES <= 16) &&
    (L2_LINES <= 32) &&
    (miss_query_structure_class == {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}});
`elsif KCMU_CFG_FPGA_KILOSCORE_SPRINT_P_SMALLCAP_HIGHQ_THROTTLE_BRAKE
    (L1_LINES <= 16) &&
    (L2_LINES <= 32) &&
    ((!group_qstruct_high_seen &&
      (miss_query_structure_class == {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}})) ||
     (miss_backend_write_pressure &&
      (miss_utility_score != {SCORE_W{1'b0}}) &&
      (group_throttle_credit >= 3'd2)) ||
     ((miss_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) &&
      (group_throttle_credit >= 3'd4)));
`elsif KCMU_CFG_FPGA_KILOSCORE_SPRINT_O_SMALLCAP_LOWQ_HIGHQ_PRESSURE_BRAKE
    (L1_LINES <= 16) &&
    (L2_LINES <= 32) &&
    ((!group_qstruct_high_seen &&
