    !group_qstruct_high_seen &&
    (miss_query_structure_class == {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}});
`elsif KCMU_CFG_FPGA_KILOSCORE_SPRINT_L_SMALLCAP_UTIL_THROTTLE2_BRAKE
    (L1_LINES <= 16) &&
    (L2_LINES <= 32) &&
    (miss_utility_score != {SCORE_W{1'b0}}) &&
    (group_throttle_credit >= 3'd2);
