  assign fill_way0_reuse_keep =
    line_hh_protect_mem[fill_way0_idx] ||
    line_recent_keep_mem[fill_way0_idx] ||
    (line_h2o_class_mem[fill_way0_idx] >= 2'd1) ||
    (line_freq[fill_way0_idx] >= 4'd2) ||
    (line_utility_score_mem[fill_way0_idx] >= SCORE_W'(8'h60)) ||
    (fill_age0 <= 8'd12);
  assign fill_way1_reuse_keep =
    line_hh_protect_mem[fill_way1_idx] ||
    line_recent_keep_mem[fill_way1_idx] ||
    (line_h2o_class_mem[fill_way1_idx] >= 2'd1) ||
    (line_freq[fill_way1_idx] >= 4'd2) ||
    (line_utility_score_mem[fill_way1_idx] >= SCORE_W'(8'h60)) ||
    (fill_age1 <= 8'd12);
  assign fill_way0_strict_keep =
    line_hh_protect_mem[fill_way0_idx] ||
    (line_h2o_class_mem[fill_way0_idx] >= 2'd2) ||
    (line_utility_score_mem[fill_way0_idx] >= SCORE_W'(8'h80)) ||
    ((line_freq[fill_way0_idx] >= 4'd3) && (fill_age0 <= 8'd32));
  assign fill_way1_strict_keep =
    line_hh_protect_mem[fill_way1_idx] ||
    (line_h2o_class_mem[fill_way1_idx] >= 2'd2) ||
    (line_utility_score_mem[fill_way1_idx] >= SCORE_W'(8'h80)) ||
    ((line_freq[fill_way1_idx] >= 4'd3) && (fill_age1 <= 8'd32));
  assign fill_way0_cold_drop =
    !line_hh_protect_mem[fill_way0_idx] &&
    !line_recent_keep_mem[fill_way0_idx] &&
    (line_h2o_class_mem[fill_way0_idx] == 2'd0) &&
    (line_freq[fill_way0_idx] <= 4'd1) &&
    (line_utility_score_mem[fill_way0_idx] < SCORE_W'(8'h40)) &&
    (fill_age0 >= 8'd8);
  assign fill_way1_cold_drop =
    !line_hh_protect_mem[fill_way1_idx] &&
    !line_recent_keep_mem[fill_way1_idx] &&
    (line_h2o_class_mem[fill_way1_idx] == 2'd0) &&
    (line_freq[fill_way1_idx] <= 4'd1) &&
    (line_utility_score_mem[fill_way1_idx] < SCORE_W'(8'h40)) &&
    (fill_age1 >= 8'd8);
  assign fill_pick_way1_l2victim_reuse_guard =
    (fill_l2victim_guard_gate && (fill_way0_reuse_keep != fill_way1_reuse_keep)) ?
      (fill_way0_reuse_keep && !fill_way1_reuse_keep) :
