  assign fill_pick_way1_l2victim_strict_guard =
    (fill_l2victim_guard_gate && (fill_way0_strict_keep != fill_way1_strict_keep)) ?
      (fill_way0_strict_keep && !fill_way1_strict_keep) :
      ((L2_WAYS > 1) && (fill_score1 < fill_score0));
  assign fill_pick_way1_l2victim_cold_drop =
    (fill_l2victim_guard_gate && (fill_way0_cold_drop != fill_way1_cold_drop)) ?
