     valid_mem[fill_way0_idx] &&
     valid_mem[fill_way1_idx] &&
     !miss_is_prefetch &&
     fill_score_margin4_rrip_tie &&
     (rw_density_credit <= 4'd3) &&
     !group_pollution_block) ?
      fill_pick_way1_rrip_lite :
      ((L2_WAYS > 1) && (fill_score1 < fill_score0));
  assign fill_native_tiny_mid_rrip_tie =
`ifdef KCMU_CFG_FPGA_KILOSCORE_NATIVE_STANDALONE
    (L1_LINES <= 8) &&
    (L2_LINES == 32) &&
    (VB_LINES >= 16) &&
    (GROUP_BUF_LINES <= 4) &&
    valid_mem[fill_way0_idx] &&
    valid_mem[fill_way1_idx] &&
    !miss_is_prefetch &&
    fill_score_close_rrip_tie &&
    (rw_density_credit <= 4'd3) &&
    !group_pollution_block &&
