`elsif KCMU_CFG_FPGA_KILOSCORE_DESC_TARGET_L2_RECENT_FILL_INSURE_V876
  // v876: narrower version that only raises the L2 protect bit, leaving the
  // H2O class unchanged.  This tests whether the residual v860 loss is due to
  // weak fill metadata rather than the class lattice itself.
  assign miss_l2_recent_fill_insure =
    miss_l2_recent_fill_insure_base &&
    (miss_group_target_valid ||
     miss_sched_query_take ||
     miss_sched_temporal_take ||
     (miss_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(2)));
  assign miss_hh_protect_fill_seed = miss_hh_protect | miss_l2_recent_fill_insure;
  assign miss_h2o_class_fill_seed = miss_h2o_class;
`else
  assign miss_l2_recent_fill_insure = 1'b0;
  assign miss_hh_protect_fill_seed = miss_hh_protect;
  assign miss_h2o_class_fill_seed = miss_h2o_class;
`endif
`ifdef KCMU_CFG_FPGA_KILOSCORE_NATIVE_STANDALONE
  assign native_midcap_prefix_stream_brake =
    (L1_LINES > 8) &&
    (L2_LINES > 16) &&
    (VB_LINES >= 16) &&
    (GROUP_BUF_LINES >= 4) &&
    !miss_backend_write_pressure &&
    (miss_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) &&
    (miss_query_relevance >= SCORE_W'(8'hA0)) &&
    (miss_utility_score >= SCORE_W'(8'h80)) &&
    (miss_temporal_persist_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(1));
  assign miss_sched_structured_fill_admit =
    !miss_is_prefetch &&
    (L2_LINES > 16) &&
    (miss_sched_query_take || miss_sched_temporal_take) &&
    (miss_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) &&
    (miss_query_relevance >= SCORE_W'(8'hA0)) &&
    (miss_utility_score >= SCORE_W'(8'h80)) &&
    !native_midcap_prefix_stream_brake &&
    !allow_read_fill(miss_is_prefetch, miss_qos, miss_fill_hot_hint);
`else
  assign native_midcap_prefix_stream_brake = 1'b0;
  assign miss_sched_structured_fill_admit =
    !miss_is_prefetch &&
    (miss_sched_query_take || miss_sched_temporal_take) &&
    (miss_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(2)) &&
    (miss_query_relevance >= SCORE_W'(8'h78)) &&
    (miss_utility_score >= SCORE_W'(8'h68)) &&
    !allow_read_fill(miss_is_prefetch, miss_qos, miss_fill_hot_hint);
`endif
  assign fill_l2_protected_victim_bypass =
`ifdef KCMU_CFG_FPGA_KILOSCORE_L2_PROTVICTIM_LOWSTRUCT_BYPASS_V917
    // v917: if both L2 candidates already carry strong reuse/protect evidence,
    // do not admit a low-structure, mid-value demand fill just because the
    // descriptor-target path would otherwise refill it.  This preserves L2
    // residency for chain-like MDQA phases where v860/v878 gained L1 hits but
    // lost backend reads through extra L2 churn.
    valid_mem[fill_way0_idx] &&
    valid_mem[fill_way1_idx] &&
    !miss_is_prefetch &&
    !miss_backend_write_pressure &&
    fill_way0_strict_keep &&
    fill_way1_strict_keep &&
    (rw_density_credit <= 4'd4) &&
    (miss_query_structure_class <= kcmu_pkg::KCMU_DESC_CLASS_W'(1)) &&
    (miss_utility_score < SCORE_W'(8'hA8)) &&
    !miss_sched_query_take &&
    !miss_sched_temporal_take;
`elsif KCMU_CFG_FPGA_KILOSCORE_L2_PROTVICTIM_RECENT_BYPASS_V918
    // v918: broader recent-only form.  Keep L2 stable when the incoming line is
    // recent-biased but not an explicit scheduler/query take, and both resident
    // candidates already have reuse value.
    valid_mem[fill_way0_idx] &&
    valid_mem[fill_way1_idx] &&
    !miss_is_prefetch &&
    !miss_backend_write_pressure &&
    fill_way0_reuse_keep &&
    fill_way1_reuse_keep &&
    (rw_density_credit <= 4'd5) &&
    miss_recent_keep &&
    (miss_h2o_class == KCMU_H2O_RECENT_ONLY) &&
    (miss_utility_score < SCORE_W'(8'hB8)) &&
    !miss_sched_query_take &&
    !miss_sched_temporal_take;
`elsif KCMU_CFG_FPGA_KILOSCORE_NATIVE_STANDALONE
    // Native KiloScore admission brake: when L2 is already holding two lines
    // and backend write pressure is high, do not let a structured-but-not-hot
    // demand miss churn the set. This is H2O-independent and uses only resident
    // validity, incoming descriptor/query value, and write-pressure state.
    valid_mem[fill_way0_idx] &&
    valid_mem[fill_way1_idx] &&
    !miss_is_prefetch &&
    !miss_group_target_valid &&
    !miss_sched_query_take &&
    !miss_sched_temporal_take &&
     (((miss_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) &&
       (miss_query_relevance < SCORE_W'(8'hA0)) &&
       (miss_utility_score < SCORE_W'(8'hA0))) ||
       ((L2_LINES > 16) &&
        (VB_LINES >= 16) &&
        (GROUP_BUF_LINES >= 4) &&
        !miss_backend_write_pressure &&
        fill_way0_strict_keep &&
       fill_way1_strict_keep &&
        (miss_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) &&
        (miss_query_relevance >= SCORE_W'(8'hA0)) &&
        (miss_utility_score < SCORE_W'(8'hD0))) ||
       ((L2_LINES <= 16) &&
        (VB_LINES <= 8) &&
        fill_way0_strict_keep &&
        fill_way1_strict_keep &&
        (miss_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) &&
        (miss_query_relevance >= SCORE_W'(8'hC0)) &&
        (miss_query_relevance <= SCORE_W'(8'hC8)) &&
        (miss_utility_score < SCORE_W'(8'hD0))) ||
       ((L2_LINES <= 16) &&
        miss_backend_write_pressure &&
        fill_way0_strict_keep &&
       fill_way1_strict_keep &&
      (miss_query_structure_class == {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}}) &&
      (miss_query_relevance >= SCORE_W'(8'h48)) &&
      (miss_query_relevance <= SCORE_W'(8'h80)) &&
      (miss_utility_score >= SCORE_W'(8'h40))));
`else
    1'b0;
`endif
  assign fill_read_fill_enable =
    !fill_l2_protected_victim_bypass &&
    !casu_miss_admission_bypass &&
    ((miss_fill_allow && allow_read_fill(miss_is_prefetch, miss_qos, miss_fill_hot_hint)) ||
    miss_sched_structured_fill_admit ||
    miss_compress_allow ||
    desc_target_read_bypass_rescue ||
    miss_l2miss_read_bypass_rescue);
`ifdef KCMU_CFG_FPGA_KILOSCORE_L2MISS_UTILITY_REFILL_V891
  // v891: broad utility-visible demand refill rescue.  v885-v890 showed that
  // response-time group-throttle credit does not coincide with the bypassed
  // fills.  This variant asks the sharper question: are the residual MDQA
  // backend losses simply useful demand fills being rejected from L2?
  assign miss_l2miss_read_bypass_rescue =
    !miss_is_prefetch &&
    !miss_backend_write_pressure &&
    ((miss_utility_score != {SCORE_W{1'b0}}) ||
     miss_sched_query_take ||
     miss_sched_temporal_take ||
     miss_recent_keep ||
     (miss_h2o_class != KCMU_H2O_NEITHER));
`elsif KCMU_CFG_FPGA_KILOSCORE_L2MISS_RECENT_REFILL_V892
  // v892: narrower v891.  Restore only recent/H2O-marked demand fills; this
  // avoids treating every non-zero utility line as L2-resident.
  assign miss_l2miss_read_bypass_rescue =
    !miss_is_prefetch &&
    !miss_backend_write_pressure &&
    (miss_recent_keep || (miss_h2o_class != KCMU_H2O_NEITHER));
`elsif KCMU_CFG_FPGA_KILOSCORE_L2MISS_RB_RESCUE4_V885
  // v885: qrel-free read-bypass rescue.  The remaining MDQA negatives are
  // not caused by GB pollution; they show a small number of demand responses
  // bypassing L2 during a group-throttled, L2-miss-heavy phase.  Admit only
  // demand fills with hardware-visible utility/recent/scheduler evidence.
  assign miss_l2miss_read_bypass_rescue =
    !miss_is_prefetch &&
    (group_throttle_credit >= 3'd4) &&
    (rw_density_credit <= 4'd6) &&
    !miss_backend_write_pressure &&
    ((miss_utility_score >= SCORE_W'(8'h80)) ||
     miss_sched_query_take ||
     miss_sched_temporal_take ||
     miss_recent_keep ||
     (miss_h2o_class != KCMU_H2O_NEITHER));
`elsif KCMU_CFG_FPGA_KILOSCORE_L2MISS_RB_RESCUE6_V886
  // v886: stricter v885; require stronger observed group-throttle debt.
  assign miss_l2miss_read_bypass_rescue =
    !miss_is_prefetch &&
    (group_throttle_credit >= 3'd6) &&
    (rw_density_credit <= 4'd6) &&
    !miss_backend_write_pressure &&
    ((miss_utility_score >= SCORE_W'(8'h80)) ||
     miss_sched_query_take ||
     miss_sched_temporal_take ||
     miss_recent_keep ||
     (miss_h2o_class != KCMU_H2O_NEITHER));
`elsif KCMU_CFG_FPGA_KILOSCORE_L2MISS_RECENT_RB_RESCUE4_V887
  // v887: recent/H2O-only rescue.  This isolates whether the bypass loss is
  // specifically from recent-only backend lines rather than generic utility.
  assign miss_l2miss_read_bypass_rescue =
    !miss_is_prefetch &&
    (group_throttle_credit >= 3'd4) &&
    (rw_density_credit <= 4'd6) &&
    !miss_backend_write_pressure &&
    miss_recent_keep &&
    (miss_h2o_class != KCMU_H2O_NEITHER);
`else
  assign miss_l2miss_read_bypass_rescue = 1'b0;
`endif
`ifdef KCMU_CFG_FPGA_KILOSCORE_DESC_TARGET_RB_REFILL_RESCUE_BROAD_V868
  // v868: broader descriptor-target refill rescue.  v861 was too selective
  // and did not move the MDQA read-bypass rows; this variant still requires
  // a descriptor-target demand miss and non-depleted GF feedback, but removes
  // descriptor-class/query thresholds so the actual L2 admission path can
  // repair target-induced backend demand debt.
  assign desc_target_read_bypass_rescue =
    miss_group_target_valid &&
    !miss_is_prefetch &&
    (group_feedback_credit >= 3'd3) &&
    (rw_density_credit <= 4'd6) &&
    !miss_backend_write_pressure;
`elsif KCMU_CFG_FPGA_KILOSCORE_DESC_TARGET_RB_REFILL_RESCUE_V861
  // v861: rescue only strong descriptor-target demand responses that would
  // otherwise bypass L2.  This uses observed hierarchy pressure, not a trace
  // name or model-specific selector.
  assign desc_target_read_bypass_rescue =
    miss_group_target_valid &&
    !miss_is_prefetch &&
    (miss_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) &&
    (miss_query_relevance >= SCORE_W'(8'h78)) &&
    (miss_utility_score >= SCORE_W'(8'h68)) &&
    (group_feedback_credit >= 3'd3) &&
    (rw_density_credit <= 4'd6) &&
    !miss_backend_write_pressure;
`else
  assign desc_target_read_bypass_rescue = 1'b0;
`endif
  assign read_bus_idle = (read_owner == READ_NONE);
  assign demand_resp_valid = (read_owner == READ_DEMAND) && mem_rvalid;
  assign group_resp_valid = (read_owner == READ_GROUP) && mem_rvalid;
  assign fill_req_query_admit_event =
    demand_resp_valid && fill_read_fill_enable &&
    (miss_query_relevance >= SCORE_W'(8'hA8)) &&
    (miss_utility_score >= SCORE_W'(8'h80));
  assign fill_req_comp_bits = choose_comp_bits(miss_qos, miss_is_prefetch);
  assign fill_req_lossy_fill =
    miss_compress_allow &&
    LOSSY_COMPRESS_EN &&
    (miss_is_prefetch || (miss_qos <= COMPRESS_QOS_TH)) &&
    (max_err_for_bits(fill_req_comp_bits) <= COMP_ERR_CAP);
  assign group_fetch_stride_ext = (ADDR_W+1)'(GROUP_FETCH_ADDR_STRIDE);
  assign group_fetch_stride2_ext = group_fetch_stride_ext << 1;
  assign group_lane_idx =
    (GROUP_FETCH_LANES <= 1) ? {GROUP_FETCH_LANE_IDX_W{1'b0}} :
    miss_addr[GROUP_FETCH_LANE_IDX_W-1:0];
  assign group_lane_match =
    group_lane_valid[group_lane_idx] &&
    (miss_addr == (group_lane_last_addr[group_lane_idx] + ADDR_W'(GROUP_FETCH_ADDR_STRIDE)));
  assign group_match_delta_sel = group_lane_match ? 2'd1 : 2'd0;
  assign group_match_stride = group_lane_match;
  assign group_match_same_delta = group_lane_match;
  assign group_pollution_block = &(gb_valid_mem & ~gb_used_mem);
  assign group_insert_pollution_risk = gb_valid_mem[gb_insert_idx] && !gb_used_mem[gb_insert_idx];
`ifdef KCMU_CFG_FPGA_KILOSCORE_SLIDING_GF_V408
  assign group_sliding_value_gate =
    group_lane_valid[group_lane_idx] &&
    group_match_stride &&
    (group_lane_conf[group_lane_idx] != 3'd0) &&
    !group_pollution_block &&
    (group_write_quiet_cnt >= GROUP_FETCH_WRITE_QUIET_TH) &&
    (rw_density_credit <= 4'd3) &&
    (group_feedback_credit >= 3'd3) &&
    (miss_query_structure_class <= kcmu_pkg::KCMU_DESC_CLASS_W'(1));
  assign group_useful_ready =
    (group_lane_conf[group_lane_idx] >= GROUP_FETCH_CONF_TH) ||
    group_sliding_value_gate;
`elsif KCMU_CFG_FPGA_KILOSCORE_TINY_SLIDE_GF_RESCUE_V723
  // v723: recover only the tiny-window stride side-path that v722 loses when
  // its stricter HH threshold suppresses all H2O candidates.  This is bounded
  // to the small L2/CVR/GB cells where v722 keeps a sliding-window residual
  // negative, and still requires confirmed stride, write quiet, and no GB
  // pollution.  It does not relax replacement or CVR admission.
  assign group_sliding_value_gate =
    (L2_LINES <= 32) &&
    (VB_LINES <= 8) &&
    (GROUP_BUF_LINES <= 2) &&
    group_lane_valid[group_lane_idx] &&
    group_match_stride &&
    (group_lane_conf[group_lane_idx] != 3'd0) &&
    !group_pollution_block &&
    (group_write_quiet_cnt >= GROUP_FETCH_WRITE_QUIET_TH) &&
    (rw_density_credit <= 4'd3) &&
    (miss_query_structure_class <= kcmu_pkg::KCMU_DESC_CLASS_W'(1));
  assign group_useful_ready =
    (group_lane_conf[group_lane_idx] >= GROUP_FETCH_CONF_TH) ||
    group_sliding_value_gate;
`elsif KCMU_CFG_FPGA_KILOSCORE_CAP_Q1_GFCONF_GUARD_V718
  assign group_sliding_value_gate = 1'b0;
  assign group_useful_ready =
    ((L2_LINES <= 32) &&
     (VB_LINES <= 8) &&
     (GROUP_BUF_LINES <= 2) &&
     (miss_query_structure_class == kcmu_pkg::KCMU_DESC_CLASS_W'(1))) ?
      (group_lane_conf[group_lane_idx] >= 3'd1) :
      (group_lane_conf[group_lane_idx] >= GROUP_FETCH_CONF_TH);
`else
  assign group_sliding_value_gate = 1'b0;
  assign group_useful_ready = (group_lane_conf[group_lane_idx] >= GROUP_FETCH_CONF_TH);
`endif
`ifdef KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_HASP_SAFE_GROUP_V270
  // v270: allow already-confirmed stride streams to bypass the old
  // non-zero descriptor-class gate, while keeping v251's pollution,
  // useful-credit, cached-target, and owner-FSM safeguards intact.
  assign group_hasp_safe_stride_gate =
    group_lane_valid[group_lane_idx] &&
    group_match_stride &&
    (
      (miss_query_relevance >= SCORE_W'(8'h80)) ||
      (miss_query_structure_class <= kcmu_pkg::KCMU_DESC_CLASS_W'(1)) ||
      (miss_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3))
    );
`else
  assign group_hasp_safe_stride_gate = 1'b0;
`endif
  assign group_structure_gate_ok =
    (miss_query_structure_class != {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}}) ||
    group_hasp_safe_stride_gate ||
    group_sliding_value_gate;
`ifdef KCMU_KILOSCORE_CVR_GF_V384_ACTIVE
  // v384: suppress only the speculative Group Fill side path when class
  // switching and write pressure make the group buffer a weak value signal.
  assign group_mixed_nsa_guard =
    kiloscore_path_enable &&
    group_class_seen &&
    (group_class_switch_credit >= 3'd3) &&
    (rw_density_credit >= 4'd5) &&
    (miss_query_structure_class != {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}});
`elsif KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_MIXED_NSA_GUARD_V288
  // v288: mixed-NSA class diversity guard.  The HASP proxy sweeps showed
  // that spatial/locality-biased policies tend to trade sliding-window wins
  // for mixed-NSA pollution.  This guard is intentionally tiny: a saturating
  // switch counter over FPGA-visible descriptor classes.  It suppresses only
  // the speculative Group Fill side path, leaving demand, CVR, and read-owner
  // semantics unchanged.
  assign group_mixed_nsa_guard =
    group_class_seen &&
    (group_class_switch_credit >= 3'd3) &&
    (miss_query_structure_class != {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}});
`elsif KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_UNUSED_MIXED_GUARD_V304
  // v304: narrower mixed-NSA guard.  Block the side-path only when descriptor
  // class is unstable and GB already contains unused speculative data; the
  // first group fill in a run is still allowed.
  assign group_mixed_nsa_guard =
    group_class_seen &&
    (group_class_switch_credit >= 3'd2) &&
    (miss_query_structure_class != {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}}) &&
    (|(gb_valid_mem & ~gb_used_mem));
`elsif KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_PREFIX_BLOCK_V324
  // v324: special/prefix descriptors were the only class where faster issue
  // created a repeatable multimodal regression.  This candidate removes that
  // class from the speculative GF side path while preserving CVR and demand
  // behavior; it tests whether v320's improvement is due to avoiding prefix
  // GF pollution rather than just issuing later.
  assign group_mixed_nsa_guard =
    (miss_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3));
`elsif KCMU_CFG_FPGA_KILOSCORE_NATIVE_STANDALONE
  // Native KiloScore uses the group buffer's own feedback as a cheap
  // hardware-value signal: if speculative neighbors are still unused, class
  // switching or non-anchor structured fills must earn more useful credit
  // before issuing another side-path fill.
  assign group_mixed_nsa_guard =
    !((L1_LINES >= 64) && (L2_LINES >= 128) && (GROUP_BUF_LINES >= 8)) &&
    (
      ((L2_LINES <= 16) &&
       (VB_LINES >= 16) &&
       (GROUP_BUF_LINES <= 2) &&
       group_class_seen &&
       (group_class_switch_credit >= 3'd2) &&
       (group_feedback_credit <= 3'd5) &&
       (miss_query_structure_class != {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}}) &&
       (miss_query_relevance < SCORE_W'(8'hD0))) ||
       ((L2_LINES > 16) &&
       (|(gb_valid_mem & ~gb_used_mem)) &&
       (
         ((group_feedback_credit <= 3'd4) &&
          (
            ((miss_query_structure_class != {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}}) &&
             group_class_seen && (group_class_switch_credit >= 3'd2)) ||
            ((miss_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) &&
             (miss_query_relevance < SCORE_W'(8'hE0)))
          ))
       ))
    );
`elsif KCMU_CFG_FPGA_KILOSCORE_PREFIX_SWITCH_CAP_GUARD_V769
  // v769 assigns this guard in the capacity-scoped KiloScore branch above.
  // Keep this branch empty so the generic fallback does not create a second
  // continuous driver on group_mixed_nsa_guard.
`else
  assign group_mixed_nsa_guard = 1'b0;
`endif
`ifdef KCMU_KILOSCORE_CVR_GF_V384_ACTIVE
  assign group_feedback_block =
    kiloscore_path_enable &&
    ((group_feedback_credit <= 3'd1) ||
     (group_pollution_block && (group_activity_credit == 3'd0)));
`elsif KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_POLLUTION_CREDIT_V289
  // v289: feedback-driven GF pollution credit.  Unlike v288's descriptor
  // diversity heuristic, this uses the side path's own outcome: useful GB hits
  // earn credit; overwriting an unused GB entry spends credit.  When credit is
  // depleted, GF is temporarily throttled but demand/CVR behavior is untouched.
  assign group_feedback_block =
    (group_feedback_credit <= 3'd1) &&
    (miss_query_structure_class != {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}});
`elsif KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_GLOBAL_POLLUTION_CREDIT_V291
  // v291: global version of v289.  Descriptor class was too sparse on real
  // smoke traces, so this variant lets GB's own useful/pollution feedback
  // throttle GF regardless of descriptor class.  It is still side-path-only.
  assign group_feedback_block = (group_feedback_credit <= 3'd1);
`elsif KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_FAST_BACKOFF_V292
  // v292: faster backoff.  A single unused-overwrite pollution event can put
  // GF into cooldown; useful GB hits restore credit faster.  This tests whether
  // real 7B traces with sparse pollution can translate credit feedback into
  // visible AMAT/HBM movement.
  assign group_feedback_block = (group_feedback_credit <= 3'd2);
`elsif KCMU_CFG_FPGA_KILOSCORE_NATIVE_STANDALONE
  assign group_feedback_block =
    (GROUP_BUF_LINES >= 4) &&
    (L2_LINES <= 32) &&
    (group_hhfloor_backoff_credit >= 3'd2) &&
    (group_feedback_credit <= 3'd5) &&
    (miss_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3));
`elsif KCMU_CFG_FPGA_KILOSCORE_PREFIX_SWITCH_CAP_GUARD_V769
  // v769 assigns this block in the capacity-scoped KiloScore branch above.
  // Keep this branch empty so the generic fallback does not create a second
  // continuous driver on group_feedback_block.
`else
  assign group_feedback_block = 1'b0;
`endif
`ifdef KCMU_CFG_FPGA_KILOSCORE_SEARCH_CAPACITY_CORRIDOR_RESTORE_V1475
  assign group_target_feedback_block =
    (miss_group_target_valid && fill_capacity_corridor_restore_v1475) ||
    (miss_group_target_valid && fill_largecap_hotdeficit_restore_v1475) ||
`ifdef KCMU_CFG_FPGA_KILOSCORE_SEARCH_LARGECAP_QSTRUCT_HOT_GAP_GF_BRAKE_V1476
    (miss_group_target_valid &&
     (L1_LINES >= 64) &&
     (L2_LINES >= 128) &&
     (GROUP_BUF_LINES >= 8) &&
     (miss_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) &&
     !miss_sem_hot) ||
`endif
`ifdef KCMU_CFG_FPGA_KILOSCORE_SEARCH_LARGECAP_QSTRUCT_GF_RESTORE_V1477
    (miss_group_target_valid &&
     (L1_LINES >= 64) &&
     (L2_LINES >= 128) &&
     (GROUP_BUF_LINES >= 8) &&
     (miss_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3))) ||
`endif
    (miss_group_target_valid &&
     (L1_LINES >= 64) &&
     (L2_LINES >= 128) &&
     (GROUP_BUF_LINES >= 8) &&
     (miss_query_structure_class == kcmu_pkg::KCMU_DESC_CLASS_W'(1)) &&
     group_class_seen &&
     (group_class_switch_credit >= 3'd1));
`elsif KCMU_CFG_FPGA_KILOSCORE_SEARCH_LARGECAP_CLASSSW_Q1_GF_BRAKE_V1470
