        ((L1_LINES <= 16) && (L2_LINES == 32) &&
         (VB_LINES <= 8) && (GROUP_BUF_LINES <= 2) &&
         (rd_req_query_structure_class == kcmu_pkg::KCMU_DESC_CLASS_W'(1)) &&
         (rd_req_q1_run_cnt == 3'd7))
      ));
`elsif KCMU_CFG_FPGA_KILOSCORE_PREFIX_DENSITY6_OWNER_HIDDEN_V764
  // v764: midpoint threshold between v762 (too conservative) and v763
  // (too permissive), still using the same prefix-density evidence source.
  assign rd_req_immediate_resp_visible =
    !((GROUP_FETCH_TO_CVR_EN && VB_CLEAN_ACTIVE &&
       (read_owner == READ_GROUP) && !deferred_req_valid) &&
      (
        ((L1_LINES >= 64) && (L2_LINES >= 128) &&
         (group_prefix_density_credit >= 4'd6)) ||
        ((L1_LINES <= 16) && (L2_LINES == 32) &&
         (VB_LINES <= 8) && (GROUP_BUF_LINES <= 2) &&
         (rd_req_query_structure_class == kcmu_pkg::KCMU_DESC_CLASS_W'(1)) &&
         (rd_req_q1_run_cnt == 3'd7))
      ));
`elsif KCMU_CFG_FPGA_KILOSCORE_PREFIX_DENSITY10_OWNER_HIDDEN_V763
  // v763: raise v762's prefix-density threshold so short, isolated mixed-NSA
  // descriptor bursts keep v749's owner-visible benefit, while sustained
  // NSA/global-token runs still fall back to v251 owner-hidden semantics.
  assign rd_req_immediate_resp_visible =
    !((GROUP_FETCH_TO_CVR_EN && VB_CLEAN_ACTIVE &&
       (read_owner == READ_GROUP) && !deferred_req_valid) &&
      (
        ((L1_LINES >= 64) && (L2_LINES >= 128) &&
         (group_prefix_density_credit >= 4'd10)) ||
        ((L1_LINES <= 16) && (L2_LINES == 32) &&
         (VB_LINES <= 8) && (GROUP_BUF_LINES <= 2) &&
         (rd_req_query_structure_class == kcmu_pkg::KCMU_DESC_CLASS_W'(1)) &&
         (rd_req_q1_run_cnt == 3'd7))
      ));
`elsif KCMU_CFG_FPGA_KILOSCORE_PREFIX_DENSITY_OWNER_HIDDEN_V762
  // v762: distinguish isolated mixed-NSA prefix/special descriptors from
  // sustained NSA/global-token runs.  The former benefited from v749's visible
  // owner path; the latter created the large-capacity nsa_triclass negative.
  assign rd_req_immediate_resp_visible =
    !((GROUP_FETCH_TO_CVR_EN && VB_CLEAN_ACTIVE &&
       (read_owner == READ_GROUP) && !deferred_req_valid) &&
      (
        ((L1_LINES >= 64) && (L2_LINES >= 128) &&
         (group_prefix_density_credit >= 4'd4)) ||
        ((L1_LINES <= 16) && (L2_LINES == 32) &&
         (VB_LINES <= 8) && (GROUP_BUF_LINES <= 2) &&
         (rd_req_query_structure_class == kcmu_pkg::KCMU_DESC_CLASS_W'(1)) &&
         (rd_req_q1_run_cnt == 3'd7))
      ));
`elsif KCMU_CFG_FPGA_KILOSCORE_LARGENSA_OWNER_HIDDEN_V759
  // v759: v749's best frontier still had small large-capacity regressions on
  // tri-class NSA rows.  Keep v727's tiny sliding-window rescue, but restore
  // v251 owner-hidden semantics when a large hierarchy is servicing
  // prefix/special NSA descriptors through the Group Fill owner.
  assign rd_req_immediate_resp_visible =
    !((GROUP_FETCH_TO_CVR_EN && VB_CLEAN_ACTIVE &&
       (read_owner == READ_GROUP) && !deferred_req_valid) &&
      (
        ((L1_LINES >= 64) && (L2_LINES >= 128) &&
         (rd_req_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3))) ||
        ((L1_LINES <= 16) && (L2_LINES == 32) &&
         (VB_LINES <= 8) && (GROUP_BUF_LINES <= 2) &&
         (rd_req_query_structure_class == kcmu_pkg::KCMU_DESC_CLASS_W'(1)) &&
         (rd_req_q1_run_cnt == 3'd7))
      ));
`elsif KCMU_CFG_FPGA_KILOSCORE_Q1_SAT_TINY_OWNER_VISIBLE_V727
  // v727: stricter v726.  Require the q1-run observer to saturate before
  // owner-visibility rescue so short mixed-NSA q1 islands do not open Group
  // Fill service.
  assign rd_req_immediate_resp_visible =
    !((GROUP_FETCH_TO_CVR_EN && VB_CLEAN_ACTIVE &&
       (read_owner == READ_GROUP) && !deferred_req_valid) &&
      (L1_LINES <= 16) && (L2_LINES == 32) &&
      (VB_LINES <= 8) && (GROUP_BUF_LINES <= 2) &&
      (rd_req_query_structure_class == kcmu_pkg::KCMU_DESC_CLASS_W'(1)) &&
      (rd_req_q1_run_cnt == 3'd7));
`elsif KCMU_CFG_FPGA_KILOSCORE_Q1_PURE_TINY_OWNER_VISIBLE_V726
  // v726: add a tiny q1-run observer before using the owner-visibility
  // rescue.  Pure sliding-window streams build consecutive q1 confidence;
  // mixed-NSA alternates q3/q0/q1 and should not take the rescue.
  assign rd_req_immediate_resp_visible =
    !((GROUP_FETCH_TO_CVR_EN && VB_CLEAN_ACTIVE &&
       (read_owner == READ_GROUP) && !deferred_req_valid) &&
      (L1_LINES <= 16) && (L2_LINES == 32) &&
      (VB_LINES <= 8) && (GROUP_BUF_LINES <= 2) &&
      (rd_req_query_structure_class == kcmu_pkg::KCMU_DESC_CLASS_W'(1)) &&
      (rd_req_q1_run_cnt >= 3'd3));
`elsif KCMU_CFG_FPGA_KILOSCORE_Q1_TINY_OWNER_VISIBLE_V725
  // v725: keep v722 scoring, but apply v251 read-owner visibility only in
  // the tiny local-window capacity regime that v724 repaired.  This avoids
  // the mid-CVR sliding-window side effect seen when v724 was enabled globally.
  assign rd_req_immediate_resp_visible =
    !((GROUP_FETCH_TO_CVR_EN && VB_CLEAN_ACTIVE &&
       (read_owner == READ_GROUP) && !deferred_req_valid) &&
      (L2_LINES == 32) && (VB_LINES <= 8) && (GROUP_BUF_LINES <= 2) &&
      (rd_req_query_structure_class == kcmu_pkg::KCMU_DESC_CLASS_W'(1)));
`elsif KCMU_CFG_FPGA_KILOSCORE_GROUP_OWNER_VISIBLE_V724
  // v724: keep v722 scoring, but use v251's read-owner visibility rule.
  // This isolates whether the residual tiny sliding-window loss is caused by
  // response visibility during owner-safe Group Fill service rather than by
  // the score threshold itself.
  assign rd_req_immediate_resp_visible =
    !(GROUP_FETCH_TO_CVR_EN && VB_CLEAN_ACTIVE &&
      (read_owner == READ_GROUP) && !deferred_req_valid);
`elsif KCMU_CFG_FPGA_KILOSCORE_DENSE_LATCH_THRESHOLD_EXTRA_CVR_V704
  assign rd_req_immediate_resp_visible =
    !(GROUP_FETCH_TO_CVR_EN && VB_CLEAN_ACTIVE &&
      (read_owner == READ_GROUP) && !deferred_req_valid);
`elsif KCMU_CFG_FPGA_KILOSCORE_PHASE_THRESHOLD_EXTRA_CVR_V703
  assign rd_req_immediate_resp_visible =
    !(GROUP_FETCH_TO_CVR_EN && VB_CLEAN_ACTIVE &&
      (read_owner == READ_GROUP) && !deferred_req_valid);
`elsif KCMU_CFG_FPGA_KILOSCORE_WINDOW_DENSE_PHASE_TINY_EXTRA_CVR_V702
  assign rd_req_immediate_resp_visible =
    !(GROUP_FETCH_TO_CVR_EN && VB_CLEAN_ACTIVE &&
