`elsif KCMU_CFG_FPGA_KILOSCORE_TARGET_DEBT_DESC_TARGET_EXTRA_CVR_V638
  assign rd_req_immediate_resp_visible =
    !(GROUP_FETCH_TO_CVR_EN && VB_CLEAN_ACTIVE &&
