`elsif KCMU_CFG_FPGA_KILOSCORE_NSA_LENSAFE_DESC_TARGET_EXTRA_CVR_V637
  assign rd_req_immediate_resp_visible =
    !(GROUP_FETCH_TO_CVR_EN && VB_CLEAN_ACTIVE &&
      (read_owner == READ_GROUP) && !deferred_req_valid);
`elsif KCMU_CFG_FPGA_KILOSCORE_NSA_KV0_DESC_TARGET_EXTRA_CVR_V636
  assign rd_req_immediate_resp_visible =
    !(GROUP_FETCH_TO_CVR_EN && VB_CLEAN_ACTIVE &&
      (read_owner == READ_GROUP) && !deferred_req_valid);
`elsif KCMU_CFG_FPGA_KILOSCORE_NSA_DESC_TARGET_EXTRA_CVR_V635
  assign rd_req_immediate_resp_visible =
    !(GROUP_FETCH_TO_CVR_EN && VB_CLEAN_ACTIVE &&
      (read_owner == READ_GROUP) && !deferred_req_valid);
`elsif KCMU_CFG_FPGA_KILOSCORE_NSA_RAIL_QSIG1_EXTRA_CVR_V634
  assign rd_req_immediate_resp_visible =
    !(GROUP_FETCH_TO_CVR_EN && VB_CLEAN_ACTIVE &&
      (read_owner == READ_GROUP) && !deferred_req_valid);
`elsif KCMU_CFG_FPGA_KILOSCORE_NSA_RAIL_EXTRA_CVR_V633
  assign rd_req_immediate_resp_visible =
    !(GROUP_FETCH_TO_CVR_EN && VB_CLEAN_ACTIVE &&
      (read_owner == READ_GROUP) && !deferred_req_valid);
`elsif KCMU_CFG_FPGA_KILOSCORE_HOST_PROFILE_EXTRA_CVR_V632
  assign rd_req_immediate_resp_visible =
    !(GROUP_FETCH_TO_CVR_EN && VB_CLEAN_ACTIVE &&
      (read_owner == READ_GROUP) && !deferred_req_valid);
`elsif KCMU_CFG_FPGA_KILOSCORE_HOST_PROFILE_EXTRA_CVR_V630
  assign rd_req_immediate_resp_visible =
    !(GROUP_FETCH_TO_CVR_EN && VB_CLEAN_ACTIVE &&
      (read_owner == READ_GROUP) && !deferred_req_valid);
`elsif KCMU_CFG_FPGA_KILOSCORE_CMDQ_LOOKAHEAD_GF_V409
  assign rd_req_immediate_resp_visible =
    !(GROUP_FETCH_TO_CVR_EN && VB_CLEAN_ACTIVE &&
      (read_owner == READ_GROUP) && !deferred_req_valid);
`else
  assign rd_req_immediate_resp_visible = 1'b1;
`endif
  assign rd_req_immediate_hit_visible = rd_req_immediate_resp_visible && rd_req_re;

`ifdef KCMU_CFG_FPGA_KILOSCORE_NATIVE_STANDALONE
  assign req_rhit = (rd_req_immediate_hit_visible && read_hit) ||
                    clean_side_resp_valid ||
                    (rd_req_immediate_hit_visible && gb_read_hit_eff) ||
                    (rd_req_immediate_hit_visible && clean_vb_immediate_hit);
  // mem_rvalid may return after req_re deasserts; keep response visible.
  assign req_rvalid = clean_side_resp_valid ||
                      (rd_req_immediate_hit_visible &&
                       (read_hit ||
                        gb_read_hit_eff ||
                        clean_vb_immediate_hit)) ||
                      (miss_pending && miss_issued && demand_resp_valid);
  assign req_rlossy = (rd_req_immediate_hit_visible && read_hit) ? read_hit_lossy :
                      ((rd_req_immediate_hit_visible && gb_read_hit_eff) ? 1'b0 :
                       ((rd_req_immediate_hit_visible && clean_vb_immediate_hit) ? (VB_CLEAN_ACTIVE ? 1'b0 : vb_read_lossy) : 1'b0));
  assign req_rdata = clean_side_resp_valid ? clean_side_resp_data :
                    ((rd_req_immediate_hit_visible && read_hit) ? (read_hit_lossy ? decompress_data(comp_mem[r_hit_idx], comp_bits_mem[r_hit_idx]) : data_mem[r_hit_idx]) :
                    ((rd_req_immediate_hit_visible && gb_read_hit_eff) ? gb_data_mem[gb_read_idx] :
                     ((rd_req_immediate_hit_visible && clean_vb_immediate_hit) ? (VB_CLEAN_ACTIVE ? vb_data_mem[vb_read_idx] : vb_read_data) :
                      ((miss_pending && miss_issued && demand_resp_valid) ? mem_rdata : {DATA_W{1'b0}}))));
  assign req_rsource = clean_side_resp_valid ? L2_RESP_SRC_CVR :
                       ((rd_req_immediate_hit_visible && read_hit) ? L2_RESP_SRC_MAIN_L2 :
                       ((rd_req_immediate_hit_visible && gb_read_hit_eff) ? L2_RESP_SRC_GF :
                        ((rd_req_immediate_hit_visible && clean_vb_immediate_hit) ? L2_RESP_SRC_CVR :
                         ((miss_pending && miss_issued && demand_resp_valid) ? L2_RESP_SRC_BACKEND : L2_RESP_SRC_NONE))));
`else
  assign req_rhit = read_hit ||
                    clean_side_resp_valid ||
                    (rd_req_re && gb_read_hit_eff) ||
                    (rd_req_re && clean_vb_immediate_hit);
  // mem_rvalid may return after req_re deasserts; keep response visible.
  assign req_rvalid = clean_side_resp_valid ||
                      (rd_req_immediate_resp_visible &&
                       rd_req_re && (read_hit ||
                                     gb_read_hit_eff ||
                                     clean_vb_immediate_hit)) ||
                      (miss_pending && miss_issued && demand_resp_valid);
  assign req_rlossy = (rd_req_re && read_hit) ? read_hit_lossy :
                      ((rd_req_re && gb_read_hit_eff) ? 1'b0 :
                       ((rd_req_re && clean_vb_immediate_hit) ? (VB_CLEAN_ACTIVE ? 1'b0 : vb_read_lossy) : 1'b0));
  assign req_rdata = clean_side_resp_valid ? clean_side_resp_data :
                    ((rd_req_re && read_hit) ? (read_hit_lossy ? decompress_data(comp_mem[r_hit_idx], comp_bits_mem[r_hit_idx]) : data_mem[r_hit_idx]) :
                    ((rd_req_re && gb_read_hit_eff) ? gb_data_mem[gb_read_idx] :
                     ((rd_req_re && clean_vb_immediate_hit) ? (VB_CLEAN_ACTIVE ? vb_data_mem[vb_read_idx] : vb_read_data) : mem_rdata)));
  assign req_rsource = clean_side_resp_valid ? L2_RESP_SRC_CVR :
                       ((rd_req_re && read_hit) ? L2_RESP_SRC_MAIN_L2 :
                       ((rd_req_re && gb_read_hit_eff) ? L2_RESP_SRC_GF :
                        ((rd_req_re && clean_vb_immediate_hit) ? L2_RESP_SRC_CVR :
                         ((miss_pending && miss_issued && demand_resp_valid) ? L2_RESP_SRC_BACKEND : L2_RESP_SRC_NONE))));
`endif

`ifdef KCMU_L2_GROUP_FILL_ACTIVE
  always @(*) begin
    integer gb_ri;
    gb_read_hit = 1'b0;
    gb_read_idx = {GROUP_BUF_IDX_W{1'b0}};
    if (GROUP_FETCH_TO_CVR_EN && rd_req_re) begin
      for (gb_ri = 0; gb_ri < GROUP_BUF_LINES; gb_ri = gb_ri + 1) begin
        if (!gb_read_hit && gb_valid_mem[gb_ri] && (gb_tag_mem[gb_ri] == rd_req_raddr)) begin
          gb_read_hit = 1'b1;
          gb_read_idx = gb_ri[GROUP_BUF_IDX_W-1:0];
        end
      end
    end
  end
`else
  always @(*) begin
    gb_read_hit = 1'b0;
    gb_read_idx = {GROUP_BUF_IDX_W{1'b0}};
  end
`endif

  always @(*) begin
    vb_read_hit = 1'b0;
    vb_read_idx = {VB_IDX_W{1'b0}};
    vb_read_lossy = 1'b0;
    vb_read_data = {DATA_W{1'b0}};
    if (VB_ENABLE && rd_req_re) begin
      for (vi = 0; vi < VB_LINES; vi = vi + 1) begin
        if (!vb_read_hit && vb_valid_mem[vi] && (vb_tag_mem[vi] == rd_req_raddr)) begin
          vb_read_hit = 1'b1;
          vb_read_idx = vi[VB_IDX_W-1:0];
          vb_read_lossy = VB_CLEAN_ACTIVE ? 1'b0 : vb_lossy_mem[vi];
          vb_read_data = VB_CLEAN_ACTIVE ? vb_data_mem[vi] :
                         (vb_lossy_mem[vi] ? decompress_data(vb_comp_mem[vi], vb_comp_bits_mem[vi]) : vb_data_mem[vi]);
        end
      end
    end
  end

`ifdef KCMU_L2_GROUP_FILL_ACTIVE
  always @(*) begin
    integer gb_wi;
    gb_write_hit = 1'b0;
    gb_write_idx = {GROUP_BUF_IDX_W{1'b0}};
    if (GROUP_FETCH_TO_CVR_EN) begin
      for (gb_wi = 0; gb_wi < GROUP_BUF_LINES; gb_wi = gb_wi + 1) begin
        if (!gb_write_hit && gb_valid_mem[gb_wi] && (gb_tag_mem[gb_wi] == req_waddr)) begin
          gb_write_hit = 1'b1;
          gb_write_idx = gb_wi[GROUP_BUF_IDX_W-1:0];
        end
      end
    end
  end
`else
  always @(*) begin
    gb_write_hit = 1'b0;
    gb_write_idx = {GROUP_BUF_IDX_W{1'b0}};
  end
`endif

`ifdef KCMU_L2_GROUP_FILL_ACTIVE
  always @(*) begin
    integer gb_ti;
    group_next_gb_hit = 1'b0;
    if (GROUP_FETCH_TO_CVR_EN) begin
      for (gb_ti = 0; gb_ti < GROUP_BUF_LINES; gb_ti = gb_ti + 1) begin
        if (!group_next_gb_hit && gb_valid_mem[gb_ti] && (gb_tag_mem[gb_ti] == group_next_addr)) begin
          group_next_gb_hit = 1'b1;
        end
      end
    end
  end
`else
  always @(*) begin
    group_next_gb_hit = 1'b0;
  end
`endif

  always @(*) begin
    vb_write_hit = 1'b0;
    vb_write_idx = {VB_IDX_W{1'b0}};
    if (VB_ENABLE && !VB_CLEAN_ACTIVE) begin
      for (vi = 0; vi < VB_LINES; vi = vi + 1) begin
        if (!vb_write_hit && vb_valid_mem[vi] && (vb_tag_mem[vi] == req_waddr)) begin
          vb_write_hit = 1'b1;
          vb_write_idx = vi[VB_IDX_W-1:0];
        end
      end
    end
  end

  always @(*) begin
    gb_has_invalid = 1'b0;
    gb_has_reclaim = 1'b0;
    gb_insert_idx = gb_rr_ptr;
    if (GROUP_FETCH_TO_CVR_EN) begin
      for (vi = 0; vi < GROUP_BUF_LINES; vi = vi + 1) begin
        if (!gb_has_invalid && !gb_valid_mem[vi]) begin
          gb_has_invalid = 1'b1;
          gb_insert_idx = vi[GROUP_BUF_IDX_W-1:0];
        end
      end
`ifdef KCMU_CFG_FPGA_KILOSCORE_LATCHED_RISK_GB_USED_FIRST_V744
      // v744: latch the risk class at Group Fill enqueue time, then use that
      // stable bit at response insertion.  The current miss descriptor can
      // advance before the group response returns, so v743's combinational
      // check was too late to steer placement.
      if (!gb_has_invalid && group_used_first_risk) begin
        for (vi = 0; vi < GROUP_BUF_LINES; vi = vi + 1) begin
          if (!gb_has_reclaim && gb_valid_mem[vi] && gb_used_mem[vi]) begin
            gb_has_reclaim = 1'b1;
            gb_insert_idx = vi[GROUP_BUF_IDX_W-1:0];
          end
        end
      end
`elsif KCMU_CFG_FPGA_KILOSCORE_RISK_GB_USED_FIRST_V743
      // v743: v742 showed used-first placement removes prefix/multimodal GB
      // pollution, but applying it globally destroys sliding-window useful GF.
      // Restrict used-first replacement to descriptor classes where pollution
      // risk was observed: prefix/special or unstable class-switch streams.
      if (!gb_has_invalid &&
          ((miss_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) ||
           (group_class_seen && (group_class_switch_credit >= 3'd2)))) begin
        for (vi = 0; vi < GROUP_BUF_LINES; vi = vi + 1) begin
          if (!gb_has_reclaim && gb_valid_mem[vi] && gb_used_mem[vi]) begin
            gb_has_reclaim = 1'b1;
            gb_insert_idx = vi[GROUP_BUF_IDX_W-1:0];
          end
        end
      end
`elsif KCMU_CFG_FPGA_KILOSCORE_NATIVE_STANDALONE
      if (!gb_has_invalid &&
          ((GROUP_BUF_LINES <= 4) || (L2_LINES <= 64)) &&
          group_used_first_risk) begin
        for (vi = 0; vi < GROUP_BUF_LINES; vi = vi + 1) begin
          if (!gb_has_reclaim && gb_valid_mem[vi] && gb_used_mem[vi]) begin
            gb_has_reclaim = 1'b1;
            gb_insert_idx = vi[GROUP_BUF_IDX_W-1:0];
          end
        end
      end
`elsif KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_GB_USED_FIRST_V290
      // v290: once GB has no invalid slot, evict an already-used group entry
      // before overwriting an unused one.  This is a pure placement change
      // inside the side buffer and does not alter demand/CVR/read-owner paths.
      if (!gb_has_invalid) begin
        for (vi = 0; vi < GROUP_BUF_LINES; vi = vi + 1) begin
          if (!gb_has_reclaim && gb_valid_mem[vi] && gb_used_mem[vi]) begin
            gb_has_reclaim = 1'b1;
            gb_insert_idx = vi[GROUP_BUF_IDX_W-1:0];
          end
        end
      end
`endif
    end
  end

`ifdef KCMU_L2_GROUP_FILL_ACTIVE
  always @(*) begin
    integer vb_ti;
    group_next_vb_hit = 1'b0;
    if (VB_ENABLE) begin
      for (vb_ti = 0; vb_ti < VB_LINES; vb_ti = vb_ti + 1) begin
        if (!group_next_vb_hit && vb_valid_mem[vb_ti] && (vb_tag_mem[vb_ti] == group_next_addr)) begin
          group_next_vb_hit = 1'b1;
        end
      end
    end
  end
`else
  always @(*) begin
    group_next_vb_hit = 1'b0;
  end
`endif

  always @(*) begin
    vb_has_invalid = 1'b0;
    vb_insert_idx = vb_rr_ptr;
    vb_lattice_pick_found = 1'b0;
    vb_lattice_scan_idx = {VB_IDX_W{1'b0}};
    if (VB_ENABLE) begin
      for (vi = 0; vi < VB_LINES; vi = vi + 1) begin
        if (!vb_has_invalid && !vb_valid_mem[vi]) begin
          vb_has_invalid = 1'b1;
          vb_insert_idx = vi[VB_IDX_W-1:0];
        end
      end
`ifdef KCMU_CVR_LATTICE_REPL_ACTIVE
      // v293: if CVR is full, choose a low-protection slot rather than the
      // raw round-robin slot.  This is a low-bit FPGA placement lattice over
      // existing metadata: avoid evicting sem-hot, H2O-protected, recent, or
      // repeatedly touched clean victims.  Invalid-first behavior is unchanged.
      if (VB_CLEAN_ACTIVE && !vb_has_invalid) begin
        for (vi = 0; vi < VB_LINES; vi = vi + 1) begin
          vb_lattice_scan_idx = vb_rr_ptr + vi[VB_IDX_W-1:0];
          if (!vb_lattice_pick_found &&
              vb_valid_mem[vb_lattice_scan_idx] &&
`ifdef KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_CVR_CLASS_LATTICE_V295
              // v295 relaxes v294's strict "unprotected only" rule: CVR can
              // evict a lower H2O-class / low-frequency entry even when most
              // entries are tagged as recent by the baseline oracle.
              !vb_sem_hot_mem[vb_lattice_scan_idx] &&
              (vb_h2o_class_mem[vb_lattice_scan_idx] <= KCMU_H2O_RECENT_ONLY) &&
              (vb_freq_mem[vb_lattice_scan_idx] <= 4'd2)
`elsif KCMU_KILOSCORE_CVR_META_ACTIVE
              kiloscore_path_enable &&
              !vb_sem_hot_mem[vb_lattice_scan_idx] &&
              (vb_h2o_class_mem[vb_lattice_scan_idx] <= KCMU_H2O_RECENT_ONLY) &&
              (vb_freq_mem[vb_lattice_scan_idx] <=
                ((group_feedback_credit >= 3'd3) ? 4'd2 : 4'd1))
`elsif KCMU_CFG_FPGA_KILOSCORE_NATIVE_STANDALONE
              !vb_sem_hot_mem[vb_lattice_scan_idx] &&
              !vb_hh_protect_mem[vb_lattice_scan_idx] &&
              (((vb_h2o_class_mem[vb_lattice_scan_idx] <= KCMU_H2O_RECENT_ONLY) &&
                (vb_freq_mem[vb_lattice_scan_idx] <= 4'd2)) ||
               ((vb_utility_score_mem[vb_lattice_scan_idx] < SCORE_W'(8'h60)) &&
                (vb_freq_mem[vb_lattice_scan_idx] <= 4'd1)))
`else
              !vb_sem_hot_mem[vb_lattice_scan_idx] &&
              !vb_hh_protect_mem[vb_lattice_scan_idx] &&
              !vb_recent_keep_mem[vb_lattice_scan_idx] &&
              (vb_h2o_class_mem[vb_lattice_scan_idx] == KCMU_H2O_NEITHER) &&
              (vb_freq_mem[vb_lattice_scan_idx] <= 4'd1)
`endif
             ) begin
            vb_lattice_pick_found = 1'b1;
            vb_insert_idx = vb_lattice_scan_idx;
          end
        end
      end
`endif
    end
  end

  always @(*) begin
    vb_walloc_idx = vb_insert_idx;
    if (vb_write_hit) begin
      vb_walloc_idx = vb_write_idx;
    end
  end

  always @(*) begin
    // In write-back mode, only non-allocating misses without VB residency
    // are forced to write-through for correctness.
    direct_wt_we = req_we &&
                   (WRITE_THROUGH_EN ||
                    (!write_hit && !write_alloc_enable && !(VB_ENABLE && vb_write_hit)));
    wbq_empty = (wbq_count == (WBQ_IDX_W+1)'(0));
    wbq_full = (wbq_count == (WBQ_IDX_W+1)'(WBQ_DEPTH));
    wbq_head_addr = wbq_addr_mem[wbq_head_ptr];
    wbq_head_data = wbq_data_mem[wbq_head_ptr];
    wbq_head_is_writeback = wbq_is_writeback_mem[wbq_head_ptr];
`ifdef KCMU_KILOSCORE_CVR_GF_V384_ACTIVE
    group_issue_idle_th_eff =
      kiloscore_path_enable ?
        (group_fast_issue_allowed ? 2'd1 :
          (group_slow_issue_allowed ? 2'd3 : GROUP_FETCH_IDLE_TH)) :
        GROUP_FETCH_IDLE_TH;
`elsif KCMU_CFG_FPGA_KILOSCORE_GF_NSA_SLOW_PACE_V734
    group_issue_idle_th_eff = group_slow_issue_allowed ? 2'd3 : GROUP_FETCH_IDLE_TH;
`elsif KCMU_CFG_FPGA_KILOSCORE_TINY_SLIDE_GF_RESCUE_V723
    group_issue_idle_th_eff = group_fast_issue_allowed ? 2'd1 : GROUP_FETCH_IDLE_TH;
`elsif KCMU_CFG_FPGA_KILOSCORE_CMDQ_LOOKAHEAD_GF_V409
    group_issue_idle_th_eff = group_fast_issue_allowed ? 2'd1 : GROUP_FETCH_IDLE_TH;
`elsif KCMU_CFG_FPGA_KILOSCORE_SLIDING_GF_V408
    group_issue_idle_th_eff = group_fast_issue_allowed ? 2'd1 : GROUP_FETCH_IDLE_TH;
`elsif KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_MIXED_FAST_ISSUE_V315
    // v315: use the fast issue slot only for groups captured in a descriptor
    // class-switch region.  This preserves v309's mixed-NSA latency benefit
    // while avoiding always-fast issue on multimodal prefix streams.
    group_issue_idle_th_eff = group_fast_issue_allowed ? 2'd1 : GROUP_FETCH_IDLE_TH;
`elsif KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_READDENSE_FAST_ISSUE_V316
    // v316: use the fast issue slot only in read-dense phases, so write-heavy
    // multimodal/prefix phases keep v251's safer two-idle-cycle spacing.
    group_issue_idle_th_eff = group_fast_issue_allowed ? 2'd1 : GROUP_FETCH_IDLE_TH;
`elsif KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_STRICT_READDENSE_FAST_ISSUE_V317
    group_issue_idle_th_eff = group_fast_issue_allowed ? 2'd1 : GROUP_FETCH_IDLE_TH;
`elsif KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_SLIDING_FAST_ISSUE_V318
    group_issue_idle_th_eff = group_fast_issue_allowed ? 2'd1 : GROUP_FETCH_IDLE_TH;
`elsif KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_SLIDING_READDENSE_FAST_ISSUE_V319
    group_issue_idle_th_eff = group_fast_issue_allowed ? 2'd1 : GROUP_FETCH_IDLE_TH;
`elsif KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_PREFIX_SLOW_ISSUE_V320
    group_issue_idle_th_eff = group_slow_issue_allowed ? 2'd3 : GROUP_FETCH_IDLE_TH;
`elsif KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_SLIDE_FAST_PREFIX_SLOW_V321
    group_issue_idle_th_eff = group_fast_issue_allowed ? 2'd1 :
                              (group_slow_issue_allowed ? 2'd3 : GROUP_FETCH_IDLE_TH);
`elsif KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_CLEAN_GB_SLIDE_FAST_V322
    group_issue_idle_th_eff = group_fast_issue_allowed ? 2'd1 : GROUP_FETCH_IDLE_TH;
`elsif KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_CLEAN_GB_SLIDE_FAST_PREFIX_SLOW_V323
    group_issue_idle_th_eff = group_fast_issue_allowed ? 2'd1 :
                              (group_slow_issue_allowed ? 2'd3 : GROUP_FETCH_IDLE_TH);
`elsif KCMU_CFG_FPGA_KILOSCORE_NATIVE_STANDALONE
    group_issue_idle_th_eff = group_fast_issue_allowed ? 2'd1 :
                              (group_slow_issue_allowed ? 2'd3 : GROUP_FETCH_IDLE_TH);
`else
    group_issue_idle_th_eff = GROUP_FETCH_IDLE_TH;
`endif
    group_read_req_pending = GROUP_FETCH_TO_CVR_EN &&
                             VB_CLEAN_ACTIVE &&
                             read_bus_idle &&
                             group_pending &&
                             !group_issued &&
                             !miss_pending &&
                             !rd_req_re &&
                             !req_we &&
                             wbq_empty &&
                             (group_idle_ctr >= group_issue_idle_th_eff);
    read_req_pending = read_bus_idle &&
                       ((miss_pending && !miss_issued) ||
                        (!group_issued && !miss_pending && rd_req_re && !read_hit &&
                         !gb_read_hit_eff &&
                         !(VB_ENABLE && vb_read_hit)) ||
                        group_read_req_pending);
    read_req_addr = group_read_req_pending ? group_addr :
                    (miss_pending ? miss_addr : rd_req_raddr);
    read_req_is_prefetch = group_read_req_pending ? 1'b0 :
                           (miss_pending ? miss_is_prefetch : rd_req_is_prefetch);
    read_req_service_issue_boost = group_read_req_pending ? 1'b0 :
                                   (miss_pending ? miss_service_issue_boost : rd_req_service_issue_boost);
    service_issue_defer_dirty_flush = SERVICE_ISSUE_DEFER_DIRTY_FLUSH_EN &&
                                      read_req_pending &&
                                      !read_req_is_prefetch &&
                                      read_req_service_issue_boost;
    read_issue_fire = read_req_pending && mem_re_ready;
    wbq_issue_we = (!wbq_empty) && !read_issue_fire;
    wbq_pop_fire = wbq_issue_we && mem_we_ready;

    mem_re    = 1'b0;
    mem_raddr = {ADDR_W{1'b0}};
    mem_req_is_prefetch = 1'b0;
    mem_req_is_group = 1'b0;
    mem_req_service_issue_boost = 1'b0;
    mem_we    = 1'b0;
    mem_waddr = {ADDR_W{1'b0}};
    mem_wdata = {DATA_W{1'b0}};
    mem_req_is_writeback = 1'b0;

    if (read_req_pending) begin
      mem_raddr = read_req_addr;
      mem_req_is_prefetch = read_req_is_prefetch;
      mem_req_is_group = group_read_req_pending;
      mem_req_service_issue_boost = !read_req_is_prefetch && read_req_service_issue_boost;
    end

    if (read_issue_fire) begin
      mem_re    = 1'b1;
    end

    if (!mem_re && wbq_issue_we) begin
      mem_we    = 1'b1;
      mem_waddr = wbq_head_addr;
      mem_wdata = wbq_head_data;
      mem_req_is_writeback = wbq_head_is_writeback;
    end
  end

  assign mem_req_accepted = read_issue_fire && !group_read_req_pending;

  always @(posedge clk) begin
    if (!rst_n) begin
      valid_mem <= {L2_LINES{1'b0}};
      lossy_mem <= {L2_LINES{1'b0}};
      dirty_mem <= {L2_LINES{1'b0}};
      vb_valid_mem <= {VB_LINES{1'b0}};
      vb_lossy_mem <= {VB_LINES{1'b0}};
      vb_dirty_mem <= {VB_LINES{1'b0}};
      gb_valid_mem <= {GROUP_BUF_LINES{1'b0}};
      gb_used_mem <= {GROUP_BUF_LINES{1'b0}};
      gb_target_origin_mem <= {GROUP_BUF_LINES{1'b0}};
      group_recent_wr_valid <= {GROUP_RECENT_WR_LINES{1'b0}};
      vb_sem_hot_mem <= {VB_LINES{1'b0}};
      vb_hh_protect_mem <= {VB_LINES{1'b0}};
      vb_recent_keep_mem <= {VB_LINES{1'b0}};
      vb_marginal_keep_mem <= {VB_LINES{1'b0}};
      vb_pollution_risk_mem <= {VB_LINES{1'b0}};
      vb_rr_ptr <= {VB_IDX_W{1'b0}};
      gb_rr_ptr <= {GROUP_BUF_IDX_W{1'b0}};
      vb_bg_ptr <= {VB_IDX_W{1'b0}};
      l2_bg_ptr <= {L2_IDX_W{1'b0}};
`ifdef KCMU_CFG_FPGA_KILOSCORE_L2VICTIM_RRIP_BUDGET8_V897
      l2victim_rrip_budget <= 6'd8;
`elsif KCMU_CFG_FPGA_KILOSCORE_L2VICTIM_RRIP_BUDGET16_V898
      l2victim_rrip_budget <= 6'd16;
`elsif KCMU_CFG_FPGA_KILOSCORE_L2VICTIM_RRIP_BUDGET24_V899
      l2victim_rrip_budget <= 6'd24;
`else
      l2victim_rrip_budget <= 6'd0;
`endif
      wbq_head_ptr <= {WBQ_IDX_W{1'b0}};
      wbq_tail_ptr <= {WBQ_IDX_W{1'b0}};
      wbq_count <= {(WBQ_IDX_W+1){1'b0}};
      read_owner <= READ_NONE;
      miss_pending <= 1'b0;
      miss_issued <= 1'b0;
      miss_addr <= {ADDR_W{1'b0}};
      miss_is_prefetch <= 1'b0;
      miss_qos <= 3'd0;
      miss_sem_hot <= 1'b0;
      miss_fill_allow <= 1'b0;
      miss_victim_protect <= 1'b0;
      miss_compress_allow <= 1'b0;
      miss_hh_protect <= 1'b0;
      miss_recent_keep <= 1'b0;
      miss_h2o_class <= KCMU_H2O_NEITHER;
      miss_utility_score <= {SCORE_W{1'b0}};
      miss_query_relevance <= {SCORE_W{1'b0}};
      miss_head_budget_class <= {kcmu_pkg::KCMU_HEAD_BUDGET_W{1'b0}};
      miss_temporal_persist_class <= {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}};
      miss_reuse_distance_class <= {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}};
      miss_query_structure_class <= {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}};
      miss_marginal_active <= 1'b0;
      miss_service_issue_boost <= 1'b0;
      miss_sched_query_take <= 1'b0;
      miss_sched_temporal_take <= 1'b0;
      miss_sched_query_bias_take <= 1'b0;
      miss_group_boundary <= 1'b1;
      miss_group_target_valid <= 1'b0;
      miss_group_target_addr <= {ADDR_W{1'b0}};
      miss_group_v251gf_force <= 1'b0;
      miss_kiloscore_extra_cvr_hint <= 1'b0;
      miss_kiloscore_qsig_bucket <= 3'd0;
      miss_backend_write_pressure <= 1'b0;
      group_pending <= 1'b0;
      group_issued <= 1'b0;
      group_cancel <= 1'b0;
      group_extra_cvr_pending <= 1'b0;
      group_native_eqcap_q1_cvr_pending <= 1'b0;
      group_used_first_risk <= 1'b0;
      group_prefix_seen_ttl <= 6'd0;
      group_prefix_density_credit <= 4'd0;
      group_fast_issue_allowed <= 1'b0;
      group_slow_issue_allowed <= 1'b0;
      group_addr <= {ADDR_W{1'b0}};
      group_idle_ctr <= 2'd0;
      group_pending_age <= 4'd0;
      deferred_req_valid <= 1'b0;
      deferred_req_raddr <= {ADDR_W{1'b0}};
      deferred_req_is_prefetch <= 1'b0;
      deferred_req_qos <= 3'd0;
      deferred_req_sem_hot <= 1'b0;
      deferred_req_fill_allow <= 1'b0;
      deferred_req_victim_protect <= 1'b0;
      deferred_req_compress_allow <= 1'b0;
      deferred_req_hh_protect <= 1'b0;
      deferred_req_recent_keep <= 1'b0;
      deferred_req_h2o_class <= KCMU_H2O_NEITHER;
      deferred_req_utility_score <= {SCORE_W{1'b0}};
      deferred_req_query_relevance <= {SCORE_W{1'b0}};
      deferred_req_head_budget_class <= {kcmu_pkg::KCMU_HEAD_BUDGET_W{1'b0}};
      deferred_req_temporal_persist_class <= {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}};
      deferred_req_reuse_distance_class <= {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}};
      deferred_req_query_structure_class <= {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}};
      deferred_req_marginal_active <= 1'b0;
      deferred_req_service_issue_boost <= 1'b0;
      deferred_req_sched_query_take <= 1'b0;
      deferred_req_sched_temporal_take <= 1'b0;
      deferred_req_sched_query_bias_take <= 1'b0;
      deferred_req_group_boundary <= 1'b1;
      deferred_req_group_target_valid <= 1'b0;
      deferred_req_group_target_addr <= {ADDR_W{1'b0}};
      deferred_req_group_v251gf_force <= 1'b0;
      deferred_req_kiloscore_extra_cvr_hint <= 1'b0;
      deferred_req_kiloscore_qsig_bucket <= 3'd0;
      group_last_miss_valid <= 1'b0;
      group_last_miss_addr <= {ADDR_W{1'b0}};
      group_last_delta_sel <= 2'd0;
      group_stream_conf <= 3'd0;
      group_write_quiet_cnt <= 3'd0;
      rw_density_credit <= 4'd0;
      group_class_seen <= 1'b0;
      group_qstruct_high_seen <= 1'b0;
      group_prefix_anchor_run_cnt <= 5'd0;
      group_prefix_anchor_hold_cnt <= 8'd0;
      group_last_query_structure_class <= {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}};
      group_class_switch_credit <= 3'd0;
      group_activity_credit <= 3'd0;
      group_throttle_credit <= 3'd0;
      group_throttle_seen <= 1'b0;
      group_target_pollution_debt <= 4'd0;
      group_target_backend_debt <= 4'd0;
      group_target_read_bypass_debt <= 4'd0;
      group_target_use_credit <= 3'd4;
      group_target_recent_ttl <= 4'd0;
      group_target_origin_pending <= 1'b0;
      clean_side_resp_valid <= 1'b0;
      clean_side_resp_data <= {DATA_W{1'b0}};
      clean_vb_consume_pending <= 1'b0;
      clean_vb_consume_idx <= {VB_IDX_W{1'b0}};
`ifdef KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_FAST_BACKOFF_V292
      group_feedback_credit <= 3'd4;
`else
      group_feedback_credit <= 3'd3;
`endif
      group_lane_valid <= {GROUP_FETCH_LANES{1'b0}};
      for (gi = 0; gi < GROUP_FETCH_LANES; gi = gi + 1) begin
        group_lane_last_addr[gi] <= {ADDR_W{1'b0}};
        group_lane_conf[gi] <= 3'd0;
      end
      for (li = 0; li < L2_LINES; li = li + 1) begin
        tag_mem[li]  <= {L2_TAG_W{1'b0}};
        data_mem[li] <= {DATA_W{1'b0}};
        comp_mem[li] <= {COMP_W{1'b0}};
        comp_bits_mem[li] <= 3'd4;
        line_sem_hot[li] <= 1'b0;
        line_hh_protect_mem[li] <= 1'b0;
        line_recent_keep_mem[li] <= 1'b0;
        line_h2o_class_mem[li] <= KCMU_H2O_NEITHER;
        line_utility_score_mem[li] <= {SCORE_W{1'b0}};
        line_marginal_keep_mem[li] <= 1'b0;
        line_pollution_risk_mem[li] <= 1'b0;
        line_pressure_bonus_mem[li] <= 3'd0;
        line_freq[li] <= 4'd0;
        line_touch_epoch[li] <= 8'd0;
        if (li < L2_SETS) begin
          set_rr_way[li] <= 1'b0;
        end
`ifndef SYNTHESIS
        line_fill_cycle[li] <= 32'd0;
`endif
      end
      for (li = 0; li < VB_LINES; li = li + 1) begin
        vb_tag_mem[li]  <= {ADDR_W{1'b0}};
        vb_data_mem[li] <= {DATA_W{1'b0}};
        vb_comp_mem[li] <= {COMP_W{1'b0}};
        vb_comp_bits_mem[li] <= 3'd4;
        vb_h2o_class_mem[li] <= KCMU_H2O_NEITHER;
        vb_utility_score_mem[li] <= {SCORE_W{1'b0}};
        vb_marginal_keep_mem[li] <= 1'b0;
        vb_pollution_risk_mem[li] <= 1'b0;
        vb_pressure_bonus_mem[li] <= 3'd0;
        vb_freq_mem[li] <= 4'd0;
        vb_touch_epoch_mem[li] <= 8'd0;
      end
      for (li = 0; li < WBQ_DEPTH; li = li + 1) begin
        wbq_addr_mem[li] <= {ADDR_W{1'b0}};
        wbq_data_mem[li] <= {DATA_W{1'b0}};
        wbq_is_writeback_mem[li] <= 1'b0;
      end
      for (li = 0; li < GROUP_BUF_LINES; li = li + 1) begin
        gb_tag_mem[li] <= {ADDR_W{1'b0}};
        gb_data_mem[li] <= {DATA_W{1'b0}};
      end
      for (li = 0; li < GROUP_RECENT_WR_LINES; li = li + 1) begin
        group_recent_wr_addr[li] <= {ADDR_W{1'b0}};
      end
`ifndef SYNTHESIS
      stat_l2_read_hit_cnt   <= 32'd0;
      stat_l2_read_miss_cnt  <= 32'd0;
      stat_l2_write_hit_cnt  <= 32'd0;
      stat_l2_write_alloc_cnt<= 32'd0;
      stat_l2_write_noalloc_cnt <= 32'd0;
      stat_l2_fill_cnt       <= 32'd0;
      stat_l2_evict_cnt      <= 32'd0;
      stat_hbm_read_req_cnt  <= 32'd0;
      stat_hbm_write_req_cnt <= 32'd0;
      stat_l2_comp_fill_cnt  <= 32'd0;
      stat_l2_comp_hit_cnt   <= 32'd0;
      stat_l2_comp_promote_cnt <= 32'd0;
      stat_l2_comp_readback_cnt <= 32'd0;
      stat_l2_comp_spill_cnt <= 32'd0;
      stat_l2_comp_saved_beats <= 32'd0;
      stat_l2_comp_blocked_hot_cnt <= 32'd0;
      stat_l2_comp_error_accum <= 32'd0;
      stat_l2_write_qos_bypass_cnt <= 32'd0;
      stat_l2_vb_read_hit_cnt <= 32'd0;
      stat_l2_vb_write_hit_cnt <= 32'd0;
      stat_l2_vb_insert_cnt <= 32'd0;
      stat_l2_vb_evict_cnt <= 32'd0;
      stat_l2_vb_swap_cnt <= 32'd0;
      stat_l2_fill_invalid_cnt <= 32'd0;
      stat_l2_fill_replace_cnt <= 32'd0;
      stat_l2_fill_pick_way1_base_cnt <= 32'd0;
      stat_l2_fill_pick_way1_taken_cnt <= 32'd0;
      stat_l2_fill_pick_flip_cnt <= 32'd0;
      stat_l2_fill_query_bias_eval_cnt <= 32'd0;
      stat_l2_fill_query_pick_flip_cnt <= 32'd0;
      stat_l2_fill_sched_query_seen_cnt <= 32'd0;
      stat_l2_fill_sched_query_dual_valid_cnt <= 32'd0;
      stat_l2_fill_sched_query_query_hot_cnt <= 32'd0;
      stat_l2_fill_sched_query_high_util_cnt <= 32'd0;
      stat_l2_fill_sched_query_unprotected_cnt <= 32'd0;
      stat_l2_fill_sched_query_pair_ready_cnt <= 32'd0;
      stat_l2_fill_sched_query_bias_eval_cnt <= 32'd0;
      stat_l2_fill_sched_query_pick_flip_cnt <= 32'd0;
      stat_l2_fill_req_query_hot_cnt <= 32'd0;
      stat_l2_fill_req_high_util_cnt <= 32'd0;
      stat_l2_fill_req_dual_valid_cnt <= 32'd0;
      stat_l2_fill_req_query_ready_cnt <= 32'd0;
