            if ((req_h2o_class >= KCMU_H2O_HEAVY_ONLY) && (group_feedback_credit != 3'd7)) begin
              group_feedback_credit <= group_feedback_credit + 3'd1;
            end
`endif
            if (clean_vb_promote_enable) begin
              valid_mem[r_idx] <= 1'b1;
              tag_mem[r_idx]   <= r_tag;
              dirty_mem[r_idx] <= 1'b0;
              data_mem[r_idx]  <= vb_data_mem[vb_read_idx];
              comp_bits_mem[r_idx] <= 3'd4;
              lossy_mem[r_idx] <= 1'b0;
              vb_valid_mem[vb_read_idx] <= 1'b0;
              if (L2_WAYS > 1 && valid_mem[r_idx]) begin
                set_rr_way[r_set_idx] <= ~set_rr_way[r_set_idx];
              end
`ifndef SYNTHESIS
`ifdef KCMU_KILOSCORE_CVR_FREQ_PROMOTE_ACTIVE
              if (kiloscore_path_enable) begin
                $display("KS_CVR_ACTIVE: req_qstruct=%0d miss_qstruct=%0d gf=%0d ga=%0d rw=%0d req_h2o=%0d qos=%0d util=0x%02h qrel=0x%02h hh=%0d recent=%0d sem=%0d group_boundary=%0d group_target=%0d gb_unused=%0d vb_freq=%0d new_freq=%0d addr=%0d",
                         req_query_structure_class,
                         miss_query_structure_class,
                         group_feedback_credit,
                         group_activity_credit,
                         rw_density_credit,
                         req_h2o_class,
                         req_qos,
