                         |(gb_valid_mem & ~gb_used_mem),
                         vb_freq_mem[vb_read_idx],
                         clean_vb_promote_freq_seed,
                         r_tag);
              end
`endif
              if (valid_mem[r_idx]) begin
                stat_l2_fill_replace_cnt <= stat_l2_fill_replace_cnt + 32'd1;
                stat_l2_lifetime_cycle_sum <= stat_l2_lifetime_cycle_sum + {32'd0, (sim_cycle - line_fill_cycle[r_idx])};
                stat_l2_lifetime_sample_cnt <= stat_l2_lifetime_sample_cnt + 32'd1;
                if ((sim_cycle - line_fill_cycle[r_idx]) < 32'd32) begin
                  stat_l2_lifetime_bin_lt32_cnt <= stat_l2_lifetime_bin_lt32_cnt + 32'd1;
                end else if ((sim_cycle - line_fill_cycle[r_idx]) < 32'd128) begin
