              line_sem_hot[r_idx] <= req_sem_hot;
              line_hh_protect_mem[r_idx] <= req_hh_protect;
              line_recent_keep_mem[r_idx] <= req_recent_keep;
              line_h2o_class_mem[r_idx] <= clean_vb_promote_h2o_class_seed;
              line_utility_score_mem[r_idx] <= req_utility_score;
