              vb_pressure_bonus_mem[vb_read_idx] <= 3'd0;
              vb_freq_mem[vb_read_idx] <= 4'd0;
              vb_touch_epoch_mem[vb_read_idx] <= 8'd0;
              vb_comp_bits_mem[vb_read_idx] <= 3'd4;
              vb_lossy_mem[vb_read_idx] <= 1'b0;
            end
`ifndef SYNTHESIS
            if (valid_mem[r_idx]) begin
