            line_sem_hot[r_idx] <= vb_sem_hot_mem[vb_read_idx] | req_sem_hot;
            line_hh_protect_mem[r_idx] <= vb_hh_protect_mem[vb_read_idx] | req_hh_protect;
            line_recent_keep_mem[r_idx] <= vb_recent_keep_mem[vb_read_idx] | req_recent_keep;
            line_h2o_class_mem[r_idx] <= (vb_h2o_class_mem[vb_read_idx] > req_h2o_class) ? vb_h2o_class_mem[vb_read_idx] : req_h2o_class;
            line_utility_score_mem[r_idx] <= merge_utility_score(vb_utility_score_mem[vb_read_idx], req_utility_score);
            line_marginal_keep_mem[r_idx] <= vb_marginal_keep_mem[vb_read_idx] |
