            vb_hh_protect_mem[vb_read_idx] <= vb_hh_protect_mem[vb_read_idx] | req_hh_protect;
            vb_recent_keep_mem[vb_read_idx] <= vb_recent_keep_mem[vb_read_idx] | req_recent_keep;
            vb_utility_score_mem[vb_read_idx] <= merge_utility_score(vb_utility_score_mem[vb_read_idx], req_utility_score);
            vb_marginal_keep_mem[vb_read_idx] <= vb_marginal_keep_mem[vb_read_idx] |
