                req_hh_protect || (req_h2o_class == KCMU_H2O_BOTH) || (req_h2o_class == KCMU_H2O_HEAVY_ONLY),
                req_service_issue_boost && !req_is_prefetch,
                vb_freq_mem[vb_read_idx],
                epoch_ctr - vb_touch_epoch_mem[vb_read_idx]);
            vb_pollution_risk_mem[vb_read_idx] <= vb_pollution_risk_mem[vb_read_idx] |
              make_pollution_risk(req_utility_score,
                req_marginal_active,
