                vb_freq_mem[vb_read_idx],
                epoch_ctr - vb_touch_epoch_mem[vb_read_idx]);
            vb_pressure_bonus_mem[vb_read_idx] <= make_pressure_bonus(req_utility_score, req_marginal_active, req_service_issue_boost && !req_is_prefetch);
