                if (fill_req_lossy_fill) begin
                  stat_l2_fill_req_query_lossy_taken_cnt <= stat_l2_fill_req_query_lossy_taken_cnt + 32'd1;
                end else if (miss_compress_allow && LOSSY_COMPRESS_EN) begin
                  stat_l2_fill_req_query_lossy_block_cnt <= stat_l2_fill_req_query_lossy_block_cnt + 32'd1;
                end
              end else begin
                stat_l2_fill_req_query_bypass_cnt <= stat_l2_fill_req_query_bypass_cnt + 32'd1;
              end
            end
`endif
            if (fill_read_fill_enable) begin
              if (valid_mem[fill_idx]) begin
`ifndef SYNTHESIS
              if (miss_query_relevance >= SCORE_W'(8'hA8)) begin
                stat_l2_fill_req_query_hot_cnt <= stat_l2_fill_req_query_hot_cnt + 32'd1;
              end
              if (miss_utility_score >= SCORE_W'(8'h80)) begin
                stat_l2_fill_req_high_util_cnt <= stat_l2_fill_req_high_util_cnt + 32'd1;
              end
              if (L2_WAYS > 1 && valid_mem[fill_way0_idx] && valid_mem[fill_way1_idx]) begin
                stat_l2_fill_req_dual_valid_cnt <= stat_l2_fill_req_dual_valid_cnt + 32'd1;
                if ((miss_query_relevance >= SCORE_W'(8'hA8)) &&
