                    vb_utility_score_mem[vb_insert_idx] <= line_utility_score_mem[fill_idx];
                    vb_marginal_keep_mem[vb_insert_idx] <= line_marginal_keep_mem[fill_idx];
                    vb_pollution_risk_mem[vb_insert_idx] <= line_pollution_risk_mem[fill_idx];
                    vb_pressure_bonus_mem[vb_insert_idx] <= line_pressure_bonus_mem[fill_idx];
                    vb_freq_mem[vb_insert_idx] <= line_freq[fill_idx];
                    vb_touch_epoch_mem[vb_insert_idx] <= line_touch_epoch[fill_idx];
                    vb_comp_bits_mem[vb_insert_idx] <= 3'd4;
