                           vb_recent_keep_mem[vb_insert_idx],
                           vb_h2o_class_mem[vb_insert_idx],
                           vb_lossy_mem[vb_insert_idx],
                           (miss_sem_hot || miss_victim_protect || miss_hh_protect || miss_recent_keep),
                           miss_qos,
                           miss_is_prefetch
                         )) && !wb_push_req) begin
                      wb_push_req = 1'b1;
                      wb_push_addr = vb_tag_mem[vb_insert_idx];
                      wb_push_data = line_export_data(
                        vb_data_mem[vb_insert_idx],
                        vb_comp_mem[vb_insert_idx],
                        vb_comp_bits_mem[vb_insert_idx],
                        vb_lossy_mem[vb_insert_idx]
                      );
                      wb_push_is_comp = should_spill_compress(
                        vb_dirty_mem[vb_insert_idx],
                        vb_sem_hot_mem[vb_insert_idx],
                        vb_hh_protect_mem[vb_insert_idx],
                        vb_recent_keep_mem[vb_insert_idx],
                        vb_h2o_class_mem[vb_insert_idx],
                        vb_lossy_mem[vb_insert_idx],
                        (miss_sem_hot || miss_victim_protect || miss_hh_protect || miss_recent_keep),
                        miss_qos,
                        miss_is_prefetch
                      );
                      wb_push_comp_bits = vb_lossy_mem[vb_insert_idx] ? vb_comp_bits_mem[vb_insert_idx] :
                                          choose_comp_bits(miss_qos, miss_is_prefetch);
                      wb_push_src_fill_vb_evict = 1'b1;
                    end
`ifndef SYNTHESIS
                    stat_l2_vb_evict_cnt <= stat_l2_vb_evict_cnt + 32'd1;
`endif
                  end
                  vb_valid_mem[vb_insert_idx] <= 1'b1;
                  vb_tag_mem[vb_insert_idx] <= compose_addr_from_line(tag_mem[fill_idx], fill_idx);
                  vb_dirty_mem[vb_insert_idx] <= dirty_mem[fill_idx];
                  vb_sem_hot_mem[vb_insert_idx] <= line_sem_hot[fill_idx];
                  vb_hh_protect_mem[vb_insert_idx] <= line_hh_protect_mem[fill_idx];
                  vb_recent_keep_mem[vb_insert_idx] <= line_recent_keep_mem[fill_idx];
                  vb_h2o_class_mem[vb_insert_idx] <= line_h2o_class_mem[fill_idx];
                  vb_utility_score_mem[vb_insert_idx] <= line_utility_score_mem[fill_idx];
                  vb_marginal_keep_mem[vb_insert_idx] <= line_marginal_keep_mem[fill_idx];
                  vb_pollution_risk_mem[vb_insert_idx] <= line_pollution_risk_mem[fill_idx];
                  vb_pressure_bonus_mem[vb_insert_idx] <= line_pressure_bonus_mem[fill_idx];
                  vb_freq_mem[vb_insert_idx] <= line_freq[fill_idx];
                  vb_touch_epoch_mem[vb_insert_idx] <= line_touch_epoch[fill_idx];
                  if (lossy_mem[fill_idx]) begin
                    vb_comp_mem[vb_insert_idx] <= comp_mem[fill_idx];
                    vb_comp_bits_mem[vb_insert_idx] <= comp_bits_mem[fill_idx];
                    vb_lossy_mem[vb_insert_idx] <= 1'b1;
                  end else begin
                    vb_data_mem[vb_insert_idx] <= data_mem[fill_idx];
                    vb_comp_bits_mem[vb_insert_idx] <= 3'd4;
                    vb_lossy_mem[vb_insert_idx] <= 1'b0;
                  end
                  vb_rr_ptr <= vb_insert_idx + VB_IDX_W'(1);
`ifndef SYNTHESIS
                  stat_l2_vb_insert_cnt <= stat_l2_vb_insert_cnt + 32'd1;
`endif
                end else if ((fill_victim_dirty ||
                              should_spill_compress(
                                fill_victim_dirty,
                                line_sem_hot[fill_idx],
                                line_hh_protect_mem[fill_idx],
                                line_recent_keep_mem[fill_idx],
                                line_h2o_class_mem[fill_idx],
                                lossy_mem[fill_idx],
                                (miss_sem_hot || miss_victim_protect || miss_hh_protect || miss_recent_keep),
                                miss_qos,
                                miss_is_prefetch
                              )) && !wb_push_req) begin
                  wb_push_req = 1'b1;
                  wb_push_addr = compose_addr_from_line(tag_mem[fill_idx], fill_idx);
                  wb_push_data = line_export_data(
                    data_mem[fill_idx],
                    comp_mem[fill_idx],
                    comp_bits_mem[fill_idx],
                    lossy_mem[fill_idx]
                  );
                  wb_push_is_comp = should_spill_compress(
                    fill_victim_dirty,
                    line_sem_hot[fill_idx],
                    line_hh_protect_mem[fill_idx],
                    line_recent_keep_mem[fill_idx],
                    line_h2o_class_mem[fill_idx],
                    lossy_mem[fill_idx],
                    (miss_sem_hot || miss_victim_protect || miss_hh_protect || miss_recent_keep),
                    miss_qos,
                    miss_is_prefetch
                  );
                  wb_push_comp_bits = lossy_mem[fill_idx] ? comp_bits_mem[fill_idx] :
                                      choose_comp_bits(miss_qos, miss_is_prefetch);
                  wb_push_src_fill_direct = 1'b1;
                end
                if (L2_WAYS > 1) begin
                  set_rr_way[fill_set_idx] <= ~set_rr_way[fill_set_idx];
                end
`ifndef SYNTHESIS
                if (fill_clean_victim_candidate) begin
                  stat_l2_service_issue_clean_candidate_cnt <= stat_l2_service_issue_clean_candidate_cnt + 32'd1;
                end
                if (fill_clean_victim_rescue) begin
                  stat_l2_service_issue_clean_pick_cnt <= stat_l2_service_issue_clean_pick_cnt + 32'd1;
                end
                if (fill_sched_query_req_seen) begin
                  stat_l2_fill_sched_query_seen_cnt <= stat_l2_fill_sched_query_seen_cnt + 32'd1;
                end
                if (fill_sched_query_dual_valid) begin
                  stat_l2_fill_sched_query_dual_valid_cnt <= stat_l2_fill_sched_query_dual_valid_cnt + 32'd1;
                end
                if (fill_sched_query_query_hot) begin
                  stat_l2_fill_sched_query_query_hot_cnt <= stat_l2_fill_sched_query_query_hot_cnt + 32'd1;
                end
                if (fill_sched_query_high_util) begin
                  stat_l2_fill_sched_query_high_util_cnt <= stat_l2_fill_sched_query_high_util_cnt + 32'd1;
                end
                if (fill_sched_query_unprotected) begin
                  stat_l2_fill_sched_query_unprotected_cnt <= stat_l2_fill_sched_query_unprotected_cnt + 32'd1;
                end
                if (fill_sched_query_pair_ready) begin
                  stat_l2_fill_sched_query_pair_ready_cnt <= stat_l2_fill_sched_query_pair_ready_cnt + 32'd1;
                end
                if (L2_WAYS > 1 && valid_mem[fill_way0_idx] && valid_mem[fill_way1_idx]) begin
                  if (!H2O_V2_EN &&
                      (L2_LINES <= 16) &&
                      !miss_is_prefetch &&
                      (miss_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) &&
                      (miss_query_relevance >= SCORE_W'(8'hA0)) &&
                      (miss_query_relevance <= SCORE_W'(8'hC8))) begin
                    stat_l2_native_tiny_midprefix_fill_cnt <= stat_l2_native_tiny_midprefix_fill_cnt + 32'd1;
                    if (fill_pick_way1) begin
                      stat_l2_native_tiny_midprefix_way1_cnt <= stat_l2_native_tiny_midprefix_way1_cnt + 32'd1;
                    end
                    if (fill_score0 == fill_score1) begin
                      stat_l2_native_tiny_midprefix_tie_cnt <= stat_l2_native_tiny_midprefix_tie_cnt + 32'd1;
                    end
                    if (fill_score_close_rrip_tie) begin
                      stat_l2_native_tiny_midprefix_close_cnt <= stat_l2_native_tiny_midprefix_close_cnt + 32'd1;
                    end
                    if (line_utility_score_mem[fill_way1_idx] < line_utility_score_mem[fill_way0_idx]) begin
                      stat_l2_native_tiny_midprefix_way1_lower_util_cnt <= stat_l2_native_tiny_midprefix_way1_lower_util_cnt + 32'd1;
                    end
                    if (line_freq[fill_way1_idx] < line_freq[fill_way0_idx]) begin
                      stat_l2_native_tiny_midprefix_way1_lower_freq_cnt <= stat_l2_native_tiny_midprefix_way1_lower_freq_cnt + 32'd1;
                    end
                    if (line_h2o_class_mem[fill_idx] == KCMU_H2O_BOTH) begin
                      stat_l2_native_tiny_midprefix_victim_both_cnt <= stat_l2_native_tiny_midprefix_victim_both_cnt + 32'd1;
                    end
                    if (line_utility_score_mem[fill_idx] >= SCORE_W'(8'h60)) begin
                      stat_l2_native_tiny_midprefix_victim_util_ge60_cnt <= stat_l2_native_tiny_midprefix_victim_util_ge60_cnt + 32'd1;
                    end
                  end
                  if ((miss_query_relevance >= SCORE_W'(8'hA8)) &&
                      (miss_utility_score >= SCORE_W'(8'h80))) begin
                    stat_l2_fill_query_bias_eval_cnt <= stat_l2_fill_query_bias_eval_cnt + 32'd1;
                    if (fill_pick_way1_preclean != fill_pick_way1_base_noquery) begin
                      stat_l2_fill_query_pick_flip_cnt <= stat_l2_fill_query_pick_flip_cnt + 32'd1;
                    end
                  end
                  if (fill_sched_query_bias_en) begin
                    stat_l2_fill_sched_query_bias_eval_cnt <= stat_l2_fill_sched_query_bias_eval_cnt + 32'd1;
                    if (fill_pick_way1_preclean != fill_pick_way1_base) begin
                      stat_l2_fill_sched_query_pick_flip_cnt <= stat_l2_fill_sched_query_pick_flip_cnt + 32'd1;
                    end
                  end
                  if (fill_pick_way1_base) begin
                    stat_l2_fill_pick_way1_base_cnt <= stat_l2_fill_pick_way1_base_cnt + 32'd1;
                  end
                  if (fill_pick_way1) begin
                    stat_l2_fill_pick_way1_taken_cnt <= stat_l2_fill_pick_way1_taken_cnt + 32'd1;
                  end
                  if (fill_pick_way1 != fill_pick_way1_base) begin
                    stat_l2_fill_pick_flip_cnt <= stat_l2_fill_pick_flip_cnt + 32'd1;
                  end
                end
                stat_l2_evict_cnt <= stat_l2_evict_cnt + 32'd1;
                stat_l2_evict_capacity_cnt <= stat_l2_evict_capacity_cnt + 32'd1;
                if (fill_victim_dirty) begin
                  stat_l2_fill_victim_dirty_cnt <= stat_l2_fill_victim_dirty_cnt + 32'd1;
                end else begin
                  stat_l2_fill_victim_clean_cnt <= stat_l2_fill_victim_clean_cnt + 32'd1;
                end
                if (lossy_mem[fill_idx]) begin
                  stat_l2_fill_victim_lossy_cnt <= stat_l2_fill_victim_lossy_cnt + 32'd1;
                end
                if (line_hh_protect_mem[fill_idx] || line_recent_keep_mem[fill_idx] ||
                    (line_h2o_class_mem[fill_idx] != KCMU_H2O_NEITHER)) begin
                  stat_l2_fill_victim_protected_cnt <= stat_l2_fill_victim_protected_cnt + 32'd1;
                end
                if (fill_victim_sem_hot_eff) begin
                  stat_l2_evict_sem_hot_victim_cnt <= stat_l2_evict_sem_hot_victim_cnt + 32'd1;
                end
                if (miss_qos <= 3'd2) begin
                  stat_l2_evict_low_qos_req_cnt <= stat_l2_evict_low_qos_req_cnt + 32'd1;
                end
                if (miss_is_prefetch) begin
                  stat_l2_evict_prefetch_req_cnt <= stat_l2_evict_prefetch_req_cnt + 32'd1;
                end
                if (VB_ENABLE) begin
                  stat_l2_evict_vb_path_cnt <= stat_l2_evict_vb_path_cnt + 32'd1;
                end
                if (line_sem_hot[fill_idx]) begin
                  stat_l2_sem_hot_evict_cnt <= stat_l2_sem_hot_evict_cnt + 32'd1;
                end
                stat_l2_fill_replace_cnt <= stat_l2_fill_replace_cnt + 32'd1;
                stat_l2_lifetime_cycle_sum <= stat_l2_lifetime_cycle_sum + {32'd0, (sim_cycle - line_fill_cycle[fill_idx])};
                stat_l2_lifetime_sample_cnt <= stat_l2_lifetime_sample_cnt + 32'd1;
                if ((sim_cycle - line_fill_cycle[fill_idx]) < 32'd32) begin
                  stat_l2_lifetime_bin_lt32_cnt <= stat_l2_lifetime_bin_lt32_cnt + 32'd1;
                end else if ((sim_cycle - line_fill_cycle[fill_idx]) < 32'd128) begin
                  stat_l2_lifetime_bin_lt128_cnt <= stat_l2_lifetime_bin_lt128_cnt + 32'd1;
                end else if ((sim_cycle - line_fill_cycle[fill_idx]) < 32'd512) begin
                  stat_l2_lifetime_bin_lt512_cnt <= stat_l2_lifetime_bin_lt512_cnt + 32'd1;
                end else begin
                  stat_l2_lifetime_bin_ge512_cnt <= stat_l2_lifetime_bin_ge512_cnt + 32'd1;
                end
`endif
              end else begin
`ifndef SYNTHESIS
                if (miss_service_issue_boost && !miss_is_prefetch) begin
                  stat_l2_service_issue_fill_invalid_cnt <= stat_l2_service_issue_fill_invalid_cnt + 32'd1;
                end
                stat_l2_fill_invalid_cnt <= stat_l2_fill_invalid_cnt + 32'd1;
                stat_l2_valid_cur_cnt <= stat_l2_valid_cur_cnt + 32'd1;
                if ((stat_l2_valid_cur_cnt + 32'd1) > stat_l2_valid_peak_cnt) begin
                  stat_l2_valid_peak_cnt <= stat_l2_valid_cur_cnt + 32'd1;
                end
`endif
              end
              valid_mem[fill_idx] <= 1'b1;
              tag_mem[fill_idx]   <= fill_tag;
              line_touch_epoch[fill_idx] <= epoch_ctr;
              line_freq[fill_idx] <= seed_freq_from_req(miss_qos, miss_sem_hot, miss_is_prefetch);
              line_sem_hot[fill_idx] <= miss_sem_hot;
              line_hh_protect_mem[fill_idx] <= miss_hh_protect_fill_seed;
              line_recent_keep_mem[fill_idx] <= miss_recent_keep;
              line_h2o_class_mem[fill_idx] <= miss_h2o_class_fill_seed;
              line_utility_score_mem[fill_idx] <= miss_utility_score;
              line_marginal_keep_mem[fill_idx] <= make_marginal_keep(
                miss_utility_score,
                miss_marginal_active,
                miss_hh_protect_fill_seed || (miss_h2o_class_fill_seed == KCMU_H2O_BOTH) || (miss_h2o_class_fill_seed == KCMU_H2O_HEAVY_ONLY),
                miss_service_issue_boost,
                seed_freq_from_req(miss_qos, miss_sem_hot, miss_is_prefetch),
                8'd0);
              line_pollution_risk_mem[fill_idx] <= make_pollution_risk(
                miss_utility_score,
                miss_marginal_active,
                miss_hh_protect_fill_seed || miss_recent_keep || (miss_h2o_class_fill_seed != KCMU_H2O_NEITHER),
                seed_freq_from_req(miss_qos, miss_sem_hot, miss_is_prefetch),
                8'd0);
              line_pressure_bonus_mem[fill_idx] <= make_pressure_bonus(miss_utility_score, miss_marginal_active, miss_service_issue_boost);
              dirty_mem[fill_idx] <= 1'b0;
`ifndef SYNTHESIS
              line_fill_cycle[fill_idx] <= sim_cycle;
              if (make_marginal_keep(
                    miss_utility_score,
                    miss_marginal_active,
                    miss_hh_protect_fill_seed || (miss_h2o_class_fill_seed == KCMU_H2O_BOTH) || (miss_h2o_class_fill_seed == KCMU_H2O_HEAVY_ONLY),
                    miss_service_issue_boost,
                    seed_freq_from_req(miss_qos, miss_sem_hot, miss_is_prefetch),
                    8'd0)) begin
                stat_l2_casu_marginal_keep_cnt <= stat_l2_casu_marginal_keep_cnt + 32'd1;
              end
              if (make_pollution_risk(
                    miss_utility_score,
                    miss_marginal_active,
                    miss_hh_protect_fill_seed || miss_recent_keep || (miss_h2o_class_fill_seed != KCMU_H2O_NEITHER),
                    seed_freq_from_req(miss_qos, miss_sem_hot, miss_is_prefetch),
                    8'd0)) begin
                stat_l2_casu_pollution_block_cnt <= stat_l2_casu_pollution_block_cnt + 32'd1;
              end
              if (make_pressure_bonus(miss_utility_score, miss_marginal_active, miss_service_issue_boost) != 3'd0) begin
                stat_l2_casu_pressure_bonus_cnt <= stat_l2_casu_pressure_bonus_cnt + 32'd1;
              end
              if (UTILITY_MARGINAL_REPL_EN && !miss_compress_allow && (miss_utility_score >= SCORE_W'(8'hD8))) begin
                stat_l2_casu_comp_guard_cnt <= stat_l2_casu_comp_guard_cnt + 32'd1;
              end
              if (miss_sem_hot) begin
                stat_l2_sem_hot_fill_cnt <= stat_l2_sem_hot_fill_cnt + 32'd1;
              end
`endif
              if (fill_req_lossy_fill) begin
                comp_mem[fill_idx]  <= compress_data(mem_rdata, fill_req_comp_bits);
                comp_bits_mem[fill_idx] <= fill_req_comp_bits;
                lossy_mem[fill_idx] <= 1'b1;
`ifndef SYNTHESIS
                stat_l2_fill_lossy_taken_cnt <= stat_l2_fill_lossy_taken_cnt + 32'd1;
                stat_l2_comp_fill_cnt <= stat_l2_comp_fill_cnt + 32'd1;
                stat_l2_comp_error_accum <= stat_l2_comp_error_accum + 32'(max_err_for_bits(fill_req_comp_bits) * BYTE_W);
`endif
              end else begin
                data_mem[fill_idx]  <= mem_rdata;
                comp_bits_mem[fill_idx] <= 3'd4;
                lossy_mem[fill_idx] <= 1'b0;
              end
`ifndef SYNTHESIS
              stat_l2_read_miss_cnt <= stat_l2_read_miss_cnt + 32'd1;
              stat_l2_fill_cnt      <= stat_l2_fill_cnt + 32'd1;
              stat_hbm_read_req_cnt <= stat_hbm_read_req_cnt + 32'd1;
              if (!fill_req_lossy_fill &&
                  LOSSY_COMPRESS_EN &&
                  (miss_is_prefetch || (miss_qos <= COMPRESS_QOS_TH)) &&
                  (miss_sem_hot || miss_victim_protect || miss_hh_protect || miss_recent_keep)) begin
                stat_l2_comp_blocked_hot_cnt <= stat_l2_comp_blocked_hot_cnt + 32'd1;
              end
`endif
            end else begin
`ifndef SYNTHESIS
              stat_l2_read_miss_cnt <= stat_l2_read_miss_cnt + 32'd1;
              stat_hbm_read_req_cnt <= stat_hbm_read_req_cnt + 32'd1;
              stat_l2_read_fill_bypass_cnt <= stat_l2_read_fill_bypass_cnt + 32'd1;
              if (casu_miss_admission_bypass) begin
                stat_l2_casu_admission_bypass_cnt <= stat_l2_casu_admission_bypass_cnt + 32'd1;
              end
`endif
            end
          end
        end
      if (req_we) begin
        if (write_hit) begin
          line_touch_epoch[w_hit_idx] <= epoch_ctr;
          line_freq[w_hit_idx] <= sat_add4(
            line_freq[w_hit_idx],
            freq_step_from_req(req_qos, req_sem_hot, 1'b0)
          );
          line_sem_hot[w_hit_idx] <= line_sem_hot[w_hit_idx] | req_sem_hot;
          line_hh_protect_mem[w_hit_idx] <= line_hh_protect_mem[w_hit_idx] | req_hh_protect;
          line_recent_keep_mem[w_hit_idx] <= line_recent_keep_mem[w_hit_idx] | req_recent_keep;
          line_utility_score_mem[w_hit_idx] <= merge_utility_score(line_utility_score_mem[w_hit_idx], req_utility_score);
          line_marginal_keep_mem[w_hit_idx] <= line_marginal_keep_mem[w_hit_idx] |
            make_marginal_keep(req_utility_score,
              req_marginal_active,
              req_hh_protect || (req_h2o_class == KCMU_H2O_BOTH) || (req_h2o_class == KCMU_H2O_HEAVY_ONLY),
              1'b0,
              line_freq[w_hit_idx],
              epoch_ctr - line_touch_epoch[w_hit_idx]);
          line_pollution_risk_mem[w_hit_idx] <=
            make_pollution_risk(req_utility_score,
              req_marginal_active,
              req_hh_protect || req_recent_keep || (req_h2o_class != KCMU_H2O_NEITHER),
              line_freq[w_hit_idx],
              epoch_ctr - line_touch_epoch[w_hit_idx]);
          line_pressure_bonus_mem[w_hit_idx] <= 3'd0;
          if (req_h2o_class > line_h2o_class_mem[w_hit_idx]) begin
            line_h2o_class_mem[w_hit_idx] <= req_h2o_class;
          end
          dirty_mem[w_hit_idx] <= 1'b1;
            if (req_lossy_fill) begin
              comp_mem[w_hit_idx]  <= compress_data(req_wdata, req_comp_bits);
              comp_bits_mem[w_hit_idx] <= req_comp_bits;
              lossy_mem[w_hit_idx] <= 1'b1;
`ifndef SYNTHESIS
              stat_l2_comp_fill_cnt <= stat_l2_comp_fill_cnt + 32'd1;
              stat_l2_comp_error_accum <= stat_l2_comp_error_accum + 32'(max_err_for_bits(req_comp_bits) * BYTE_W);
`endif
            end else begin
            data_mem[w_hit_idx]  <= req_wdata;
            comp_bits_mem[w_hit_idx] <= 3'd4;
            if (lossy_mem[w_hit_idx]) begin
`ifndef SYNTHESIS
              stat_l2_comp_promote_cnt <= stat_l2_comp_promote_cnt + 32'd1;
`endif
            end
            lossy_mem[w_hit_idx] <= 1'b0;
          end
`ifndef SYNTHESIS
          stat_l2_write_hit_cnt <= stat_l2_write_hit_cnt + 32'd1;
`endif
        end else begin
          if (VB_ENABLE && vb_write_hit) begin
`ifndef SYNTHESIS
            stat_l2_vb_write_hit_cnt <= stat_l2_vb_write_hit_cnt + 32'd1;
`endif
          end

          if (write_alloc_enable) begin
            if (valid_mem[w_idx]) begin
              if (VB_ENABLE && !VB_CLEAN_READONLY_EN && vb_valid_mem[vb_walloc_idx] && !vb_write_hit) begin
                if ((vb_dirty_mem[vb_walloc_idx] ||
                     should_spill_compress(
                       vb_dirty_mem[vb_walloc_idx],
                       vb_sem_hot_mem[vb_walloc_idx],
                       vb_hh_protect_mem[vb_walloc_idx],
                       vb_recent_keep_mem[vb_walloc_idx],
                       vb_h2o_class_mem[vb_walloc_idx],
                       vb_lossy_mem[vb_walloc_idx],
                       (req_sem_hot || req_victim_protect || req_hh_protect || req_recent_keep),
                       req_qos,
                       req_is_prefetch
                     )) && !wb_push_req) begin
                  wb_push_req = 1'b1;
                  wb_push_addr = vb_tag_mem[vb_walloc_idx];
                  wb_push_data = line_export_data(
                    vb_data_mem[vb_walloc_idx],
                    vb_comp_mem[vb_walloc_idx],
                    vb_comp_bits_mem[vb_walloc_idx],
                    vb_lossy_mem[vb_walloc_idx]
                  );
                  wb_push_is_comp = should_spill_compress(
                    vb_dirty_mem[vb_walloc_idx],
                    vb_sem_hot_mem[vb_walloc_idx],
                    vb_hh_protect_mem[vb_walloc_idx],
                    vb_recent_keep_mem[vb_walloc_idx],
                    vb_h2o_class_mem[vb_walloc_idx],
                    vb_lossy_mem[vb_walloc_idx],
                    (req_sem_hot || req_victim_protect || req_hh_protect || req_recent_keep),
                    req_qos,
                    req_is_prefetch
                  );
                  wb_push_comp_bits = vb_lossy_mem[vb_walloc_idx] ? vb_comp_bits_mem[vb_walloc_idx] :
                                      choose_comp_bits(req_qos, req_is_prefetch);
                  wb_push_src_write_vb_evict = 1'b1;
                end
`ifndef SYNTHESIS
                stat_l2_vb_evict_cnt <= stat_l2_vb_evict_cnt + 32'd1;
`endif
              end
              if (VB_ENABLE && !VB_CLEAN_READONLY_EN) begin
                vb_valid_mem[vb_walloc_idx] <= 1'b1;
                vb_tag_mem[vb_walloc_idx] <= compose_addr_from_line(tag_mem[w_idx], w_idx);
                vb_dirty_mem[vb_walloc_idx] <= dirty_mem[w_idx];
                vb_sem_hot_mem[vb_walloc_idx] <= line_sem_hot[w_idx];
                vb_hh_protect_mem[vb_walloc_idx] <= line_hh_protect_mem[w_idx];
                vb_recent_keep_mem[vb_walloc_idx] <= line_recent_keep_mem[w_idx];
                vb_h2o_class_mem[vb_walloc_idx] <= line_h2o_class_mem[w_idx];
                vb_utility_score_mem[vb_walloc_idx] <= line_utility_score_mem[w_idx];
                vb_marginal_keep_mem[vb_walloc_idx] <= line_marginal_keep_mem[w_idx];
                vb_pollution_risk_mem[vb_walloc_idx] <= line_pollution_risk_mem[w_idx];
                vb_pressure_bonus_mem[vb_walloc_idx] <= line_pressure_bonus_mem[w_idx];
                vb_freq_mem[vb_walloc_idx] <= line_freq[w_idx];
                vb_touch_epoch_mem[vb_walloc_idx] <= line_touch_epoch[w_idx];
                if (lossy_mem[w_idx]) begin
                  vb_comp_mem[vb_walloc_idx] <= comp_mem[w_idx];
                  vb_comp_bits_mem[vb_walloc_idx] <= comp_bits_mem[w_idx];
                  vb_lossy_mem[vb_walloc_idx] <= 1'b1;
                end else begin
                  vb_data_mem[vb_walloc_idx] <= data_mem[w_idx];
                  vb_comp_bits_mem[vb_walloc_idx] <= 3'd4;
                  vb_lossy_mem[vb_walloc_idx] <= 1'b0;
                end
                vb_rr_ptr <= vb_walloc_idx + VB_IDX_W'(1);
              end else if ((w_victim_dirty ||
                            should_spill_compress(
                              w_victim_dirty,
                              line_sem_hot[w_idx],
                              line_hh_protect_mem[w_idx],
                              line_recent_keep_mem[w_idx],
                              line_h2o_class_mem[w_idx],
                              lossy_mem[w_idx],
                              (req_sem_hot || req_victim_protect || req_hh_protect || req_recent_keep),
                              req_qos,
                              req_is_prefetch
                            )) && !wb_push_req) begin
                wb_push_req = 1'b1;
                wb_push_addr = compose_addr_from_line(tag_mem[w_idx], w_idx);
                wb_push_data = line_export_data(
                  data_mem[w_idx],
                  comp_mem[w_idx],
                  comp_bits_mem[w_idx],
                  lossy_mem[w_idx]
                );
                wb_push_is_comp = should_spill_compress(
                  w_victim_dirty,
                  line_sem_hot[w_idx],
                  line_hh_protect_mem[w_idx],
                  line_recent_keep_mem[w_idx],
                  line_h2o_class_mem[w_idx],
                  lossy_mem[w_idx],
                  (req_sem_hot || req_victim_protect || req_hh_protect || req_recent_keep),
                  req_qos,
                  req_is_prefetch
                );
                wb_push_comp_bits = lossy_mem[w_idx] ? comp_bits_mem[w_idx] :
                                    choose_comp_bits(req_qos, req_is_prefetch);
                wb_push_src_write_direct = 1'b1;
              end
              if (L2_WAYS > 1) begin
                set_rr_way[w_set_idx] <= ~set_rr_way[w_set_idx];
              end
`ifndef SYNTHESIS
              stat_l2_evict_cnt <= stat_l2_evict_cnt + 32'd1;
              stat_l2_evict_capacity_cnt <= stat_l2_evict_capacity_cnt + 32'd1;
              if (w_victim_sem_hot_eff) begin
                stat_l2_evict_sem_hot_victim_cnt <= stat_l2_evict_sem_hot_victim_cnt + 32'd1;
              end
              if (req_qos <= 3'd2) begin
                stat_l2_evict_low_qos_req_cnt <= stat_l2_evict_low_qos_req_cnt + 32'd1;
              end
              if (req_is_prefetch) begin
                stat_l2_evict_prefetch_req_cnt <= stat_l2_evict_prefetch_req_cnt + 32'd1;
              end
              if (VB_ENABLE) begin
                stat_l2_evict_vb_path_cnt <= stat_l2_evict_vb_path_cnt + 32'd1;
              end
              if (line_sem_hot[w_idx]) begin
                stat_l2_sem_hot_evict_cnt <= stat_l2_sem_hot_evict_cnt + 32'd1;
              end
              if (VB_ENABLE) begin
                stat_l2_vb_insert_cnt <= stat_l2_vb_insert_cnt + 32'd1;
              end
`endif
            end else if (VB_ENABLE && vb_write_hit) begin
              vb_valid_mem[vb_write_idx] <= 1'b0;
              vb_dirty_mem[vb_write_idx] <= 1'b0;
              vb_sem_hot_mem[vb_write_idx] <= 1'b0;
              vb_hh_protect_mem[vb_write_idx] <= 1'b0;
              vb_recent_keep_mem[vb_write_idx] <= 1'b0;
              vb_h2o_class_mem[vb_write_idx] <= KCMU_H2O_NEITHER;
              vb_utility_score_mem[vb_write_idx] <= {SCORE_W{1'b0}};
              vb_marginal_keep_mem[vb_write_idx] <= 1'b0;
              vb_pollution_risk_mem[vb_write_idx] <= 1'b0;
              vb_pressure_bonus_mem[vb_write_idx] <= 3'd0;
              vb_freq_mem[vb_write_idx] <= 4'd0;
              vb_touch_epoch_mem[vb_write_idx] <= 8'd0;
              vb_comp_bits_mem[vb_write_idx] <= 3'd4;
              vb_lossy_mem[vb_write_idx] <= 1'b0;
            end

            valid_mem[w_idx] <= 1'b1;
            tag_mem[w_idx]   <= w_tag;
            line_touch_epoch[w_idx] <= epoch_ctr;
            line_freq[w_idx] <= seed_freq_from_req(req_qos, req_sem_hot, 1'b0);
            line_sem_hot[w_idx] <= req_sem_hot;
            line_hh_protect_mem[w_idx] <= req_hh_protect;
            line_recent_keep_mem[w_idx] <= req_recent_keep;
            line_h2o_class_mem[w_idx] <= req_h2o_class;
            line_utility_score_mem[w_idx] <= req_utility_score;
            line_marginal_keep_mem[w_idx] <= make_marginal_keep(
              req_utility_score,
              req_marginal_active,
              req_hh_protect || (req_h2o_class == KCMU_H2O_BOTH) || (req_h2o_class == KCMU_H2O_HEAVY_ONLY),
              1'b0,
              seed_freq_from_req(req_qos, req_sem_hot, 1'b0),
              8'd0);
            line_pollution_risk_mem[w_idx] <= make_pollution_risk(
              req_utility_score,
              req_marginal_active,
              req_hh_protect || req_recent_keep || (req_h2o_class != KCMU_H2O_NEITHER),
              seed_freq_from_req(req_qos, req_sem_hot, 1'b0),
              8'd0);
            line_pressure_bonus_mem[w_idx] <= 3'd0;
            dirty_mem[w_idx] <= 1'b1;
`ifndef SYNTHESIS
            if (valid_mem[w_idx]) begin
              stat_l2_fill_replace_cnt <= stat_l2_fill_replace_cnt + 32'd1;
              stat_l2_lifetime_cycle_sum <= stat_l2_lifetime_cycle_sum + {32'd0, (sim_cycle - line_fill_cycle[w_idx])};
              stat_l2_lifetime_sample_cnt <= stat_l2_lifetime_sample_cnt + 32'd1;
              if ((sim_cycle - line_fill_cycle[w_idx]) < 32'd32) begin
                stat_l2_lifetime_bin_lt32_cnt <= stat_l2_lifetime_bin_lt32_cnt + 32'd1;
              end else if ((sim_cycle - line_fill_cycle[w_idx]) < 32'd128) begin
                stat_l2_lifetime_bin_lt128_cnt <= stat_l2_lifetime_bin_lt128_cnt + 32'd1;
              end else if ((sim_cycle - line_fill_cycle[w_idx]) < 32'd512) begin
                stat_l2_lifetime_bin_lt512_cnt <= stat_l2_lifetime_bin_lt512_cnt + 32'd1;
              end else begin
                stat_l2_lifetime_bin_ge512_cnt <= stat_l2_lifetime_bin_ge512_cnt + 32'd1;
              end
            end else begin
              stat_l2_fill_invalid_cnt <= stat_l2_fill_invalid_cnt + 32'd1;
              stat_l2_valid_cur_cnt <= stat_l2_valid_cur_cnt + 32'd1;
              if ((stat_l2_valid_cur_cnt + 32'd1) > stat_l2_valid_peak_cnt) begin
                stat_l2_valid_peak_cnt <= stat_l2_valid_cur_cnt + 32'd1;
              end
            end
            line_fill_cycle[w_idx] <= sim_cycle;
            if (req_sem_hot) begin
              stat_l2_sem_hot_fill_cnt <= stat_l2_sem_hot_fill_cnt + 32'd1;
            end
`endif
            if (req_lossy_fill) begin
              comp_mem[w_idx]  <= compress_data(req_wdata, req_comp_bits);
              comp_bits_mem[w_idx] <= req_comp_bits;
              lossy_mem[w_idx] <= 1'b1;
`ifndef SYNTHESIS
              stat_l2_comp_fill_cnt <= stat_l2_comp_fill_cnt + 32'd1;
              stat_l2_comp_error_accum <= stat_l2_comp_error_accum + 32'(max_err_for_bits(req_comp_bits) * BYTE_W);
`endif
            end else begin
              data_mem[w_idx]  <= req_wdata;
              comp_bits_mem[w_idx] <= 3'd4;
              lossy_mem[w_idx] <= 1'b0;
            end
`ifndef SYNTHESIS
            stat_l2_write_alloc_cnt <= stat_l2_write_alloc_cnt + 32'd1;
`endif
          end else begin
            if (VB_ENABLE && vb_write_hit) begin
              if (VB_CLEAN_ACTIVE) begin
                vb_valid_mem[vb_write_idx] <= 1'b0;
                vb_dirty_mem[vb_write_idx] <= 1'b0;
                vb_lossy_mem[vb_write_idx] <= 1'b0;
              end else begin
              vb_touch_epoch_mem[vb_write_idx] <= epoch_ctr;
              vb_freq_mem[vb_write_idx] <= sat_add4(
                vb_freq_mem[vb_write_idx],
                freq_step_from_req(req_qos, req_sem_hot, 1'b0)
              );
              vb_sem_hot_mem[vb_write_idx] <= vb_sem_hot_mem[vb_write_idx] | req_sem_hot;
              vb_hh_protect_mem[vb_write_idx] <= vb_hh_protect_mem[vb_write_idx] | req_hh_protect;
              vb_recent_keep_mem[vb_write_idx] <= vb_recent_keep_mem[vb_write_idx] | req_recent_keep;
              vb_utility_score_mem[vb_write_idx] <= merge_utility_score(vb_utility_score_mem[vb_write_idx], req_utility_score);
              if (req_h2o_class > vb_h2o_class_mem[vb_write_idx]) begin
                vb_h2o_class_mem[vb_write_idx] <= req_h2o_class;
              end
              vb_dirty_mem[vb_write_idx] <= 1'b1;
                if (req_lossy_fill) begin
                  vb_comp_mem[vb_write_idx] <= compress_data(req_wdata, req_comp_bits);
                  vb_comp_bits_mem[vb_write_idx] <= req_comp_bits;
                  vb_lossy_mem[vb_write_idx] <= 1'b1;
`ifndef SYNTHESIS
                  stat_l2_comp_fill_cnt <= stat_l2_comp_fill_cnt + 32'd1;
                  stat_l2_comp_error_accum <= stat_l2_comp_error_accum + 32'(max_err_for_bits(req_comp_bits) * BYTE_W);
`endif
                end else begin
                vb_data_mem[vb_write_idx] <= req_wdata;
                vb_comp_bits_mem[vb_write_idx] <= 3'd4;
                if (vb_lossy_mem[vb_write_idx]) begin
`ifndef SYNTHESIS
                  stat_l2_comp_promote_cnt <= stat_l2_comp_promote_cnt + 32'd1;
`endif
                end
                vb_lossy_mem[vb_write_idx] <= 1'b0;
              end
              end
            end
`ifndef SYNTHESIS
            stat_l2_write_noalloc_cnt <= stat_l2_write_noalloc_cnt + 32'd1;
            if (WRITE_ALLOCATE && (req_qos < WRITE_ALLOC_QOS_TH)) begin
              stat_l2_write_qos_bypass_cnt <= stat_l2_write_qos_bypass_cnt + 32'd1;
            end
`endif
          end
        end
      end

      if (VB_ENABLE && !VB_CLEAN_READONLY_EN && vb_bg_idle) begin
        if (vb_valid_mem[vb_bg_idx] && vb_dirty_mem[vb_bg_idx] && !wb_push_req) begin
          if (service_issue_defer_dirty_flush) begin
            vb_bg_ptr <= vb_bg_idx + VB_IDX_W'(1);
`ifndef SYNTHESIS
            stat_l2_vb_dirty_defer_cnt <= stat_l2_vb_dirty_defer_cnt + 32'd1;
`endif
          end else begin
            // Idle-cycle dirty victim flush from VB to bounded writeback queue.
            wb_push_req = 1'b1;
            wb_push_addr = vb_tag_mem[vb_bg_idx];
            wb_push_data = line_export_data(
              vb_data_mem[vb_bg_idx],
              vb_comp_mem[vb_bg_idx],
              vb_comp_bits_mem[vb_bg_idx],
              vb_lossy_mem[vb_bg_idx]
            );
            wb_push_is_comp = vb_lossy_mem[vb_bg_idx];
            wb_push_comp_bits = vb_comp_bits_mem[vb_bg_idx];
            wb_push_src_vb_bg_flush = 1'b1;
            vb_valid_mem[vb_bg_idx] <= 1'b0;
            vb_dirty_mem[vb_bg_idx] <= 1'b0;
            vb_sem_hot_mem[vb_bg_idx] <= 1'b0;
            vb_hh_protect_mem[vb_bg_idx] <= 1'b0;
            vb_recent_keep_mem[vb_bg_idx] <= 1'b0;
            vb_h2o_class_mem[vb_bg_idx] <= KCMU_H2O_NEITHER;
            vb_utility_score_mem[vb_bg_idx] <= {SCORE_W{1'b0}};
            vb_marginal_keep_mem[vb_bg_idx] <= 1'b0;
            vb_pollution_risk_mem[vb_bg_idx] <= 1'b0;
            vb_pressure_bonus_mem[vb_bg_idx] <= 3'd0;
            vb_freq_mem[vb_bg_idx] <= 4'd0;
            vb_touch_epoch_mem[vb_bg_idx] <= 8'd0;
            vb_comp_bits_mem[vb_bg_idx] <= 3'd4;
            vb_lossy_mem[vb_bg_idx] <= 1'b0;
            vb_bg_ptr <= vb_bg_idx + VB_IDX_W'(1);
`ifndef SYNTHESIS
            stat_l2_vb_dirty_flush_cnt <= stat_l2_vb_dirty_flush_cnt + 32'd1;
`endif
          end
        end else if (VB_BG_HOT_PROMOTE_EN &&
                     vb_valid_mem[vb_bg_idx] &&
                     vb_sem_hot_mem[vb_bg_idx] &&
                     vb_bg_can_promote) begin
          // Proactive hot migration: VB -> free L2 line.
          valid_mem[vb_bg_prom_idx] <= 1'b1;
          tag_mem[vb_bg_prom_idx] <= addr_tag(vb_bg_addr);
          dirty_mem[vb_bg_prom_idx] <= vb_dirty_mem[vb_bg_idx];
          line_sem_hot[vb_bg_prom_idx] <= vb_sem_hot_mem[vb_bg_idx];
          line_hh_protect_mem[vb_bg_prom_idx] <= vb_hh_protect_mem[vb_bg_idx];
          line_recent_keep_mem[vb_bg_prom_idx] <= vb_recent_keep_mem[vb_bg_idx];
          line_h2o_class_mem[vb_bg_prom_idx] <= vb_h2o_class_mem[vb_bg_idx];
          line_utility_score_mem[vb_bg_prom_idx] <= vb_utility_score_mem[vb_bg_idx];
          line_marginal_keep_mem[vb_bg_prom_idx] <= vb_marginal_keep_mem[vb_bg_idx];
          line_pollution_risk_mem[vb_bg_prom_idx] <= vb_pollution_risk_mem[vb_bg_idx];
          line_pressure_bonus_mem[vb_bg_prom_idx] <= vb_pressure_bonus_mem[vb_bg_idx];
          line_freq[vb_bg_prom_idx] <= vb_freq_mem[vb_bg_idx];
          line_touch_epoch[vb_bg_prom_idx] <= epoch_ctr;
          if (vb_lossy_mem[vb_bg_idx]) begin
            comp_mem[vb_bg_prom_idx] <= vb_comp_mem[vb_bg_idx];
            comp_bits_mem[vb_bg_prom_idx] <= vb_comp_bits_mem[vb_bg_idx];
            lossy_mem[vb_bg_prom_idx] <= 1'b1;
          end else begin
            data_mem[vb_bg_prom_idx] <= vb_data_mem[vb_bg_idx];
            comp_bits_mem[vb_bg_prom_idx] <= 3'd4;
            lossy_mem[vb_bg_prom_idx] <= 1'b0;
          end
          vb_valid_mem[vb_bg_idx] <= 1'b0;
          vb_dirty_mem[vb_bg_idx] <= 1'b0;
          vb_sem_hot_mem[vb_bg_idx] <= 1'b0;
          vb_hh_protect_mem[vb_bg_idx] <= 1'b0;
          vb_recent_keep_mem[vb_bg_idx] <= 1'b0;
          vb_h2o_class_mem[vb_bg_idx] <= KCMU_H2O_NEITHER;
          vb_utility_score_mem[vb_bg_idx] <= {SCORE_W{1'b0}};
          vb_marginal_keep_mem[vb_bg_idx] <= 1'b0;
          vb_pollution_risk_mem[vb_bg_idx] <= 1'b0;
          vb_pressure_bonus_mem[vb_bg_idx] <= 3'd0;
          vb_freq_mem[vb_bg_idx] <= 4'd0;
          vb_touch_epoch_mem[vb_bg_idx] <= 8'd0;
          vb_comp_bits_mem[vb_bg_idx] <= 3'd4;
          vb_lossy_mem[vb_bg_idx] <= 1'b0;
          vb_bg_ptr <= vb_bg_idx + VB_IDX_W'(1);
          if (L2_WAYS > 1) begin
            set_rr_way[vb_bg_set_idx] <= ~set_rr_way[vb_bg_set_idx];
          end
`ifndef SYNTHESIS
          stat_l2_vb_hot_promote_bg_cnt <= stat_l2_vb_hot_promote_bg_cnt + 32'd1;
          stat_l2_fill_invalid_cnt <= stat_l2_fill_invalid_cnt + 32'd1;
          stat_l2_valid_cur_cnt <= stat_l2_valid_cur_cnt + 32'd1;
          if ((stat_l2_valid_cur_cnt + 32'd1) > stat_l2_valid_peak_cnt) begin
            stat_l2_valid_peak_cnt <= stat_l2_valid_cur_cnt + 32'd1;
          end
`endif
        end else begin
          vb_bg_ptr <= vb_bg_idx + VB_IDX_W'(1);
        end
      end

      if (BG_DIRTY_FLUSH_EN && l2_bg_idle) begin
        if (valid_mem[l2_bg_idx] && dirty_mem[l2_bg_idx] && !wb_push_req) begin
          if (service_issue_defer_dirty_flush) begin
`ifndef SYNTHESIS
            stat_l2_bg_dirty_defer_cnt <= stat_l2_bg_dirty_defer_cnt + 32'd1;
`endif
          end else begin
            // Idle-cycle L2 dirty scrub: persist line while keeping it cache-resident.
            wb_push_req = 1'b1;
            wb_push_addr = l2_bg_addr;
            wb_push_data = line_export_data(
              data_mem[l2_bg_idx],
              comp_mem[l2_bg_idx],
              comp_bits_mem[l2_bg_idx],
              lossy_mem[l2_bg_idx]
            );
            wb_push_is_comp = lossy_mem[l2_bg_idx];
            wb_push_comp_bits = comp_bits_mem[l2_bg_idx];
            wb_push_src_l2_bg_flush = 1'b1;
            dirty_mem[l2_bg_idx] <= 1'b0;
`ifndef SYNTHESIS
            stat_l2_bg_dirty_flush_cnt <= stat_l2_bg_dirty_flush_cnt + 32'd1;
`endif
          end
        end
        l2_bg_ptr <= l2_bg_idx + L2_IDX_W'(1);
      end

      if (wb_push_req) begin
        if ((wbq_count < (WBQ_IDX_W+1)'(WBQ_DEPTH)) || wbq_pop_fire) begin
          wbq_addr_mem[wbq_tail_ptr] <= wb_push_addr;
          wbq_data_mem[wbq_tail_ptr] <= wb_push_data;
          wbq_is_writeback_mem[wbq_tail_ptr] <= wb_push_is_writeback;
          wbq_tail_ptr <= wbq_tail_ptr + WBQ_IDX_W'(1);
          wb_push_ok = 1'b1;
`ifndef SYNTHESIS
          stat_l2_dirty_wb_req_cnt <= stat_l2_dirty_wb_req_cnt + 32'd1;
          if (wb_push_src_direct_wt) begin
            stat_l2_wb_src_direct_wt_cnt <= stat_l2_wb_src_direct_wt_cnt + 32'd1;
            if (service_issue_wb_window_now) begin
              stat_l2_service_issue_wb_src_direct_wt_cnt <= stat_l2_service_issue_wb_src_direct_wt_cnt + 32'd1;
            end
          end
          if (wb_push_src_fill_vb_evict) begin
            stat_l2_wb_src_fill_vb_evict_cnt <= stat_l2_wb_src_fill_vb_evict_cnt + 32'd1;
            if (service_issue_wb_window_now) begin
              stat_l2_service_issue_wb_src_fill_vb_evict_cnt <= stat_l2_service_issue_wb_src_fill_vb_evict_cnt + 32'd1;
            end
          end
          if (wb_push_src_fill_direct) begin
            stat_l2_wb_src_fill_direct_cnt <= stat_l2_wb_src_fill_direct_cnt + 32'd1;
            if (service_issue_wb_window_now) begin
              stat_l2_service_issue_wb_src_fill_direct_cnt <= stat_l2_service_issue_wb_src_fill_direct_cnt + 32'd1;
            end
          end
          if (wb_push_src_write_vb_evict) begin
            stat_l2_wb_src_write_vb_evict_cnt <= stat_l2_wb_src_write_vb_evict_cnt + 32'd1;
            if (service_issue_wb_window_now) begin
              stat_l2_service_issue_wb_src_write_vb_evict_cnt <= stat_l2_service_issue_wb_src_write_vb_evict_cnt + 32'd1;
            end
          end
          if (wb_push_src_write_direct) begin
            stat_l2_wb_src_write_direct_cnt <= stat_l2_wb_src_write_direct_cnt + 32'd1;
            if (service_issue_wb_window_now) begin
              stat_l2_service_issue_wb_src_write_direct_cnt <= stat_l2_service_issue_wb_src_write_direct_cnt + 32'd1;
            end
          end
          if (wb_push_src_vb_bg_flush) begin
            stat_l2_wb_src_vb_bg_flush_cnt <= stat_l2_wb_src_vb_bg_flush_cnt + 32'd1;
            if (service_issue_wb_window_now) begin
              stat_l2_service_issue_wb_src_vb_bg_flush_cnt <= stat_l2_service_issue_wb_src_vb_bg_flush_cnt + 32'd1;
            end
          end
          if (wb_push_src_l2_bg_flush) begin
            stat_l2_wb_src_l2_bg_flush_cnt <= stat_l2_wb_src_l2_bg_flush_cnt + 32'd1;
            if (service_issue_wb_window_now) begin
              stat_l2_service_issue_wb_src_l2_bg_flush_cnt <= stat_l2_service_issue_wb_src_l2_bg_flush_cnt + 32'd1;
            end
          end
          if (wb_push_is_comp) begin
            stat_l2_comp_spill_cnt <= stat_l2_comp_spill_cnt + 32'd1;
            stat_l2_comp_saved_beats <= stat_l2_comp_saved_beats + spill_saved_beats(1'b1, wb_push_comp_bits);
            stat_l2_comp_error_accum <= stat_l2_comp_error_accum + 32'(max_err_for_bits(wb_push_comp_bits) * BYTE_W);
          end
`endif
        end else begin
`ifndef SYNTHESIS
          stat_l2_dirty_wb_drop_cnt <= stat_l2_dirty_wb_drop_cnt + 32'd1;
`endif
        end
      end

      if (wbq_pop_fire) begin
        wbq_head_ptr <= wbq_head_ptr + WBQ_IDX_W'(1);
      end
      if (wbq_pop_fire && !wb_push_ok) begin
        wbq_count <= wbq_count - (WBQ_IDX_W+1)'(1);
      end else if (!wbq_pop_fire && wb_push_ok) begin
        wbq_count <= wbq_count + (WBQ_IDX_W+1)'(1);
      end

      // The clean read-only victim cache never owns dirty data.  A write can
      // conservatively invalidate the small spillway instead of carrying a
      // per-entry write-hit compare path.
      if (VB_CLEAN_ACTIVE && req_we) begin
        vb_valid_mem <= {VB_LINES{1'b0}};
      end
      if (GROUP_FETCH_TO_CVR_EN && req_we) begin
`ifdef KCMU_CFG_FPGA_KILOSCORE_DESC_TARGET_USE_CREDIT_V852
        if ((|(gb_valid_mem & ~gb_used_mem & gb_target_origin_mem)) &&
            (group_target_use_credit != 3'd0)) begin
          group_target_use_credit <= group_target_use_credit - 3'd1;
        end
`endif
        gb_valid_mem <= {GROUP_BUF_LINES{1'b0}};
        gb_used_mem <= {GROUP_BUF_LINES{1'b0}};
        gb_target_origin_mem <= {GROUP_BUF_LINES{1'b0}};
`ifdef KCMU_L2_GROUP_WRGUARD_ACTIVE
        group_recent_wr_valid <= {group_recent_wr_valid[GROUP_RECENT_WR_LINES-2:0], 1'b1};
        for (li = GROUP_RECENT_WR_LINES-1; li > 0; li = li - 1) begin
          group_recent_wr_addr[li] <= group_recent_wr_addr[li-1];
        end
        group_recent_wr_addr[0] <= req_waddr;
`endif
        group_pending <= 1'b0;
        group_fast_issue_allowed <= 1'b0;
        group_slow_issue_allowed <= 1'b0;
        if (!group_issued) begin
          group_extra_cvr_pending <= 1'b0;
          group_native_eqcap_q1_cvr_pending <= 1'b0;
          group_cancel <= 1'b0;
        end
        group_write_quiet_cnt <= 3'd0;
        group_last_miss_valid <= 1'b0;
        group_last_miss_addr <= {ADDR_W{1'b0}};
        group_last_delta_sel <= 2'd0;
        group_stream_conf <= 3'd0;
        group_lane_valid <= {GROUP_FETCH_LANES{1'b0}};
        for (gi = 0; gi < GROUP_FETCH_LANES; gi = gi + 1) begin
          group_lane_last_addr[gi] <= {ADDR_W{1'b0}};
          group_lane_conf[gi] <= 3'd0;
        end
      end else if (GROUP_FETCH_TO_CVR_EN && VB_CLEAN_ACTIVE &&
                   (req_re || rd_req_re || demand_resp_valid || group_resp_valid)) begin
        if (group_write_quiet_cnt != 3'd7) begin
          group_write_quiet_cnt <= group_write_quiet_cnt + 3'd1;
        end
      end else if (!GROUP_FETCH_TO_CVR_EN) begin
        group_write_quiet_cnt <= 3'd0;
      end

      if (req_we && (rw_density_credit <= 4'd13)) begin
        rw_density_credit <= rw_density_credit + 4'd2;
      end else if (!req_we && rd_req_re && (rw_density_credit != 4'd0)) begin
        rw_density_credit <= rw_density_credit - 4'd1;
      end

`ifdef KCMU_CFG_FPGA_KILOSCORE_PREFIX_DENSITY_OWNER_HIDDEN_V762
      if (!req_we && req_re && !req_is_prefetch) begin
        if (req_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) begin
          if (group_prefix_density_credit <= 4'd13) begin
            group_prefix_density_credit <= group_prefix_density_credit + 4'd2;
          end else begin
            group_prefix_density_credit <= 4'd15;
          end
        end else if (group_prefix_density_credit != 4'd0) begin
          group_prefix_density_credit <= group_prefix_density_credit - 4'd1;
        end
      end else if (req_we && (group_prefix_density_credit != 4'd0)) begin
        group_prefix_density_credit <= group_prefix_density_credit - 4'd1;
      end
`endif

`ifndef SYNTHESIS
      if (mem_we) begin
        stat_hbm_write_req_cnt <= stat_hbm_write_req_cnt + 32'd1;
      end

      for (li = 0; li < L2_LINES; li = li + 1) begin
        if (dirty_mem[li]) begin
          dirty_l2_count = dirty_l2_count + 1;
        end
      end
      for (li = 0; li < VB_LINES; li = li + 1) begin
        if (vb_valid_mem[li] && vb_dirty_mem[li]) begin
          dirty_vb_count = dirty_vb_count + 1;
        end
      end
      if (dirty_l2_count > stat_l2_dirty_peak_cnt) begin
        stat_l2_dirty_peak_cnt <= dirty_l2_count;
      end
      if (dirty_vb_count > stat_l2_vb_dirty_peak_cnt) begin
        stat_l2_vb_dirty_peak_cnt <= dirty_vb_count;
      end
`endif
    end
  end
endmodule

